                        [197723] = 
                        {
                            ["subcategory"] = "Flowers",
                            ["name"] = "Apocrypha Stalk, Scryeball",
                            ["quality"] = "Epic",
                            ["icon"] = "/esoui/art/icons/housing_veg_apc_eyeballplant003.dds",
                            ["id"] = 197723,
                            ["description"] = "Feel as if you're being watched? With these bizarre stalks around, you are. Each stalk adds an element of oddball ambience to wherever you choose to plant it.",
                            ["category"] = "Conservatory",
                            ["tags"] = "Animated",
                        },
                        [197722] = 
                        {
                            ["subcategory"] = "Symbolic Decor",
                            ["description"] = "If this were a real portal seal in your abode, you may end up questioning your life choices. As it stands, this replica serves as a marvelous accent in any space.",
                            ["category"] = "Undercroft",
                            ["icon"] = "/esoui/art/icons/housing_apc_inc_portalseal001.dds",
                            ["quality"] = "Epic",
                            ["id"] = 197722,
                            ["name"] = "Apocrypha Portal Seal, Replica",
                        },
                        [197721] = 
                        {
                            ["subcategory"] = "Art",
                            ["description"] = "Place this frieze of the Keeper of Forbidden Knowledge in a prominent place. Perhaps the One Who Knows will look upon you with favor and share some curious bit of information when you most need it. Or, perhaps not.",
                            ["category"] = "Gallery",
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_housinghermaeusmorafrieze001.dds",
                            ["quality"] = "Epic",
                            ["id"] = 197721,
                            ["name"] = "The Lord of Fate and Knowledge Frieze",
                        },
                        [197720] = 
                        {
                            ["subcategory"] = "Banners",
                            ["description"] = "No one can entertain doubts as to your affiliation when you hang this banner featuring the Golden Eye's symbols in your home.",
                            ["category"] = "Parlor",
                            ["icon"] = "/esoui/art/icons/housing_apc_lsb_sombanner003.dds",
                            ["quality"] = "Epic",
                            ["id"] = 197720,
                            ["name"] = "Hermaeus Mora Banner",
                        },
                        [197719] = 
                        {
                            ["subcategory"] = "Yard Ornaments",
                            ["name"] = "Apocrypha Courtyard Pool",
                            ["quality"] = "Epic",
                            ["icon"] = "/esoui/art/icons/housing_apc_inc_scryingpool001.dds",
                            ["id"] = 197719,
                            ["description"] = "The visions one could scry within the pools of Apocrypha sometimes cause a viewer's mind to shatter. Thankfully for you, this particular pool looks stunning, but provides no mind-breaking visions.",
                            ["category"] = "Courtyard",
                            ["tags"] = "Light, Animated",
                        },
                        [197718] = 
                        {
                            ["subcategory"] = "Doorways",
                            ["description"] = "Accents of green on white stone decorate this solid archway. Anything beyond it must surely be worth seeing given its elegantly dramatic appearance.",
                            ["category"] = "Structures",
                            ["icon"] = "/esoui/art/icons/housing_tlv_str_housingnechighdoorframe001.dds",
                            ["quality"] = "Epic",
                            ["id"] = 197718,
                            ["name"] = "Necrom Archway",
                        },
                        [197717] = 
                        {
                            ["subcategory"] = "Display",
                            ["name"] = "Apocrypha Altar, Lighted",
                            ["quality"] = "Epic",
                            ["icon"] = "/esoui/art/icons/housing_apc_exc_housingaltarinterior001.dds",
                            ["id"] = 197717,
                            ["description"] = "Some scholars of Apocrypha claim that if you meditate at one of its altars, a stray piece of lost knowledge may find its way into your mind. Will this work in your home? Probably not, but you'd look suitably impressive while meditating.",
                            ["category"] = "Gallery",
                            ["tags"] = "Light, Interactable",
                        },
                        [197716] = 
                        {
                            ["subcategory"] = "Boulders and Large Rocks",
                            ["name"] = "Crystalline Mind Barrier, Replica",
                            ["quality"] = "Epic",
                            ["icon"] = "/esoui/art/icons/housing_uni_str_crystalmindwall001.dds",
                            ["id"] = 197716,
                            ["description"] = "Replicated painstakingly via rough description by the very few that have returned from the nightmare realms of Vaermina, this barrier is a reminder of a dark and challenging mind-realm far from the light of day.",
                            ["category"] = "Conservatory",
                            ["tags"] = "Interactable",
                        },
                        [197715] = 
                        {
                            ["subcategory"] = "Symbolic Decor",
                            ["description"] = "Raised only to venerate ancestors that have shaped the very fabric of a family line. Ensure your forbearers are pleased by making this classic stele the focal piece of your own shrine.",
                            ["category"] = "Undercroft",
                            ["icon"] = "/esoui/art/icons/housing_tlv_fur_necstele001.dds",
                            ["quality"] = "Legendary",
                            ["id"] = 197715,
                            ["name"] = "Necrom Stele, Ceremonial",
                        },
                        [197713] = 
                        {
                            ["subcategory"] = "Rugs and Carpets",
                            ["description"] = "This is a standard house item.",
                            ["category"] = "Parlor",
                            ["icon"] = "/esoui/art/icons/housing_tlv_inc_necrug003.dds",
                            ["quality"] = "Superior",
                            ["id"] = 197713,
                            ["name"] = "Tribunal Rug",
                        },
                        [197712] = 
                        {
                            ["subcategory"] = "Maps",
                            ["description"] = "\"Mapping Apocrypha and expecting the result to help anyone else is foolish. Instead consider the map to be more of a visual guide to the cartographer's experiences there—unique to them alone.\"—Excerpt from an unknown Cipher's Journal",
                            ["category"] = "Library",
                            ["icon"] = "/esoui/art/icons/housing_gen_inc_mappropsapocrypha001.dds",
                            ["quality"] = "Fine",
                            ["id"] = 197712,
                            ["name"] = "Antique Map of Apocrypha",
                        },
                        [197702] = 
                        {
                            ["subcategory"] = "Remains",
                            ["description"] = "Faithful of Mora believe that the fossils embedded across the realm of Apocrypha are remnants of another place, another realm, the origin point of the Daedric Prince of Knowledge. Certainly, they correspond to no creatures native to Tamriel.",
                            ["category"] = "Undercroft",
                            ["icon"] = "/esoui/art/icons/housing_tre_apc_fossiltree012.dds",
                            ["quality"] = "Superior",
                            ["id"] = 197702,
                            ["name"] = "Apocrypha Fossil, Worm",
                        },
                        [197701] = 
                        {
                            ["subcategory"] = "Remains",
                            ["description"] = "Lovers of large fossils, rejoice! This enormous nautilus fossil can serve as the backdrop for your next outdoor gathering.",
                            ["category"] = "Undercroft",
                            ["icon"] = "/esoui/art/icons/housing_rok_apc_nautilus003.dds",
                            ["quality"] = "Superior",
                            ["id"] = 197701,
                            ["name"] = "Apocrypha Fossil, Nautilus",
                        },
                        [197700] = 
                        {
                            ["subcategory"] = "Remains",
