                        [171386] = 
                        {
                            ["subcategory"] = "Banners",
                            ["name"] = "Reachfolk Banner, Markarth",
                            ["quality"] = "Superior",
                            ["icon"] = "/esoui/art/icons/housing_skr_ext_rchfortbanner002.dds",
                            ["id"] = 171386,
                            ["description"] = "This is a large house item.",
                            ["category"] = "Parlor",
                            ["tags"] = "Animated",
                        },
                        [171387] = 
                        {
                            ["subcategory"] = "Banners",
                            ["name"] = "Nighthollow Banner",
                            ["quality"] = "Epic",
                            ["icon"] = "/esoui/art/icons/housing_skr_lsb_markknighthollowvampiresigilsmall001.dds",
                            ["id"] = 171387,
                            ["description"] = "The banners of the Nighthollow clan have clung to the walls of their crumbling empire for thousands of years. May this one serve you equally as long!",
                            ["category"] = "Parlor",
                            ["tags"] = "Animated",
                        },
                        [171388] = 
                        {
                            ["subcategory"] = "Machinery",
                            ["description"] = "\"Dwemer devices are precise instruments. Usually. This, however, appears to emit tonal forces in a torrent. Catastrophically dangerous. Never turn it on. If there were a control mechanism, maybe, but I can't fathom what could tune it.\"—Neramo",
                            ["category"] = "Workshop",
                            ["icon"] = "/esoui/art/icons/housing_skr_inc_marktonalcascade001.dds",
                            ["quality"] = "Epic",
                            ["id"] = 171388,
                            ["name"] = "Dwarven Tonal Cascade",
                        },
                        [171389] = 
                        {
                            ["subcategory"] = "Machinery",
                            ["description"] = "Though its pronged receptacle stands empty, this pillar once housed some form of Dwarven stone or crystal.",
                            ["category"] = "Workshop",
                            ["icon"] = "/esoui/art/icons/housing_skr_str_markiintretractpillar001.dds",
                            ["quality"] = "Epic",
                            ["id"] = 171389,
                            ["name"] = "Dwarven Crystal Receptacle",
                        },
                        [171390] = 
                        {
                            ["subcategory"] = "Symbolic Decor",
                            ["description"] = "This totem sees use only in places where Reach clans intend to set up camp for more than a few weeks or around Markarth. Some witches claim that subversive uses for this totem abound among bloodthirstier clans.",
                            ["category"] = "Undercroft",
                            ["icon"] = "/esoui/art/icons/housing_skr_exc_markalchemytotem001.dds",
                            ["quality"] = "Superior",
                            ["id"] = 171390,
                            ["name"] = "Reachwitch Protective Totem",
                        },
                        [171391] = 
                        {
                            ["subcategory"] = "Sacred Pieces",
                            ["description"] = "The bones, twigs, and hide that make up this effigy all receive blood-blessings from the clan's witchfolk, who claim it sends spirits with ill intentions back to plague their erstwhile masters.",
                            ["category"] = "Undercroft",
                            ["icon"] = "/esoui/art/icons/housing_skr_ext_rchforteffigy001.dds",
                            ["quality"] = "Epic",
                            ["id"] = 171391,
                            ["name"] = "Reach Effigy of Turnabout",
                        },
                        [171392] = 
                        {
                            ["subcategory"] = "Symbolic Decor",
                            ["description"] = "\"I would ask the scholar who wrote 'I discovered Falmer mark their territory with such totems' more about this ill-scented column and these Falmer she mentions, but she died after penning this entry in her journal. How inconvenient.\"—Scholar Tuintaatel",
                            ["category"] = "Undercroft",
                            ["icon"] = "/esoui/art/icons/housing_skr_str_fmrtotemlarge001.dds",
                            ["quality"] = "Superior",
                            ["id"] = 171392,
                            ["name"] = "Falmer Totem of Dominance",
                        },
                        [171393] = 
                        {
                            ["subcategory"] = "Symbolic Decor",
                            ["description"] = "\"Above us, the limbs stretch to the sky. Below us, the roots spread throughout the ground. Where both meet in this tree, place your bone offerings. Renew them with oils after every rain or the tree's spirit will seek your doom.\"—Reachwitch Eoinellgen",
                            ["category"] = "Undercroft",
                            ["icon"] = "/esoui/art/icons/housing_skr_ext_rchforteffigy002.dds",
                            ["quality"] = "Superior",
                            ["id"] = 171393,
                            ["name"] = "Tree, Reach Totem",
                        },
                        [171394] = 
                        {
                            ["subcategory"] = "Enchanted Lights",
                            ["name"] = "Dwarven Stand, Void Crystal",
                            ["quality"] = "Legendary",
                            ["icon"] = "/esoui/art/icons/housing_skr_inc_voidpocketshard001.dds",
                            ["id"] = 171394,
                            ["description"] = "\"Admittedly, I do love shiny things—perhaps too much given my time spent, ahem, among guards shall we say—but something about this stone makes me feel ill at ease. What were those barmy Dwarves up to with this?\"—Gorthuth, Dwarven Ruins Delver",
                            ["category"] = "Lighting",
                            ["tags"] = "Light, Interactable, Visual FX",
                        },
                        [171395] = 
                        {
                            ["subcategory"] = "Machinery",
                            ["description"] = "\"By Dagon's fiery arse, the aetheric stones in this Dwarven device simply will not budge. What are they for? Don't care. But by Zen, I can't lug this entire piece of metal out of here right now. Feh.\"—Gorthuth, Dwarven Ruins Delver",
                            ["category"] = "Workshop",
                            ["icon"] = "/esoui/art/icons/housing_skr_lsb_markaethericbeacon001.dds",
                            ["quality"] = "Legendary",
                            ["id"] = 171395,
                            ["name"] = "Dwarven Beacon, Aetheric",
                        },
                        [171396] = 
                        {
                            ["subcategory"] = "Machinery",
                            ["description"] = "\"This Dwarven gewgaw tethers … something. Trust me, I know plenty about tethers. Can smell 'em on a guard at more than fifty paces away, and this thing reeks of tethers…manacles…that sort of thing. Let's avoid it.\"—Gorthuth, Dwarven Ruins Delver",
                            ["category"] = "Workshop",
                            ["icon"] = "/esoui/art/icons/housing_skr_inc_markmanacle001.dds",
                            ["quality"] = "Epic",
                            ["id"] = 171396,
                            ["name"] = "Dwarven Tonal Manacle",
                        },
