                        },
                        [8192] = 
                        {
                            ["description"] = "\"The cubs trained into steeds by the Potentate in 2E 23 proved so successful that this practice continues today. Seeing one melted my heart—that tail tassel! In their training barding, they walk through Leyawiin's streets each week.\"—Mirannah of Gwylim",
                            ["icon"] = "/esoui/art/icons/pet_potentatebearcub.dds",
                            ["furnitureId"] = 7228,
                            ["id"] = 8192,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Akaviri Potentate Bear Cub",
                        },
                        [8193] = 
                        {
                            ["description"] = "Bred to withstand the winters in the Druadach Mountains, these dogs are favored among the Timberclaw Reach clan. They show deep tenderness to their clan or family members while protecting their territory with ferocity.",
                            ["icon"] = "/esoui/art/icons/pet_saintbrenardvar.dds",
                            ["furnitureId"] = 7229,
                            ["id"] = 8193,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Druadach Mountain Dog",
                        },
                        [8194] = 
                        {
                            ["description"] = "Quiet, tree-shaded lakes attract these blue-purple moths. Legends claim they glide on starlight and rest upon the Moons' reflections in the water. If one follows you away, good luck is said to bless your path.",
                            ["icon"] = "/esoui/art/icons/pet_lunarmothvar2.dds",
                            ["furnitureId"] = 7230,
                            ["id"] = 8194,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Dusklight Lunar Moth",
                        },
                        [8195] = 
                        {
                            ["description"] = "This fastidious little jerboa originated from Orcrest, but recent events saw them scurry away or go into deep hiding among the nooks and crannies of that ill-fated city. With coaxing, one of these delightful little creatures might venture forth with you!",
                            ["icon"] = "/esoui/art/icons/pet_jerboiavar.dds",
                            ["furnitureId"] = 7231,
                            ["id"] = 8195,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Orcrest Jerboa",
                        },
                        [8196] = 
                        {
                            ["description"] = "Who would not want such a cute Breton Terrier trailing behind them, garbed in the red and black of the Ebonheart Pact? Perfidious fools from other alliances, that's who! Blood for the Pact!",
                            ["icon"] = "/esoui/art/icons/pet_bretonterrierep.dds",
                            ["furnitureId"] = 7232,
                            ["id"] = 8196,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Pact Breton Terrier",
                        },
                        [8197] = 
                        {
                            ["description"] = "So many wiggles in this Breton Terrier! And wearing the Aldmeri Dominion colors of yellow and silver? Such a good dog! The best dog! For the Queen!",
                            ["icon"] = "/esoui/art/icons/pet_bretonterrierad.dds",
                            ["furnitureId"] = 7233,
                            ["id"] = 8197,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Dominion Breton Terrier",
                        },
                        [8198] = 
                        {
                            ["description"] = "The blue and silver of the Daggerfall Covenant decorate this adorable Breton Terrier, who wants to sniff all the sniffs while you go to war in Cyrodiil. For King and Covenant!",
                            ["icon"] = "/esoui/art/icons/pet_bretonterrierdc.dds",
                            ["furnitureId"] = 7234,
                            ["id"] = 8198,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Covenant Breton Terrier",
                        },
                        [8199] = 
                        {
                            ["description"] = "When raised from the egg, these small chaurus learn commands extraordinarily well. Some folk insist that carrying the egg near your heart helps the chitterling form an attachment to you, making it less likely to wander off and become a menace to others.",
                            ["icon"] = "/esoui/art/icons/pet_chaurus.dds",
                            ["furnitureId"] = 7235,
                            ["id"] = 8199,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Teacup Chaurus Chitterling",
                        },
                        [8200] = 
                        {
                            ["description"] = "Silver hide and dark gray stripes mark these domesticated boars, which once ran wild around Karthwasten. Their stomachs run on a tight schedule, making them perfect for those who lose track of time. Nothing like waking up to boar snuffles in your ear!",
                            ["icon"] = "/esoui/art/icons/pet_boarvariant.dds",
                            ["furnitureId"] = 7236,
                            ["id"] = 8200,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Karthwasten Silver Boar",
                        },
                        [8201] = 
                        {
                            ["description"] = "\"I'm not sure why my apprentice insists on making pets of gooey creatures, but here we are, looking at a smaller void rot. So far, it seems the sleeping potion keeps it tractable. So far. Those black tendrils concern me, however.\"—Aleri Andalor",
                            ["icon"] = "/esoui/art/icons/pet_voidrot.dds",
                            ["furnitureId"] = 7237,
                            ["id"] = 8201,
                            ["category"] = "Exotic",
                            ["hint"] = "Acquired by earning the \"Peered into the Abyss\" achievement in the Reach.",
                            ["name"] = "Somnolent Void Rot",
                        },
                        [10250] = 
                        {
                            ["description"] = "The eye-catching tail pouf of the ringtail jerboa makes for a daring fashion statement especially appreciated by the aristocracy of High Isle. It's also, of course, used for balance.",
                            ["icon"] = "/esoui/art/icons/pet_birchghostjerboa.dds",
                            ["furnitureId"] = 8287,
                            ["id"] = 10250,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ringtail Jerboa",
                        },
                        [10251] = 
                        {
                            ["description"] = "\"See the crab's big tidepool eyes? Delicious. Their big claws that can fell saplings with one snip? The meat inside is as juicy as the fruit about to drop off a tree. Trust me. Keep one of these around in case you need a snack.\"—Xoko, Hee-Tepsleel Chef",
                            ["icon"] = "/esoui/art/icons/pet_hermitcrab.dds",
                            ["furnitureId"] = 8288,
                            ["id"] = 10251,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Hermit Crab",
                        },
                        [10252] = 
                        {
                            ["description"] = "\"My study of pangrits have provided few clues as to their origin. Their young don't possess the spikes of the adults, and their hide is supple like velvet. I could almost hug one of these smaller versions! Almost.\"—Sadia Vonius, Student",
                            ["icon"] = "/esoui/art/icons/pet_xitahrannymph.dds",
                            ["furnitureId"] = 8289,
                            ["id"] = 10252,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Pangrit Nymphling",
                        },
                        [10253] = 
                        {
                            ["description"] = "\"Some claim the Hadolids created the pangrits somehow. I suspect they simply tamed these spiky beasts. If they'd made them, they'd be smarter. If a pangrit wants something, they poke you. Learn quickly how to tell what they want!\"—Saissula, Stablemaster",
                            ["icon"] = "/esoui/art/icons/mount_xitahranterror.dds",
                            ["furnitureId"] = 8290,
                            ["id"] = 10253,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Turquoise War Pangrit",
                        },
                        [10254] = 
                        {
                            ["description"] = "Bred by savvy Wayrest stablehands to handle heavy loads, these horses can carry more than one rider. The saddle, crafted by leatherworker Amal, provides both riders with stability while making for an easy ride on the animal.",
                            ["icon"] = "/esoui/art/icons/pet_fleethoofpillion.dds",
                            ["furnitureId"] = 8291,
                            ["id"] = 10254,
                            ["category"] = "Multi-Rider",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["name"] = "Wayrest Vanner Pillion Steed",
                        },
                        [10262] = 
                        {
                            ["description"] = "\"A knight's mount is the extension of her body. Four more legs to push her forward. Two longer ears, to warn her of danger. And a large heart to pump courage through her veins.\"—Gwenifyr Dufort, The Meaning of Chivalry",
                            ["icon"] = "/esoui/art/icons/mount_systresjouster.dds",
                            ["furnitureId"] = 8296,
                            ["id"] = 10262,
                            ["category"] = "Equines",
                            ["hint"] = "|cFFFFFF\nRiding Skill does not affect this mount's appearance.|r",
                            ["name"] = "Grand Joust Destrier",
                        },
                        [8218] = 
                        {
                            ["description"] = "This intimidating horned senche steed wears coal-black barding, making its orange flames stand out in stark contrast. Though none know its origins, the touch of the Deadlands looks to be upon this mount, making it favored by Mehrunes Dagon's adherents.",
                            ["icon"] = "/esoui/art/icons/mount_battlefieldnightmaresenche.dds",
                            ["furnitureId"] = 7238,
                            ["id"] = 8218,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Battlefield Nightmare Senche",
                        },
                        [8219] = 
                        {
                            ["description"] = "\"As we people of the root know, the Hist provides. With this feathered sep adder, it gives us a creature who provides both loyal companionship, as well as keen eyesight and smell. It senses danger before its companion quite often.\"—Daixth",
                            ["icon"] = "/esoui/art/icons/pet_colorfulsepadder.dds",
                            ["furnitureId"] = 7239,
                            ["id"] = 8219,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Jewel-Feathered Sep Adder",
                        },
                        [8220] = 
                        {
                            ["description"] = "Some say you should embrace your nightmares. With this darling little bear cub, you can do exactly that! This trundling bundle of adorable terror might have flaming eyes and fiery paws, but it loves hugs.",
                            ["icon"] = "/esoui/art/icons/pet_nightmarebearcub.dds",
                            ["furnitureId"] = 7240,
                            ["id"] = 8220,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Nightmare Bear Cub",
                        },
                        [8221] = 
                        {
                            ["description"] = "Never be without a snowball to throw at … uh, wait. It appears and goes plop onto the ground? Ah, I see! Ahem. Never be without a friendly snowball buddy as you adventure in Tamriel! Guaranteed to show up in even the hottest climates as if by magic.",
                            ["icon"] = "/esoui/art/icons/pet_snowball.dds",
                            ["furnitureId"] = 7241,
                            ["id"] = 8221,
                            ["category"] = "Exotic",
                            ["hint"] = "|cff0000This pet cannot path when placed as a furnishing.|r",
                            ["name"] = "Snowball Buddy",
                        },
                        [8222] = 
                        {
                            ["description"] = "\"A tale says these green frogs grew as large as Dragons, but envied the Dragons their wings. One pact with Peryite later, and they gained their wings but lost their size. So, best not to make pacts with Peryite. Yet they are amusing companions.\"—Daixth",
                            ["icon"] = "/esoui/art/icons/pet_greendragonfrog.dds",
                            ["furnitureId"] = 7242,
                            ["id"] = 8222,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Viridescent Dragon Frog",
                        },
                        [8223] = 
                        {
                            ["description"] = "Born from wamasu taken from Shadowfen to the Deadlands, or so their vendors claim, these progeny light up with fire instead of lightning. When confronted, their fiery spines project fire, making them fierce defenders of those they choose to follow.",
                            ["icon"] = "/esoui/art/icons/pet_daedricwamasu.dds",
                            ["furnitureId"] = 7243,
                            ["id"] = 8223,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Deadlands Wamasu",
                        },
                        [6181] = 
                        {
                            ["description"] = "With the Baandari Pedlar Camel as your mount, you can go farther between water breaks, plus enjoy the sight of camel spit distressing those unlucky enough to be in range.",
                            ["icon"] = "/esoui/art/icons/mount_baandaripedcamel.dds",
                            ["furnitureId"] = 5961,
                            ["id"] = 6181,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Baandari Pedlar Camel",
                        },
                        [6182] = 
                        {
                            ["description"] = "The well-traveled Baandari Pedlars lend their style to this horse's tack, creating a look any lover of rich hues would die for. Today it can be yours—with no need to die!",
                            ["icon"] = "/esoui/art/icons/mount_baandaripedsteed.dds",
                            ["furnitureId"] = 5962,
                            ["id"] = 6182,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Baandari Pedlar Steed",
                        },
                        [6183] = 
                        {
                            ["description"] = "The Baandari Pedlars find the keen sense of smell that their wolf mounts possess to be a useful source of extra profit. They sometimes offer their services as trackers, but only if other profit is not at hand!",
                            ["icon"] = "/esoui/art/icons/mount_baandaripedwolf.dds",
                            ["furnitureId"] = 5901,
                            ["id"] = 6183,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Baandari Pedlar Brindle Wolf",
                        },
                        [6184] = 
                        {
                            ["description"] = "For years, the Baandari Pedlars have traveled hither and yon, requiring them to train and equip mounts for both comfort and utility. Now you too can ride a colorful guar mount that has that Baandari style!",
                            ["icon"] = "/esoui/art/icons/mounticon_guarbandaari.dds",
                            ["furnitureId"] = 5963,
                            ["id"] = 6184,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Baandari Pedlar Guar",
                        },
                        [6185] = 
                        {
                            ["description"] = "Prone to rumbles and purrs, the Baandari Pedlar Senche-Lion serves as both a mount and a source of warmth on cold evenings around the campfire. Just watch out for that rasping tongue.",
                            ["icon"] = "/esoui/art/icons/mount_baandaripedsenche.dds",
                            ["furnitureId"] = 5902,
                            ["id"] = 6185,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Baandari Pedlar Senche-Lion",
                        },
                        [6186] = 
                        {
                            ["description"] = "The colors exhibited by the Cerulean Scorpion make it a creature sought after by artists and by those who prefer their companions to have a bit of a sting to them.",
                            ["icon"] = "/esoui/art/icons/pet_ceruleanscorpion.dds",
                            ["furnitureId"] = 5875,
                            ["id"] = 6186,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Cerulean Scorpion",
                        },
                        [6187] = 
                        {
                            ["description"] = "In their travels, the Baandari Pedlars have shown off their pack ponies to the delight of children everywhere. Recently they began selling them, and now children put even more pressure on parents to acquire them.",
                            ["icon"] = "/esoui/art/icons/bandaaripedlarpony.dds",
                            ["furnitureId"] = 5876,
                            ["id"] = 6187,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Pedlar Pack Pony",
                        },
                        [6188] = 
                        {
                            ["description"] = "Even the pups receive the full Baandari Pedlar tack treatment! These wolf cubs are often seen chasing each other around those seeking wares from the Pedlars, sometimes tripping up customers until they're trained to know better.",
                            ["icon"] = "/esoui/art/icons/pet_pedlarwolfcub.dds",
                            ["furnitureId"] = 5877,
                            ["id"] = 6188,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Pedlar Pack Wolf Cub",
                        },
                        [6189] = 
                        {
                            ["description"] = "The Baandari Pedlars first used these repurposed mechanized spiders to help retrieve things that got lost in crevices and the like. For the right price, they may sell you one.",
                            ["icon"] = "/esoui/art/icons/pets_baandaripedlarspider.dds",
                            ["furnitureId"] = 5878,
                            ["id"] = 6189,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Pedlar Pack Spider",
                        },
                        [6190] = 
                        {
                            ["description"] = "To prepare their Senche-Lion mounts, the Baandari Pedlars train them with full gear as cubs. Despite the tack, these cubs pounce and play as kittens do.",
                            ["icon"] = "/esoui/art/icons/pet_baandaripedsenchecub.dds",
                            ["furnitureId"] = 5879,
                            ["id"] = 6190,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Pedlar Pack Senche-Lion Cub",
                        },
                        [6191] = 
                        {
                            ["description"] = "Need some happiness in your day? The Alabaster Jerboa is your answer. Its hopping and air-dancing acrobatics can bring a smile to even the grumpiest Dark Elf.",
                            ["icon"] = "/esoui/art/icons/pet_259_alabasterjerboa.dds",
                            ["furnitureId"] = 5880,
                            ["id"] = 6191,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Alabaster Jerboa",
                        },
                        [6192] = 
                        {
                            ["description"] = "Before ice-fire senche-lions become mounts, they start as adorable cubs. But be careful! These cute creatures still require careful handling due to their mix of cold and flame.",
                            ["icon"] = "/esoui/art/icons/sunspiresenchecub.dds",
                            ["furnitureId"] = 5881,
                            ["id"] = 6192,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Sunspire Ice-Fire Senche-Cub",
                        },
                        [6193] = 
                        {
                            ["description"] = "A traditional gift to successful Dragon Hunters, this pup exhibits the same courage that these hunters must have, and also reminds them of the lives they're protecting with their ongoing work.",
                            ["icon"] = "/esoui/art/icons/pet_draghunthuskypup.dds",
                            ["furnitureId"] = 5882,
                            ["id"] = 6193,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Elder Dragon Hunter Wolf Pup",
                        },
                        [6194] = 
                        {
                            ["description"] = "Originally bred to find and kill rats on the docks of the Iliac Bay, the Breton Terrier has found a place in the hearts and minds of many Tamrielics due to its joyful and wriggly behavior.",
                            ["icon"] = "/esoui/art/icons/pet_bretonterrier.dds",
                            ["furnitureId"] = 5883,
                            ["id"] = 6194,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Breton Terrier",
                        },
                        [6195] = 
                        {
                            ["description"] = "\"While carrying out an assignment from Larnatille in my role as Sub-Sapiarch of Domestic Livestock, I created a mount both loyal and majestic. Though the kitten stage is … a bit trying.\" —Corderil of Sunhold",
                            ["icon"] = "/esoui/art/icons/pet_senche-serval-kitten.dds",
                            ["furnitureId"] = 5884,
                            ["id"] = 6195,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Senche-Serval Kitten",
                        },
                        [6196] = 
                        {
                            ["description"] = "The discovery of this \"lynx\" created waves in noble circles when certain of their number realized they could have a feline around without succumbing to fur-based allergies. Now you see them everywhere.",
                            ["icon"] = "/esoui/art/icons/pet_sphynxlynx.dds",
                            ["furnitureId"] = 5885,
                            ["id"] = 6196,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Sphynx Lynx",
                        },
                        [6198] = 
                        {
                            ["description"] = "Originally bred for a reclusive family in Rivenspire, the Indigo Senche-Panther possesses a distinctive black fur that has a purple sheen. Rumors claim that when left to its own devices, it stalks werewolves for amusement.",
                            ["icon"] = "/esoui/art/icons/mount_senchedarkpurple.dds",
                            ["furnitureId"] = 5886,
                            ["id"] = 6198,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Indigo Senche-Panther",
                        },
                        [6199] = 
                        {
                            ["description"] = "Bred for speed and battle, the White Spotted Courser holds a special place in the hearts of war historians due to their prominence as cavalry mounts in the Battle of Dragon Wall.",
                            ["icon"] = "/esoui/art/icons/mount_whitespottedcourser.dds",
                            ["furnitureId"] = 5887,
                            ["id"] = 6199,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "White Spotted Courser",
                        },
                        [6200] = 
                        {
                            ["description"] = "When summoned, this warrior mount of the deathless Anka-Ra mystically amalgamates, drawing sand and strength from the distant Alik'r.",
                            ["icon"] = "/esoui/art/icons/mount_ankarasandcamel.dds",
                            ["furnitureId"] = 5891,
                            ["id"] = 6200,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Anka-Ra Sandcamel",
                        },
                        [6201] = 
                        {
                            ["description"] = "Not only is this vamidium crafted from an Ebony and Ebon Steel alloy, but it also has the form of a Dwarven Spider, making it a must-have for those who prefer dark clothes and darker lives.",
                            ["icon"] = "/esoui/art/icons/mount_ebonydwarvenspider.dds",
                            ["furnitureId"] = 5892,
                            ["id"] = 6201,
                            ["category"] = "Constructs",
                            ["hint"] = "",
                            ["name"] = "Ebony Dwarven Spider",
                        },
                        [6202] = 
                        {
                            ["description"] = "A combination of feline agility with the power of a sandstorm makes this mount both a favored and feared battle companion of the eternally loyal Anka-Ra warriors.",
                            ["icon"] = "/esoui/art/icons/mount_ankarasenchelion.dds",
                            ["furnitureId"] = 5893,
                            ["id"] = 6202,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Anka-Ra Senche-Lion",
                        },
                        [6203] = 
                        {
                            ["description"] = "Ready to rule the arena? With the Arena Gladiator Horse as your steed, you'll do so in flashy style. Each one has received special training from former gladiatorial champions that makes it a practical and dashing choice.",
                            ["icon"] = "/esoui/art/icons/mount_arenagladiatorhorse.dds",
                            ["furnitureId"] = 5894,
                            ["id"] = 6203,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Arena Gladiator Horse",
                        },
                        [6204] = 
                        {
                            ["description"] = "The long-lost Dwemer never spread as far as Elsweyr, but the Baandari Pedlars go everywhere, and will adapt even ancient technology to their uses.",
                            ["icon"] = "/esoui/art/icons/mount_baandaridwarvenspider.dds",
                            ["furnitureId"] = 5895,
                            ["id"] = 6204,
                            ["category"] = "Constructs",
                            ["hint"] = "",
                            ["name"] = "Baandari Dwarven Spider",
                        },
                        [6205] = 
                        {
                            ["description"] = "Ride like the Bringer of Disease and Pestilence that you want to be! This mount features a saddle with the Peryite cult symbol upon it, giving those who spot you a chance to fear their imminent and loathsome doom.",
                            ["icon"] = "/esoui/art/icons/mount_steedoftheafflicted.dds",
                            ["furnitureId"] = 5896,
                            ["id"] = 6205,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Steed of the Afflicted",
                        },
                        [6206] = 
                        {
                            ["description"] = "Born in flame, this senche-lion's temperament matches its fiery appearance. Those who earn its respect, however, gain a mount that can blaze a path through the darkest shadows.",
                            ["icon"] = "/esoui/art/icons/sunspiresenche.dds",
                            ["furnitureId"] = 5897,
                            ["id"] = 6206,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Blazeborn Senche-Lion",
                        },
                        [6207] = 
                        {
                            ["description"] = "Dragon Hunters, take heed! This mount has received elite training that enables it to fearlessly stand fast even in Dragon breath. Some claim that the final, secret test of these mounts is what imbues their eyes with a blue glow.",
                            ["icon"] = "/esoui/art/icons/mount_frostdragonhunterhorse.dds",
                            ["furnitureId"] = 5898,
                            ["id"] = 6207,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Skyterror Dragonslayer Horse",
                        },
                        [6208] = 
                        {
                            ["description"] = "With Dragons on the loose in Elsweyr, a modern cadre of Dragon Hunters have sprung up to hunt them down. Their mounts are sturdy and fearless.",
                            ["icon"] = "/esoui/art/icons/mount_blooddraghunthorse.dds",
                            ["furnitureId"] = 5899,
                            ["id"] = 6208,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Elder Dragon Hunter Horse",
                        },
                        [10306] = 
                        {
                            ["description"] = "When merchants don't arrive through the passes of the Jerall Mountains as expected, groups of searchers head out with these well-trained dogs to find them. More than a few winter caravans have these friendly dogs to thank for their lives.",
                            ["icon"] = "/esoui/art/icons/pet_riellerescuedog.dds",
                            ["furnitureId"] = 8349,
                            ["id"] = 10306,
                            ["category"] = "Domestic",
                            ["hint"] = "Acquired by completing the quest \"Challenges of the Past\" in High Isle.",
                            ["name"] = "Jerall Rescue Dog",
                        },
                        [67] = 
                        {
                            ["description"] = "Native to the upper Ashlands and the slopes of Red Mountain, the perky Amber Ash Hopper is a favorite pet of Dunmer expatriates, as it's relatively low maintenance (it digs its own hole in the ground), and it reminds the Dark Elves of home.",
                            ["icon"] = "/esoui/art/icons/pet_118.dds",
                            ["furnitureId"] = 4175,
                            ["id"] = 67,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Amber Ash Hopper",
                        },
                        [68] = 
                        {
                            ["description"] = "The Deep-Moss Ash Hopper is native to southern Vvardenfell, where it's most commonly found in the fungal-forested uplands and the coastal marshes. They've been adopted as mascot bugs by the Buoyant Armigers, who admire their green carapaces.",
                            ["icon"] = "/esoui/art/icons/pet_125.dds",
                            ["furnitureId"] = 4176,
                            ["id"] = 68,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Deep-Moss Ash Hopper",
                        },
                        [69] = 
                        {
                            ["description"] = "The Ruby Shroom Shalk is a popular house pet on the Telvanni Coast; the sway of its warm red fungus caps as it waddles about in the firelight of a parlor hearth just says \"I'm home\" to Dark Elves of a sentimental nature.",
                            ["icon"] = "/esoui/art/icons/pet_133.dds",
                            ["furnitureId"] = 4177,
                            ["id"] = 69,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ruby Shroom Shalk",
                        },
                        [10311] = 
                        {
                            ["description"] = "Years ago, vermin overran Kvatch during a poor harvest year. To combat this threat to their low winter food supplies, the citizens brought in spotted lynx cubs from breeders. These creatures love freshly hunted vermin, warm hearths, and crusty bread.",
                            ["icon"] = "/esoui/art/icons/pet_kvatchspottedlynxcub.dds",
                            ["furnitureId"] = 8351,
                            ["id"] = 10311,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Highland Spotted Lynx Cub",
                        },
                        [10312] = 
                        {
                            ["description"] = "This spotted lynx was an uncommon sight in the Colovian hills until an enterprising hunter brought back some young to raise. Decades later, these lithe creatures serve well as mounts to those who prefer felines.",
                            ["icon"] = "/esoui/art/icons/mount_kvatchspottedlynx.dds",
                            ["furnitureId"] = 8352,
                            ["id"] = 10312,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Highland Spotted Lynx",
                        },
                        [10313] = 
                        {
                            ["description"] = "\"Clearing wasps from the Betnikh docks falls to our youngest warrior. One such asked a mage to help her befriend the wasps, and she led them away. All but one settled elsewhere, instead choosing to follow her loyally. I see you have one now.\"—Stulga",
                            ["icon"] = "/esoui/art/icons/pet_wasp.dds",
                            ["furnitureId"] = 8366,
                            ["id"] = 10313,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Dockside Paper Wasp",
                        },
                        [10316] = 
                        {
                            ["description"] = "As the weather chills and leaves take on fiery hues, the spirit of this young indrik begins to stir. When a paladin of Jephre performs an act the God of Song and Forest finds worthy, it takes its shaky steps into the world.",
                            ["icon"] = "/esoui/art/icons/pet_harvestfireindrik.dds",
                            ["furnitureId"] = 8367,
                            ["id"] = 10316,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Autumnal Indrik",
                        },
                        [77] = 
                        {
                            ["description"] = "For the Dark Elves, the Shroom Shalk is a companion animal that brings calm and serenity to the Dunmeri home. There's just something so soothing about the way the blue fungal sprouts on its back gently wave and puff out spores as the beast putters about.",
                            ["icon"] = "/esoui/art/icons/pet_122.dds",
                            ["furnitureId"] = 4178,
                            ["id"] = 77,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Blue-Cap Shroom Shalk",
                        },
                        [78] = 
                        {
                            ["description"] = "Thetys Ramarys of Balmora says, \"I love our Bitter Coast Striders, but feel bad that they can't fly very well. So I'm selectively breeding them into a strain that, one day, will dominate the Vvardenfell skies, pursuing its prey for great distances!\"",
                            ["icon"] = "/esoui/art/icons/pet_121.dds",
                            ["furnitureId"] = 4179,
                            ["id"] = 78,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Bitter Coast Cliff Strider",
                        },
                        [10319] = 
                        {
                            ["description"] = "Bretons have a strange practice of letting piebald cats loose in the secret passages of their manor homes. It stems from an ancient, noisy infestation of Sheogorath's never-there beetles. It took years, but the clever felines eventually killed them all.",
                            ["icon"] = "/esoui/art/icons/pet_piebaldcat.dds",
                            ["furnitureId"] = 8380,
                            ["id"] = 10319,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Piebald Cat",
                        },
                        [10320] = 
                        {
                            ["description"] = "The Dragonstar Caravan Company first found these brilliant moths while traveling from Evermore. Though attracted to the campfires, they didn't burn themselves. Instead, they settled on the caravan's goods, then followed them as if guarding them.",
                            ["icon"] = "/esoui/art/icons/pet_twilightslumbermoth.dds",
                            ["furnitureId"] = 8381,
                            ["id"] = 10320,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Orchid Whisper Moth",
                        },
                        [10321] = 
                        {
                            ["description"] = "Once bred for their ability to smell when a grape is perfectly ripe, the Sweetgrape Dragon Frog is now considered an invasive pest. Winemakers go to great lengths to keep the grape-loving frog away from their vineyards.",
                            ["icon"] = "/esoui/art/icons/pet_sweetgrapedragonfrog.dds",
                            ["furnitureId"] = 8382,
                            ["id"] = 10321,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Sweetgrape Dragon Frog",
                        },
                        [10324] = 
                        {
                            ["description"] = "The naivety of the chub loons endears them to druids, whose mission is to protect nature. When the Eldertide landed on Galen and found a new species, they took it as a blessing from Y'ffre and built their villages where the loons make their nests.",
                            ["icon"] = "/esoui/art/icons/pet_fellbraunchubloon.dds",
                            ["furnitureId"] = 8384,
                            ["id"] = 10324,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Fellbraun Chub Loon",
                        },
                        [10325] = 
                        {
                            ["description"] = "\"In retrospect, attempting to add nirnroot to molten silver by using magic was a terrible idea. Now my guarlings and I are covered in silver, blue, and black streaks. Nothing I do will change us back. At least it's attractive!\"—My Experiments, Vol. 5",
                            ["icon"] = "/esoui/art/icons/pet_silverlimnedguar.dds",
                            ["furnitureId"] = 8385,
                            ["id"] = 10325,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Silver-Bellied Guarling",
                        },
                        [86] = 
                        {
                            ["description"] = "This hardy dog was bred for herding sheep in the rugged terrain of Rivenspire.",
                            ["icon"] = "/esoui/art/icons/pet_022.dds",
                            ["furnitureId"] = 4180,
                            ["id"] = 86,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Shornhelm Shepherd",
                        },
                        [88] = 
                        {
                            ["description"] = "Known in Deshaan as loyal pals, the Freckled is the most intelligent breed of guar.",
                            ["icon"] = "/esoui/art/icons/pet_003.dds",
                            ["furnitureId"] = 4181,
                            ["id"] = 88,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Freckled Guar",
                        },
                        [89] = 
                        {
                            ["description"] = "It isn't well known outside financial circles, but somewhere in the basement or sub-level of every bank in Morrowind you'll find the institution's mascot, a sweet old waddling Gold-Cap Shroom Shalk. The symbolism, of course, is obvious.",
                            ["icon"] = "/esoui/art/icons/pet_134.dds",
                            ["furnitureId"] = 4182,
                            ["id"] = 89,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Gold-Cap Shroom Shalk",
                        },
                        [90] = 
                        {
                            ["description"] = "When the gray wolves of Rivenspire howl across the dismal moors of Boralis, it sends a chill down the spine and even the bravest look back over their shoulders—but by Kynareth, their pups sure are cute! And adorably playful into the bargain.",
                            ["icon"] = "/esoui/art/icons/pet_083.dds",
                            ["furnitureId"] = 4183,
                            ["id"] = 90,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Boralis Gray Wolf Pup",
                        },
                        [91] = 
                        {
                            ["description"] = "A favorite household pet in Morrowind, the Striated Pony Guar is a glutton for affection.",
                            ["icon"] = "/esoui/art/icons/pet_025.dds",
                            ["furnitureId"] = 4184,
                            ["id"] = 91,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Striated Pony Guar",
                        },
                        [92] = 
                        {
                            ["description"] = "The Ice Wolves that lope along the White River of northeast Skyrim are associated with both the goddess Mara and the Wolf Totem of Atmora—but it's mighty hard to think of their mythic stature when you're rolling around in the snow with an Ice Wolf Puppy!",
                            ["icon"] = "/esoui/art/icons/pet_085.dds",
                            ["furnitureId"] = 4185,
                            ["id"] = 92,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "White River Ice Wolf Pup",
                        },
                        [93] = 
                        {
                            ["description"] = "With its icy gaze and steaming breath, the frigid Frost Mare seems carved from the very glaciers of Skyrim.",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_l.dds",
                            ["furnitureId"] = 4186,
                            ["id"] = 93,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Frost Mare",
                        },
                        [6246] = 
                        {
                            ["description"] = "This sleek and light-hued mount hails from Verkarth, where some warriors drill both night and day to earn the right to train a young one as a battle mount. Now more widely available, you too can add one to your stable.",
                            ["icon"] = "/esoui/art/icons/senchevariantd.dds",
                            ["furnitureId"] = 5900,
                            ["id"] = 6246,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Verkarth Senche-Lioness",
                        },
                        [103] = 
                        {
                            ["description"] = "Common sights around Solitude, these steadfast and fierce wolves also adorn the heraldry of that city. All of them are, of course, good wolves, and befriending one brings you good fortune in the land of the Nords!",
                            ["icon"] = "/esoui/art/icons/pet_solitudewolf.dds",
                            ["furnitureId"] = 4188,
                            ["id"] = 103,
                            ["category"] = "Exotic",
                            ["hint"] = "Acquired by completing the \"The Vampire Scholar\" quest in Western Skyrim.",
                            ["name"] = "Solitude Silver Wolf",
                        },
                        [104] = 
                        {
                            ["description"] = "Shouldn't an animated skeleton always be a thing of fear and revulsion? This necromantic Pony Guar might change your mind about that!",
                            ["icon"] = "/esoui/art/icons/pet_147.dds",
                            ["furnitureId"] = 4189,
                            ["id"] = 104,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Skeletal Pony Guar",
                        },
                        [10348] = 
                        {
                            ["description"] = "The Ash'abah revere Fennec Foxes for leading lost children back to the tribe. Scholars say that it is more likely the foxes are seeking out the nearest watering hole, which is usually where the tribes are anyway.",
                            ["icon"] = "/esoui/art/icons/pet_bergamafennecfox.dds",
                            ["furnitureId"] = 8405,
                            ["id"] = 10348,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Bergama Fennec Fox",
                        },
                        [10349] = 
                        {
                            ["description"] = "Trails through the thick marshlands outside Gideon change with every passing storm. Hunters in the city bred these dogs to be light enough not to get stuck in the muck and trained their noses to detect new paths of sure footing.",
                            ["icon"] = "/esoui/art/icons/pet_gideontraildog.dds",
                            ["furnitureId"] = 8406,
                            ["id"] = 10349,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Gideon Trail Dog",
                        },
                        [111] = 
                        {
                            ["description"] = "A native of Hammerfell, the Fennec Fox has been domesticated by many of its desert peoples, and makes an alert and loyal pet.",
                            ["icon"] = "/esoui/art/icons/pet_027.dds",
                            ["furnitureId"] = 4193,
                            ["id"] = 111,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Fennec Fox",
                        },
                        [112] = 
                        {
                            ["description"] = "The glowing Purple Daggerback boar is found only in Craglorn in the vicinity of the Spellscar, from which it seems to have absorbed some sort of magical aura.",
                            ["icon"] = "/esoui/art/icons/pet_028.dds",
                            ["furnitureId"] = 4194,
                            ["id"] = 112,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Purple Daggerback",
                        },
                        [113] = 
                        {
                            ["description"] = "With its equine psyche stolen by Daedric magic, the mind-shriven horse is a docile yet terrifying mount.",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_m.dds",
                            ["furnitureId"] = 4195,
                            ["id"] = 113,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Mind-Shriven Horse",
                        },
                        [114] = 
                        {
                            ["description"] = "The Red Pit Wolves of southern Skyrim are known for their aggression and ferocity, and you can see that even in their puppies, adorable as they are. They love to play, but that means play-fighting, so expect to get chewed on as you tussle!",
                            ["icon"] = "/esoui/art/icons/pet_084.dds",
                            ["furnitureId"] = 4196,
                            ["id"] = 114,
