                            ["name"] = "Eri, Barking Banker",
                        },
                        [12414] = 
                        {
                            ["description"] = "Xyn travels the Daedric realms looking for profitable opportunities. They'll happily take your goods (or those of your groupmates) in exchange for common mortal coinage.\n\nAncient bindings prevent them from appearing in Cyrodiil or Battlegrounds.",
                            ["icon"] = "/esoui/art/icons/assistant_xynthemerchant.dds",
