                        },
                        [12420] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in the Lucent Citadel.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranshatteredshard001.dds",
                            ["furnitureId"] = 9864,
                            ["id"] = 12420,
