                        [8376] = 
                        {
                            ["description"] = "A miniature statue of the Scion of Bal",
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_vampirelordsmall001.dds",
                            ["furnitureId"] = 7259,
                            ["id"] = 8376,
                            ["category"] = "General",
