                        },
                        [10912] = 
                        {
                            ["description"] = "\"These large, floof-tailed beasts love to scamper around their home Graht-oak, tucking nuts and seeds into hidey-holes around its roots. Keep an acorn in your pocket, and you've a friend for life—or until it sneaks that acorn away from you!\"—Amridil",
                            ["icon"] = "/esoui/art/icons/pet_grahtwoodsquirrel.dds",
                            ["furnitureId"] = 8682,
                            ["id"] = 10912,
                            ["category"] = "Exotic",
                            ["hint"] = "Acquired by completing the achievement \"Great Oaks from Little Acorns.\"",
                            ["name"] = "Graht-Oak Squirrel",
                        },
                        [12964] = 
                        {
                            ["description"] = "This is a standard house collectible.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranlordhollowjack001.dds",
                            ["furnitureId"] = 10287,
                            ["id"] = 12964,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "",
                            ["name"] = "Bust: Lord Hollowjack",
                        },
                        [12965] = 
                        {
                            ["description"] = "Barbas, Clavicus Vile's faithful companion, loves being a talking dog. Why he wants to stay with you is for him to know and you to never find out. After adding Barbas to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/u43_houseguest_barbas.dds",
                            ["furnitureId"] = 10274,
                            ["id"] = 12965,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Barbas",
                        },
                        [12966] = 
                        {
                            ["description"] = "Self-proclaimed expert adventurer and prolific author Narsis Dren needs some time away from his exploits to write his next thrilling book. After adding Narsis to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/u43_houseguest_narsisdren.dds",
                            ["furnitureId"] = 10288,
                            ["id"] = 12966,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Narsis Dren",
                        },
                        [10919] = 
                        {
                            ["description"] = "\"Swirls of velvety purple. Curved horns. Eyes glowing as they stared down at me. Did I still dream? Had I eaten the wrong mushroom? But no, I was awake. Ah, Vaermina. I delight in serving you, but this gift interrupts my studies.\"—Malven Relas's Journal",
                            ["icon"] = "/esoui/art/icons/mount_ramofdarkdreams.dds",
                            ["furnitureId"] = 8683,
                            ["id"] = 10919,
                            ["category"] = "Cervines",
                            ["hint"] = "Acquired by completing the achievement \"Sane and Clearheaded.\"",
                            ["name"] = "Ram of Dark Dreams",
                        },
                        [8872] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Vateshran Hollows.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialvateshranhollow001.dds",
