                        [8873] = 
                        {
                            ["description"] = "Trophy taken from Maebroogha in honor of an Undaunted victory in Vateshran Hollows.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyvateshranhollow001.dds",
