                        [11062] = 
                        {
                            ["description"] = "A miniature statue of Bendu Olo, Baron-Admiral of the All Flags Navy, as sculpted in High Isle.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_benduolocolossusstatuette001.dds",
                            ["furnitureId"] = 8695,
                            ["id"] = 11062,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Baron-Admiral Olo",
                        },
                        [11063] = 
                        {
                            ["description"] = "A miniature statue of the mysterious Ascendant Lord, who seeks to claim an ancient legacy.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuetteascendantlord001.dds",
                            ["furnitureId"] = 8696,
                            ["id"] = 11063,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Ascendant Lord",
                        },
                        [11064] = 
                        {
                            ["description"] = "A painting by Vaudrie Barthel that captures the play of light and water at an elegant manor in the Systres Archipelago.",
                            ["icon"] = "/esoui/art/icons/housing_sys_inc_housingkeyartpainting003.dds",
                            ["furnitureId"] = 8697,
                            ["id"] = 11064,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Painting: Systres Seaside Manor",
                        },
                        [11065] = 
                        {
                            ["description"] = "\"Druids say the moths are ash made manifest. They leap from the flames of Mount Firesong and flutter away on the breeze. Nonsense! I've seen a moth ignite and then emerge from the coals like a cocoon.\"—Feather-Brained Teeska",
                            ["icon"] = "/esoui/art/icons/pet_phoenixmoth.dds",
                            ["furnitureId"] = 8698,
                            ["id"] = 11065,
                            ["category"] = "Flying Pets",
                            ["hint"] = "Complete the quest \"Guardian of Y'ffelon\" on Galen.",
                            ["name"] = "Phoenix Moth",
                        },
                        [11067] = 
                        {
                            ["description"] = "The first destrier born from a harrowstorm spurned its original rider and galloped away before any present could capture it. This pattern continued for a time, leading many to wonder where they went. Some say they must find new riders—for good or ill.",
                            ["icon"] = "/esoui/art/icons/mount_harrowstormcharger.dds",
                            ["furnitureId"] = 8699,
                            ["id"] = 11067,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Harrowstorm Destrier",
                        },
                        [6972] = 
                        {
                            ["description"] = "\"Clearly the Dwarves liked to travel in pairs now and again, so they built this two-seated animunculi for that purpose. My partner and I adore using it on market day!\"—Delyna Ulvel",
                            ["icon"] = "/esoui/art/icons/mount_groupmountspider.dds",
                            ["furnitureId"] = 7244,
                            ["id"] = 6972,
                            ["category"] = "Multi-Rider",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["name"] = "Duo-Dynamo Dwarven Spider",
                        },
                        [11069] = 
                        {
                            ["description"] = "\"Vile mischief inflicted wounds upon the striped kagouti. 'Lord Vivec must know we have healed this creature who protected his servants. Remembered pain will lead to prevented pain.' And so it befriended the bear and spider.\"—Armiger Tharys's Journal",
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerkagouti.dds",
                            ["furnitureId"] = 8701,
                            ["id"] = 11069,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Buoyant Armiger Kagouti",
                        },
                        [6974] = 
                        {
                            ["description"] = "A miniature statue of a Senche-raht Khajiit and its chosen battlemate.",
                            ["icon"] = "/esoui/art/icons/housing_els_exc_housingstatuesenchesmall001.dds",
                            ["furnitureId"] = 6525,
                            ["id"] = 6974,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Senche-Raht",
                        },
                        [6975] = 
                        {
                            ["description"] = "A miniature statue depicting one of the Manes, the spiritual leaders of the Khajiit.",
                            ["icon"] = "/esoui/art/icons/housing_els_exc_housingstatuemanesmall001.dds",
                            ["furnitureId"] = 6526,
                            ["id"] = 6975,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Mane, Moons-Blessed",
                        },
                        [6976] = 
                        {
                            ["description"] = "A miniature statue of a hero of the Pride of Alkosh, standing triumphantly over her foe.",
                            ["icon"] = "/esoui/art/icons/housing_els_exc_housingsestatueprideofalkosh001.dds",
                            ["furnitureId"] = 6527,
                            ["id"] = 6976,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Pride of Alkosh Hero",
                        },
                        [11073] = 
                        {
                            ["description"] = "With both knightly skills and druidic lore in his repertoire, Sir Stefan Mornard makes for a deadly foe—and a courteous houseguest. After adding Sir Stefan to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/houseguest_sirstefanmornard.dds",
                            ["furnitureId"] = 8818,
                            ["id"] = 11073,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Stefan Mornard",
                        },
                        [11074] = 
                        {
                            ["description"] = "Caska the Senche-raht serves as the first mate on The Perfect Pounce, and she loves time off to pursue other interests—perhaps in your house! After adding Caska to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["icon"] = "/esoui/art/icons/houseguest_caska.dds",
                            ["furnitureId"] = 8817,
                            ["id"] = 11074,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Caska",
                        },
                        [11075] = 
                        {
                            ["description"] = "Vampire hunters such as Mel Adrys travel widely in pursuit of their quarry, and they need places to rest between hunts. Care to host this Dark Elf? After adding Mel to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/houseguest_meladrys.dds",
                            ["furnitureId"] = 8819,
                            ["id"] = 11075,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Mel Adrys",
                        },
                        [11076] = 
                        {
                            ["description"] = "The unchained potential that emanates from the Spellscar twists and changes everything it touches. Who or what drew a quasigriff to Craglorn is still a mystery, but these esoterically beautiful beasts add something new and transcendent to Tamriel.",
                            ["icon"] = "/esoui/art/icons/mount_spellscarquasigriff.dds",
                            ["furnitureId"] = 8705,
                            ["id"] = 11076,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Spellscar Quasigriff",
                        },
                        [11079] = 
                        {
                            ["description"] = "Unlike their more common domesticated cousins, the Firebelly Shalk constantly blazes. Militant Dark Elves sometimes train these Glasscrag Edifice natives to infiltrate the holds of their enemies. Others find them fiery friends on cold Ashlands nights.",
                            ["icon"] = "/esoui/art/icons/pet_firebellyshalk.dds",
                            ["furnitureId"] = 8707,
                            ["id"] = 11079,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Firebelly Shalk",
                        },
                        [11082] = 
                        {
                            ["description"] = "\"Love books, do you? What if they had tentacles and an eye? The gift of flight? Like them as much then? Yes? Oh, delightful! Here, befriend my beloved Philosophicus Aeternum—Philo for short. Expand its knowledge of Nirn.\"—The Archivist of the Lost",
                            ["icon"] = "/esoui/art/icons/pet_fangtome.dds",
                            ["furnitureId"] = 8708,
                            ["id"] = 11082,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Abyssal Tomeshell",
                        },
                        [11097] = 
                        {
                            ["description"] = "Hailing from the pocket realm of Infernace, Pyroclast will holdfast your items (or the items of your groupmates) in the fiery pits of Oblivion. Minor scorching may occur.\n\nAncient bindings prevent them from appearing in Cyrodiil or Battlegrounds.",
                            ["icon"] = "/esoui/art/icons/assistant_pyroclast.dds",
                            ["furnitureId"] = 8997,
                            ["id"] = 11097,
                            ["category"] = "Assistants",
                            ["hint"] = "",
                            ["name"] = "Pyroclast, Infernace Conservator",
                        },
                        [11102] = 
                        {
                            ["description"] = "\"We were all surprised when this senche arrived via envoy. 'A gift from Necrom to an armiger of great repute. Return and aid in the training of more!' And so I ventured to Necrom with a cunning, furry companion.\"—Armiger Tharys's Journal",
                            ["icon"] = "/esoui/art/icons/mount_necromarmigersenche.dds",
                            ["furnitureId"] = 8776,
                            ["id"] = 11102,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Necrom Armiger Senche",
                        },
                        [9057] = 
                        {
                            ["description"] = "Trophy taken from Pyroturge Encratis in honor of an Undaunted victory in Black Drake Villa.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyfirebehemoth001.dds",
                            ["furnitureId"] = 7597,
                            ["id"] = 9057,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Black Drake Villa.",
                            ["name"] = "Trophy: Encratis's Behemoth",
                        },
                        [9058] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Black Drake Villa.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranfirebehemoth001.dds",
                            ["furnitureId"] = 7595,
                            ["id"] = 9058,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Black Drake Villa.",
                            ["name"] = "Bust: Encratis's Behemoth",
                        },
                        [9059] = 
                        {
                            ["description"] = "Trophy taken from Baron Zaudrus in honor of an Undaunted victory in The Cauldron.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophybaron001.dds",
                            ["furnitureId"] = 7598,
                            ["id"] = 9059,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing The Cauldron.",
                            ["name"] = "Trophy: Baron Zaudrus",
                        },
                        [9060] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in The Cauldron.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranbaron001.dds",
                            ["furnitureId"] = 7596,
                            ["id"] = 9060,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran The Cauldron.",
                            ["name"] = "Bust: Baron Zaudrus",
                        },
                        [9062] = 
                        {
                            ["description"] = "Through an Argonian ritual imbued by the Razor Prince's chaos, this former welwa mount seethes with both fury and destruction in conflagration-touched form. Only the strong-willed can control this beast. Perhaps that's you?",
                            ["icon"] = "/esoui/art/icons/mount_sulxanfleshripper.dds",
                            ["furnitureId"] = 7528,
                            ["id"] = 9062,
                            ["category"] = "Heavyweights",
                            ["hint"] = "Complete the \"Xalvakka's Bane\" achievement in the Rockgrove trial.",
                            ["name"] = "Sul-Xan Fleshripper",
                        },
                        [9063] = 
                        {
                            ["description"] = "Though some claim these horses are bred purely for show, the Grand Nibenese Stallion serves as more than just a good luck charm in Leyawiin. They possess a keen intelligence and even temperament—maintaining their composure, even on crowded streets.",
                            ["icon"] = "/esoui/art/icons/mount_grandnibenesehorse.dds",
                            ["furnitureId"] = 7529,
                            ["id"] = 9063,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Grand Nibenese Stallion",
                        },
                        [9064] = 
                        {
                            ["description"] = "\"Though Iron Orcs ate nearly all these gentle camels, the puissant Elinhir mages took them in, allowing them to flourish. With their flowing gaits and downy fur, the sweet-scented creatures became the mages' steed of choice.\"—Garold Farfly",
                            ["icon"] = "/esoui/art/icons/mount_dappledelinhircamel.dds",
                            ["furnitureId"] = 7530,
                            ["id"] = 9064,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Dappled Elinhir Camel",
                        },
                        [9065] = 
                        {
                            ["description"] = "This steed's sunny disposition matches its vibrant multihued coat, making it an excellent horse for a new rider—or one who regularly ventures into treacherous situations. Herds often race the Gold Coast waves, manes flowing freely and tails high.",
                            ["icon"] = "/esoui/art/icons/mount_bayhorse.dds",
                            ["furnitureId"] = 7531,
                            ["id"] = 9065,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Sungold Bay Thoroughbred",
                        },
                        [9066] = 
                        {
                            ["description"] = "\"The stars do not always stay in the sky in Craglorn. They wander, leaping over rocks, and occasionally eat everything you planted in your garden. Those tusking goats can take their shimmering hides somewhere else!\"—Ubri, Belkarth Horticulturalist",
                            ["icon"] = "/esoui/art/icons/mount_celestialram.dds",
                            ["furnitureId"] = 7532,
                            ["id"] = 9066,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Celestial Ram",
                        },
                        [9067] = 
                        {
                            ["description"] = "Once considered a delicacy by Maormer, these iridescent mudcrabs regard every creature a threat, even other mudcrabs. With proper handling, it probably won't snap at your nose. Probably.",
                            ["icon"] = "/esoui/art/icons/pet_wastencoraldalemudcrab.dds",
                            ["furnitureId"] = 7533,
                            ["id"] = 9067,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Wasten Coraldale Mudcrab",
                        },
                        [9068] = 
                        {
                            ["description"] = "While Alik'r natives count this sleeping boar's twitches to foretell of coming sandstorms, others enjoy its penchant to bob along to a drum's beat or squeal until it gains a taste of burgundy wine. Clearly, a boar that favors festivities! Like you, maybe?",
                            ["icon"] = "/esoui/art/icons/pet_goldspineboar.dds",
                            ["furnitureId"] = 7534,
                            ["id"] = 9068,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Goldspine Boar",
                        },
                        [9069] = 
                        {
                            ["description"] = "Ask an Iliac Bay native what they'd miss most about their home and the answer might be the sight of tree-climbing spotted goats. Fortunately for these goat-lovers, the creatures now bleat their way from the bay to climb all manner of trees in new homes.",
                            ["icon"] = "/esoui/art/icons/pet_lliacspottedgoat.dds",
                            ["furnitureId"] = 7535,
                            ["id"] = 9069,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Iliac Spotted Goat",
                        },
                        [9070] = 
                        {
                            ["description"] = "Ready for action? Like Khamira herself, this kitten certainly is! With a roll and a hiss, Ja'khajiit Khamira enters your life, ready to face danger at your side.",
                            ["icon"] = "/esoui/art/icons/pet_khamirasenchecub.dds",
                            ["furnitureId"] = 7536,
                            ["id"] = 9070,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ja'khajiit Khamira",
                        },
                        [9071] = 
                        {
                            ["description"] = "Because these ponies love flowers—to the point of nudging and nickering at any picking them—Nibenese folk started stabling them amid gardens as guardians. Their gentle grace in such a colorful setting make them superb companions for beauty lovers.",
                            ["icon"] = "/esoui/art/icons/pet_nibenesepony.dds",
                            ["furnitureId"] = 7537,
                            ["id"] = 9071,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Nibenese Pony",
                        },
                        [9072] = 
                        {
                            ["description"] = "These cerulean-toned haj mota hatchlings learn to fend for themselves amid ice caves, frozen wastes, and crevasses early on. If you tame one, not only do you have a future terror loyal to you, but you also gain its keen survival instinct in frosty lands.",
                            ["icon"] = "/esoui/art/icons/pet_hajmotavaru30.dds",
                            ["furnitureId"] = 7538,
                            ["id"] = 9072,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Scutecicle Haj Mota",
                        },
                        [9073] = 
                        {
                            ["description"] = "Syliril the trapper caught a sabre cat from the Vale and presented it to Emperor Durcorach in 2E 531. Not to be outdone, Durcorach's beastmaster created a more resplendent cat. He was fed to the hunting dogs when the color washed out of the cat's fur.",
                            ["icon"] = "/esoui/art/icons/pet_valesabercat.dds",
                            ["furnitureId"] = 7539,
                            ["id"] = 9073,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Vale Sabre Cat",
                        },
                        [9074] = 
                        {
                            ["description"] = "The Argonian who named this multihued jelly claims inspiration from the mineral, though some note she was calling it a \"watermelon jelly\" first. Oddly enough, some find its flavor resembles that of the fruit.",
                            ["icon"] = "/esoui/art/icons/pet_tourmalinenetchcalf.dds",
                            ["furnitureId"] = 7540,
                            ["id"] = 9074,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Tourmaline Swamp Jelly",
                        },
                        [9075] = 
                        {
                            ["description"] = "With pincers resembling Dagon's spires and a ferocious multibarbed stinger, these Deadlands natives see most creatures as prey. If you let a softshell baby ride your shoulders until it molts, however, you might just have a friend for life. Might.",
                            ["icon"] = "/esoui/art/icons/pet_deadlandsscorpion.dds",
                            ["furnitureId"] = 7541,
                            ["id"] = 9075,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Deadlands Scorpion",
                        },
                        [9076] = 
                        {
                            ["description"] = "Visiting the Stitches requires a certain amount of fortitude and bravado. Living there, as do these cavies, involves hiding and good timing, as well. Gain a cavy's hard-won trust, and you gain a furry friend seeking neck-snuggles for life.",
                            ["icon"] = "/esoui/art/icons/pet_mara.dds",
                            ["furnitureId"] = 7542,
                            ["id"] = 9076,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Stitchfur Cavy",
                        },
                        [9079] = 
                        {
                            ["description"] = "Watching mighty trees fall to this ram's practice leaps and headbutts led to its eventual domestication by the Nords around its home peak. Bring that power, as well as its love of scaling treacherous heights, into your stable!",
                            ["icon"] = "/esoui/art/icons/mount_eldersbloodram.dds",
                            ["furnitureId"] = 7569,
                            ["id"] = 9079,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Eldersblood Peak Ram",
                        },
                        [9083] = 
                        {
                            ["description"] = "\"Blackwood has some odd creatures. Take the bog dog. Sure, it lives in bogs, but it's no dog. That said, tame it and train it, and it'll follow you anywhere. Just make sure the local guards know it's yours.\"—Grelaith of White Stallion Inn",
                            ["icon"] = "/esoui/art/icons/pet_prowler.dds",
                            ["furnitureId"] = 7570,
                            ["id"] = 9083,
                            ["category"] = "Exotic",
                            ["hint"] = "Acquired by completing the \"Lost in the Wilds\" achievement in Blackwood.",
                            ["name"] = "Bog Dog",
                        },
                        [9088] = 
                        {
                            ["description"] = "The long-suffering Stibbons, Lady Laurent's servant, needs a break. He chose to seek you out, desperate for the peace your home provides. After adding Stibbons to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/hsg_housguest_stibbons.dds",
                            ["furnitureId"] = 7591,
                            ["id"] = 9088,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Stibbons",
                        },
                        [9089] = 
                        {
                            ["description"] = "Erilthel's quest to become Lady Twilight, Tamriel's greatest thief, brought her to your door until her teacher, Seeks-the-Dark, finds her again. After adding Erilthel to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["icon"] = "/esoui/art/icons/hsg_houseguest_erilthel.dds",
                            ["furnitureId"] = 7592,
                            ["id"] = 9089,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Erilthel",
                        },
                        [9090] = 
                        {
                            ["description"] = "The blacksmith, Narboth, dedicated her life to her art after fulfilling an oath to Malacath. Now she seeks a worthy patron. After adding Narboth to your home, you can set her on a path.",
                            ["icon"] = "/esoui/art/icons/hsg_houseguest_blacksmith.dds",
                            ["furnitureId"] = 7593,
                            ["id"] = 9090,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Narboth",
                        },
                        [4996] = 
                        {
                            ["description"] = "The Big-Eared Ginger, a favorite shipboard pet, is just about the most playful kitten in Summerset. Its over-sized sound catchers enable it to hear every tiny motion within range before it pounces upon it.",
                            ["icon"] = "/esoui/art/icons/pet_4996.dds",
                            ["furnitureId"] = 4803,
                            ["id"] = 4996,
                            ["category"] = "Domestic",
                            ["hint"] = "Acquired by finding its seven Runebox Fragments in Karnwasten, and combining them.",
                            ["name"] = "Big-Eared Ginger Kitten",
                        },
                        [11143] = 
                        {
                            ["description"] = "Originally found in volcanic regions in the Dark Elf territories, these insects can be tamed with kind words and cheese. They chirp excitedly when happy or when skittering on slick floors.",
                            ["icon"] = "/esoui/art/icons/pet_fungalashhopper.dds",
                            ["furnitureId"] = 8842,
                            ["id"] = 11143,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Fungal Ash Hopper",
                        },
                        [11146] = 
                        {
                            ["description"] = "Riders of these draugr bears find the dragonscale barding does an exemplary job. There's exactly as much jouncing as you'd expect riding hard on a skeletal ursine's back. Plus, the frost magic imbued within adds a frisson of chill to keep riders alert.",
                            ["icon"] = "/esoui/art/icons/moiunt_dragonscaledraugrbear.dds",
                            ["furnitureId"] = 8843,
                            ["id"] = 11146,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Dragonscale Draugr Bear",
                        },
                        [11147] = 
                        {
                            ["description"] = "\"You may laugh, but like Shor, this fox has added years to my life. Years. Saved me from some giants by outwitting them. Hoisted me by my breeches out of the angry spring waters of the Yorgrim. I breed them now, so I named them.\"—Thorkell",
                            ["icon"] = "/esoui/art/icons/mount_shorsfox.dds",
                            ["furnitureId"] = 8844,
                            ["id"] = 11147,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Shor's Fox",
                        },
                        [11149] = 
                        {
                            ["description"] = "Hermit crabs are famous for making homes out of any discarded shell, but the hermit crabs of Iliac Bay are pickier than most. They choose shells that match their own delicate blue coloration.",
                            ["icon"] = "/esoui/art/icons/pet_iliacbayhermitcrab.dds",
                            ["furnitureId"] = 8850,
                            ["id"] = 11149,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Iliac Bay Hermit Crab",
                        },
                        [11150] = 
                        {
                            ["description"] = "Natives of the Ashlands of Vvardenfell, these flightless, winged reptiles use their pale coloration to hide amidst that barren terrain. They can be trained, however, and follow their owners almost anywhere.",
                            ["icon"] = "/esoui/art/icons/pet_ashencliffstrider.dds",
                            ["furnitureId"] = 8851,
                            ["id"] = 11150,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ashen Cliff Strider",
                        },
                        [11151] = 
                        {
                            ["description"] = "In Telvanni lands, haj mota sometimes lay their eggs in broken catacombs or abandoned cemeteries. The hatchlings acquire a coating of green grave-mold on their shells and become sensitive to the presence of ghosts.",
                            ["icon"] = "/esoui/art/icons/pet_necromhajmota.dds",
                            ["furnitureId"] = 8852,
                            ["id"] = 11151,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ancestral Haj Mota",
                        },
                        [11152] = 
                        {
                            ["description"] = "\"As kits, these rambunctious little trouble-making furballs keep this one on her toes. But their predilection for trouble when young works in your favor—their ability to sense harm is nearly magical. Perfect for messenger work!\"—Tesusah, Stablemaster",
                            ["icon"] = "/esoui/art/icons/mount_autumnmessengerfox.dds",
                            ["furnitureId"] = 8853,
                            ["id"] = 11152,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Autumn Messenger Fox",
                        },
                        [11153] = 
                        {
                            ["description"] = "Legend says a trading caravan was once ambushed on its way to Elden Root. Only one survived. Days later they arrived safely, slung across the back of a majestic white-and-black elk. Perhaps you might make such a friend if you find yourself in need.",
                            ["icon"] = "/esoui/art/icons/mount_eldenrootelk.dds",
                            ["furnitureId"] = 8854,
                            ["id"] = 11153,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Elden Root Elk",
                        },
                        [11159] = 
                        {
                            ["description"] = "The bears of Solstheim have a deep and ancient connection to the All-Maker. When the time comes to serve as a mount to the Skaal, or so the stories go, they enter the corral as mild-mannered as a cub.",
                            ["icon"] = "/esoui/art/icons/mount_all-maker-bear.dds",
                            ["furnitureId"] = 8855,
                            ["id"] = 11159,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "All-Maker's Bear",
                        },
                        [11160] = 
                        {
                            ["description"] = "The harmony of the All-Maker dwells within the chest of this steed. It breathes in the breath and breathes out the wind. In its wake does the earth move, the waters flow, and the sun shine.",
                            ["icon"] = "/esoui/art/icons/mount_allmakerhorse.dds",
                            ["furnitureId"] = 8856,
                            ["id"] = 11160,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "All-Maker's Horse",
                        },
                        [11161] = 
                        {
                            ["description"] = "Unlike other Senche-rahts, Thryn has accepted many riders in its time, though only a few have lasted beyond one battle. This is due to Thryn's habit of testing its rider's mettle with daring maneuvers and wild risks—all in the name of a good story.",
                            ["icon"] = "/esoui/art/icons/mount_all-maker-senche-raht.dds",
                            ["furnitureId"] = 8857,
                            ["id"] = 11161,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "All-Maker's Senche-Raht",
                        },
                        [11162] = 
                        {
                            ["description"] = "\"I don't normally consult on the personal projects of other folk, but it was an honor to study beside you. Whatever gave you the excellent idea to overhaul it in the style of the Skaal?\"—Neramo, in a letter to the artisan known as the Spidersmith",
                            ["icon"] = "/esoui/art/icons/mount_all-maker-dwarven-spider.dds",
                            ["furnitureId"] = 8858,
                            ["id"] = 11162,
                            ["category"] = "Constructs",
                            ["hint"] = "",
                            ["name"] = "All-Maker's Dwarven Spider",
                        },
                        [11163] = 
                        {
                            ["description"] = "\"On a dark and moonless night, raiders stole into the village with plunder in their eyes and violence in their hearts. Their victory was assured, until a lone howl ripped through the icy night air.\" —The All-Maker's Land, translated",
                            ["icon"] = "/esoui/art/icons/mount_all-maker-wolf.dds",
                            ["furnitureId"] = 8859,
                            ["id"] = 11163,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "All-Maker's Wolf",
                        },
                        [11166] = 
                        {
                            ["description"] = "First domesticated around Bonerock Cavern, these miniature mammoths are affectionate pets and follow their masters at a cautious, reasonable gait. Careful—pocket mammoths are known cuddlers.",
                            ["icon"] = "/esoui/art/icons/pet_ebontuskpocketmammoth.dds",
                            ["furnitureId"] = 8860,
                            ["id"] = 11166,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ebontusk Pocket Mammoth",
                        },
                        [11167] = 
                        {
                            ["description"] = "A playful bit of incarnated plasma first summoned by talented arcanists from the strange realms beyond Tamriel, these cubs are mischievous, devoted, and harmless. Well, mostly harmless.",
                            ["icon"] = "/esoui/art/icons/pet_creatiacub.dds",
                            ["furnitureId"] = 8861,
                            ["id"] = 11167,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Chaotic Creatia Cub",
                        },
                        [11168] = 
                        {
                            ["description"] = "These ashen vvardvarks are much adored by Ashlander children. Their long tongues hungrily searching Morrowind's volcanic vents for food make for an entertaining sight.",
                            ["icon"] = "/esoui/art/icons/pet_ashsorrowvvardvark.dds",
                            ["furnitureId"] = 8862,
                            ["id"] = 11168,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ashsorrow Vvardvark",
                        },
                        [11169] = 
                        {
                            ["description"] = "\"The glint of gold I glimpsed when I first spotted these guar made me think I'd found a vein of gold, but no. Instead I found something better—golden guar that match my exquisite taste. One nudged me to ride it, too! We're best friends.\"—Ganalyn Relvan",
                            ["icon"] = "/esoui/art/icons/mount_goldgleamguar.dds",
                            ["furnitureId"] = 8863,
                            ["id"] = 11169,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Goldscale Guar",
                        },
                        [11170] = 
                        {
                            ["description"] = "The artists of Black Heights found a new canvas upon which to share their imagination: senche-servals. The high-quality pigments used on this feline's fur weather much without causing harm, and artists claim the cats preen as they're painted.",
                            ["icon"] = "/esoui/art/icons/mount_oleandersencheserval.dds",
                            ["furnitureId"] = 8864,
                            ["id"] = 11170,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Oleander Senche-Serval",
                        },
                        [7076] = 
                        {
                            ["description"] = "An iniquitous blend of magic created this unhallowed mount. From its baleful glow to the corrupt lanterns that drift about it, this steed serves liches, necromancers, and other wicked beings with undying loyalty.",
                            ["icon"] = "/esoui/art/icons/mount_curseboundradhorse.dds",
                            ["furnitureId"] = 6531,
                            ["id"] = 7076,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Cursebound Lichsteed",
                        },
                        [7077] = 
                        {
                            ["description"] = "This creature is dominated by the oppressive energies of Coldharbour, bound to its master by a vile pledge to Molag Bal. Though it lacks the ability to act without command, the simmering rage bottled inside the beast grows with every passing day.",
                            ["icon"] = "/esoui/art/icons/mount_curseboundradsenche.dds",
                            ["furnitureId"] = 6532,
                            ["id"] = 7077,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Cursebound Sabre Cat Prowler",
                        },
                        [7078] = 
                        {
                            ["description"] = "Zarnor, seeking to quench his insatiable curiosity, took part in experimental rituals that twisted and marked him. Though he still seeks to satiate his ceaseless desire for knowledge, he does so to free himself from servitude to loathsome masters.",
                            ["icon"] = "/esoui/art/icons/mount_curseboundradraht.dds",
                            ["furnitureId"] = 6533,
                            ["id"] = 7078,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Cursebound Senche-Raht Darkfang",
                        },
                        [7079] = 
                        {
                            ["description"] = "\"A fellow named Rigurt requested a 'fortuitudinous' bear mount that 'shines up the face' of a friend. My glowing Gloomspore Bears, with their mora tapinella infusion, barrel through enemies to get a rider to safety. 'Fortuitudinous' galore.\"—Mage Naleldi",
                            ["icon"] = "/esoui/art/icons/mount_gloomsporebear.dds",
                            ["furnitureId"] = 6534,
                            ["id"] = 7079,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Gloomspore Bear",
                        },
                        [7080] = 
                        {
                            ["description"] = "\"A scholar sought a mount that would assume her burdens, so I gave her a Gloomspore Camel. Using scaly pholiota in its creation makes it less likely to complain at any weight it bears, plus gives it a bounce to its step.\"—Mage Naleldil",
                            ["icon"] = "/esoui/art/icons/mount_gloomsporecamel.dds",
                            ["furnitureId"] = 6535,
                            ["id"] = 7080,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Gloomspore Camel",
                        },
                        [7081] = 
                        {
                            ["description"] = "\"A Dunmer mage came by, shaking with rage, and tersely asked for my toughest mount. Though my Gloomspore Guars are a bit nippy, probably due to the extra bleeding crown I used to make them, they have thick fungal hide.\"—Mage Naleldil",
                            ["icon"] = "/esoui/art/icons/mount_gloomsporeguar.dds",
                            ["furnitureId"] = 6536,
                            ["id"] = 7081,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Gloomspore Guar",
                        },
                        [7082] = 
                        {
                            ["description"] = "\"Using giant lichen while creating Gloomspore Horses caused unexpected results. Dauntingly beautiful, these mounts often twitch with nervous caution. So you'll never have to worry about an ambush. Just hold on tight!\"—Mage Naleldil",
                            ["icon"] = "/esoui/art/icons/mount_gloomsporehorse.dds",
                            ["furnitureId"] = 6537,
                            ["id"] = 7082,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Gloomspore Horse",
                        },
                        [7083] = 
                        {
                            ["description"] = "\"When developing my Gloomspore Senche, I utilized thunder fungi—a remarkable mushroom that erupts into spores with a deafening boom! I thought it only fitting to mix one roar with another.\" — Mage Naleldil",
                            ["icon"] = "/esoui/art/icons/mount_gloomsporesenche.dds",
                            ["furnitureId"] = 6538,
                            ["id"] = 7083,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Gloomspore Senche",
                        },
                        [7084] = 
                        {
                            ["description"] = "\"Using hypha facia while creating my Gloomspore Wolves made for some eerie fungal mounts—perfect for anyone who wants to keep others at a distance. Their howls make my own skin prickle.\"—Mage Naleldil",
                            ["icon"] = "/esoui/art/icons/mount_gloomsporewolf.dds",
                            ["furnitureId"] = 6539,
                            ["id"] = 7084,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Gloomspore Wolf",
                        },
                        [11181] = 
                        {
                            ["description"] = "Trophy taken from Ozezan the Inferno in honor of an Undaunted victory in Scrivener's Hall.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyinfernium001.dds",
                            ["furnitureId"] = 8867,
                            ["id"] = 11181,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing the Scrivener's Hall.",
                            ["name"] = "Trophy: Ozezan the Inferno",
                        },
                        [11182] = 
                        {
                            ["description"] = "Trophy taken from Roksa the Warped in honor of an Undaunted victory in Bal Sunnar.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophynixox001.dds",
                            ["furnitureId"] = 8868,
                            ["id"] = 11182,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Bal Sunnar.",
                            ["name"] = "Trophy: Roksa the Warped",
                        },
                        [11183] = 
                        {
                            ["description"] = "You may place the Chronometer in your home. Watching the dial spin causes local perception of time to shift. Until the Chronometer is disturbed, time stands still. Enjoy Sotha Sil's morning sun, Almalexia's mid-day mercy, or the star-spun night of Vivec.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_tribunaltimeofdayclock001.dds",
                            ["furnitureId"] = 8892,
                            ["id"] = 11183,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Chronometer of the Tribunal",
                        },
                        [11194] = 
                        {
                            ["description"] = "\"I wished for ears that could listen to dreams. He gave them to me. How lonely was I that I needed to be part of your most private wonders? Now I wander a forest of waking horrors. Please, take care of him. It was my fault.\"—Note found in Jasper's basket",
                            ["icon"] = "/esoui/art/icons/pet_abyssalbunny.dds",
                            ["furnitureId"] = 8922,
                            ["id"] = 11194,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Abyssal Bunny",
                        },
                        [11196] = 
                        {
                            ["description"] = "Iron Orcs labor hard and long, fight until their dying breath, and train mounts to do the same. So, if you're lucky enough to ride one of their welwas, expect to be pushed to your own limits as your mount keeps going despite all obstacles in its path.",
                            ["icon"] = "/esoui/art/icons/mount_ironorcwelwa.dds",
                            ["furnitureId"] = 8927,
                            ["id"] = 11196,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Iron Orc Welwa",
                        },
                        [11197] = 
                        {
                            ["description"] = "\"Don't muck with another rider's wolf, unless you're ready to meet the All-Maker. These are spirit beasts. They come when summoned, but they're loyal only to their rider. I nearly lost a finger learning that lesson the hard way.\" —Hlokela, Solitude",
                            ["icon"] = "/esoui/art/icons/mount_solstheimshamanwolf.dds",
                            ["furnitureId"] = 8929,
                            ["id"] = 11197,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Solstheim Shiver Wolf",
                        },
                        [11198] = 
                        {
                            ["description"] = "As her name implies, Crafty Lerisa possesses a cunning that keeps her alive. Right now it's telling her to sit tight—perhaps in your home? After adding Crafty Lerisa to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["icon"] = "/esoui/art/icons/houseguest_craftylerisa.dds",
                            ["furnitureId"] = 8931,
                            ["id"] = 11198,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Crafty Lerisa",
                        },
                        [11199] = 
                        {
                            ["description"] = "No job is too small for this Pahmar-raht resistance fighter. That said, he needs a place to rest before his next efforts against his oppressors. After adding J'baanluk to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/houseguest_jbaanluk.dds",
                            ["furnitureId"] = 8930,
                            ["id"] = 11199,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "J'baanluk",
                        },
                        [5056] = 
                        {
                            ["description"] = "Psijic Exemplar mounts theoretically represent the ideal forms such creatures can assume, at which point they transcend the physical and incarnate the mystical. One look at the noble Horse Exemplar, and you know it's true.",
                            ["icon"] = "/esoui/art/icons/mounticon_psijichorse.dds",
                            ["furnitureId"] = 4996,
                            ["id"] = 5056,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Psijic Horse Exemplar",
                        },
                        [5057] = 
                        {
                            ["description"] = "When the Ra Gada first came to Hammerfell from lost Yokuda, they brought their mounts—horses and camels—with them. It was these Yokudan camels that the Psijic monks are said to have taken as models for their Psijic Camel Exemplars.",
                            ["icon"] = "/esoui/art/icons/mounticon_psijiccamel.dds",
                            ["furnitureId"] = 4999,
                            ["id"] = 5057,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Psijic Camel Exemplar",
                        },
                        [5058] = 
                        {
                            ["description"] = "To gaze into the eyes of the Wolf Exemplar is to look into the eyes of every wolf back to the Dawn Era, when the tribes of mortals still huddled around their campfires at night, staring at the glowing eyes of the wolves prowling around the perimeters.",
                            ["icon"] = "/esoui/art/icons/mounticon_psijicwolf.dds",
                            ["furnitureId"] = 4998,
                            ["id"] = 5058,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Psijic Wolf Exemplar",
                        },
                        [5059] = 
                        {
                            ["description"] = "Psijic monks crossing the doubtful terrain of Black Marsh or southern Morrowind are more concerned with the practical matter of safe and sure riding than whether they look dignified and impressive. For these purposes, the Guar Exemplar is unequaled.",
                            ["icon"] = "/esoui/art/icons/mounticon_psijicguar.dds",
                            ["furnitureId"] = 5001,
                            ["id"] = 5059,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Psijic Guar Exemplar",
                        },
                        [5060] = 
                        {
                            ["description"] = "According to Nord legend, bears—like the Nords themselves—originated on the frozen continent of Atmora. And some Nords think that's where the Psijic monks went to find the original model of their Psiiic Bear Exemplar. The Psijic mages aren't saying.",
                            ["icon"] = "/esoui/art/icons/mounticon_psijicbear.dds",
                            ["furnitureId"] = 5000,
                            ["id"] = 5060,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Psijic Bear Exemplar",
                        },
                        [5062] = 
                        {
                            ["description"] = "The Psijic Senche Exemplar is the ultimate physical expression of feline grace and power. Khajiiti say it reminds them of the descriptions of Southpaw, the legendary mount of Rajhin the Purring Liar.",
                            ["icon"] = "/esoui/art/icons/mounticon_psijicsenche.dds",
                            ["furnitureId"] = 4997,
                            ["id"] = 5062,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Psijic Senche Exemplar",
                        },
                        [5063] = 
                        {
                            ["description"] = "When Psijic monks (or their favored allies) call up a Psijic Spectral Steed, they're really summoning the spirit of a Psijic Horse Exemplar, brought back to the world of the living and made tangible by a supreme act of Conjuration.",
                            ["icon"] = "/esoui/art/icons/mounticon_psijichorserad.dds",
                            ["furnitureId"] = 5005,
                            ["id"] = 5063,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Psijic Spectral Steed",
                        },
                        [5064] = 
                        {
                            ["description"] = "This magical mount was created to provide Psijic Monks with a reliable conjured ride when going to and from the courts of rulers in northern Tamriel. Psijics have little use for such a creature on Artaeum, but summon them out of admiration and affection.",
                            ["icon"] = "/esoui/art/icons/mounticon_psijicwolfrad.dds",
                            ["furnitureId"] = 5004,
                            ["id"] = 5064,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Phantom Ice Wolf",
                        },
                        [5065] = 
                        {
                            ["description"] = "The Psijic monk who created the spell for conjuring the spirit of a Psijic Senche Exemplar back into the world of the living as a tangible Ghost Cat was a Wood Elf—which probably explains why it manifests as an Y'frren spirit of the Green.",
                            ["icon"] = "/esoui/art/icons/mounticon_psijicsencherad.dds",
                            ["furnitureId"] = 5006,
                            ["id"] = 5065,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Green-Graht Ghost Cat",
                        },
                        [5066] = 
                        {
                            ["description"] = "When one of Meridia's Auroran Knights manifests in Tamriel, and needs a mount, the knight has the ability to instantly summon a Daedric Warhorse from the Colored Rooms. Curiously, if the knight is banished to Oblivion, the mount sometimes stays behind.",
                            ["icon"] = "/esoui/art/icons/mount_auroranwarhorse.dds",
                            ["furnitureId"] = 5409,
                            ["id"] = 5066,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Auroran Warhorse",
                        },
                        [5067] = 
                        {
                            ["description"] = "These magical creatures have a special relationship to Y'ffre the nature god, and seem to draw strength from the very bones of the earth beneath their hooves. It's a privilege for a mortal rider to be borne by such an enchanted beast.",
                            ["icon"] = "/esoui/art/icons/mounticon_indrik_dawnwood-green.dds",
                            ["furnitureId"] = 5416,
                            ["id"] = 5067,
                            ["category"] = "Cervines",
                            ["hint"] = "Obtained by combining four different Dawnwood Berries with a Nascent Indrik mount. The Nascent Indrik will become the Dawnwood Indrik.",
                            ["name"] = "Dawnwood Indrik",
                        },
                        [5068] = 
                        {
                            ["description"] = "The Luminous Indrik seems to radiate the same soft aetherial glow as the stars in the heavens, but steady and nearby rather than flickering and remote. It's reassuring, somehow.",
                            ["icon"] = "/esoui/art/icons/mounticon_indrik_illustrious-gold.dds",
                            ["furnitureId"] = 5417,
                            ["id"] = 5068,
                            ["category"] = "Cervines",
                            ["hint"] = "Obtained by combining four different Luminous Berries with a Nascent Indrik mount. The Nascent Indrik will become the Luminous Indrik.",
                            ["name"] = "Luminous Indrik",
                        },
                        [5071] = 
                        {
                            ["description"] = "An Exemplar mount is a mystical manifestation of its form's ideal concept, It is also extraordinarily sensitive to the emotional valences of its rider. If the rider engages in too much bloodthirsty killing, their Exemplar may become a Bloodshadow Wraith.",
                            ["icon"] = "/esoui/art/icons/mounticon_bloodshadowsteed.dds",
                            ["furnitureId"] = 4995,
                            ["id"] = 5071,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Bloodshadow Wraith Steed",
                        },
                        [5072] = 
                        {
                            ["description"] = "The Badger Bears of southern Blackwood were nearly extinct in the wild when they were saved by the intervention from an unlikely source, an Imperial noble, when Viscount Glorion of Leyawiin rescued the species by breeding them as mounts.",
                            ["icon"] = "/esoui/art/icons/mount_badgerbear.dds",
                            ["furnitureId"] = 5003,
                            ["id"] = 5072,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Badger Bear",
                        },
                        [5073] = 
                        {
                            ["description"] = "The cliffs and escarpments of east central Elsweyr are the home of the nimble and sure-footed senche-cougars, who prowl the rocks hunting goats and marmots. Inevitably, they've been domesticated by their feline cousins the Khajiit.",
                            ["icon"] = "/esoui/art/icons/mount_cougarsenche.dds",
                            ["furnitureId"] = 5002,
                            ["id"] = 5073,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Senche-Cougar",
                        },
                        [11218] = 
                        {
                            ["description"] = "A miniature statue of an Orc warrior emanating strength.",
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_statuetteorcheavystatue001.dds",
                            ["furnitureId"] = 8964,
                            ["id"] = 11218,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Orc Warrior",
                        },
                        [5075] = 
                        {
                            ["description"] = "In the rugged badlands of central Hammerfell, even camels struggle to maneuver across the broken terrain. But wolves can go where even camels cannot, so the roving Redguards of the canyon lands have bred the local Painted Wolves into sure-footed mounts.",
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_paintedwolf.dds",
                            ["furnitureId"] = 5412,
                            ["id"] = 5075,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Painted Wolf",
                        },
                        [5076] = 
                        {
                            ["description"] = "The thief-god Rajhin is said to have stolen these enchanted purple steeds from somewhere in Oblivion, but when his worshipers are asked where he got them, they just laugh and say, \"Noweyr!\"",
                            ["icon"] = "/esoui/art/icons/mounticon_psijichorse_twitch.dds",
                            ["furnitureId"] = 5413,
                            ["id"] = 5076,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Noweyr Steed",
                        },
                        [5077] = 
                        {
                            ["description"] = "This ominous companion, conjured by Psijic magic in the shape of a glowing senche mount, represents for the monks of Artaeum all of the painful choices they regret having made, but which they nonetheless must ride upon into the future.",
                            ["icon"] = "/esoui/art/icons/mounticon_psijicsenche_twitch.dds",
                            ["furnitureId"] = 5414,
                            ["id"] = 5077,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Senche of Scarlet Regret",
                        },
                        [5078] = 
                        {
                            ["description"] = "\"Sweet young things like to give this one kittens as keepsakes,\" says Eye of the Queen Razum-dar, \"but raising a pet is not consistent with Raz's romantic but itinerant life of intrigue. Perhaps you could give cute Ja'khajiit a good home, yes?\"",
                            ["icon"] = "/esoui/art/icons/pet_185_steve.dds",
                            ["furnitureId"] = 4963,
                            ["id"] = 5078,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ja'khajiit Raz",
                        },
                        [5079] = 
                        {
                            ["description"] = "In the Clockwork City, mechanical Firepot Spiders can be programmed to follow chefs around like little walking barbecues. Someone has devised a secret method for exporting them from Sotha Sil's hidden world—but how? Better get one while you still can.",
                            ["icon"] = "/esoui/art/icons/pet_4668.dds",
                            ["furnitureId"] = 4964,
                            ["id"] = 5079,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Firepet Spider",
                        },
                        [5080] = 
                        {
                            ["description"] = "\"Cute little thing, isn't it? 'Course, what I care about is that a Ringtail, properly trained, can get into places no one else can, and carry out small items in their cheek pouches. Lost goods, as it were, or misplaced valuables. Right?\" —Fenaanaral",
                            ["icon"] = "/esoui/art/icons/pet_bassarisk_a_basic.dds",
                            ["furnitureId"] = 4965,
                            ["id"] = 5080,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Alinor Ringtail",
                        },
                        [5081] = 
                        {
                            ["description"] = "The Great Daenians are gigantic hounds bred as protectors and companions by the Beldama Wyrd coven. Despite their size and strength, they are surprisingly gentle except when roused to the defense of their masters.",
                            ["icon"] = "/esoui/art/icons/pet_181_greatdane.dds",
                            ["furnitureId"] = 4966,
                            ["id"] = 5081,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Great Daenian Hound",
                        },
                        [5082] = 
                        {
                            ["description"] = "The young of most creatures are cute, even adorable. That's … not really true of the Larval Yaghra. If you have one of these following you, you're either telling the world you don't give a Daedric damn what they think, or you're a Sea Sload in disguise.",
                            ["icon"] = "/esoui/art/icons/pet_191_yaghradarkblue-yellow.dds",
                            ["furnitureId"] = 4967,
                            ["id"] = 5082,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Larval Yaghra",
                        },
                        [5083] = 
                        {
                            ["description"] = "Prong-Eared Grimalkins are widely regarded as having supernatural powers thanks to their ability to appear almost instantly when a container of cat food is opened, and to fit themselves into boxes that seem entirely too small for them.",
                            ["icon"] = "/esoui/art/icons/pet_182_grimalkin.dds",
                            ["furnitureId"] = 4968,
                            ["id"] = 5083,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Prong-Eared Grimalkin",
                        },
                        [5084] = 
                        {
                            ["description"] = "Native to Summerset Isle, the gaudy Coral Mudcrab has elaborate coral growths on its back, as well as a claw that looks comically over-sized, but which is surprisingly functional. Count fingers after petting.",
                            ["icon"] = "/esoui/art/icons/pet_180_coralcrab.dds",
                            ["furnitureId"] = 4969,
                            ["id"] = 5084,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Coral Mudcrab",
                        },
                        [5085] = 
                        {
                            ["description"] = "For mortals good in heart and soul, being in the presence of a Springtide Indrik induces serenity and makes anger almost impossible—though paradoxically it also inspires a righteous determination to fight injustice.",
                            ["icon"] = "/esoui/art/icons/pet_192_indrik-springtide-green.dds",
                            ["furnitureId"] = 4970,
                            ["id"] = 5085,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Springtide Indrik",
                        },
                        [5086] = 
                        {
                            ["description"] = "As savage as Welwas are, history indicates that every pastoral society in Craglorn's long history—Nedes, Yokudans, Goblins, and Orcs—has domesticated them at some point. They may be ugly, but they sure are loyal.",
                            ["icon"] = "/esoui/art/icons/pet_longhairwelwa.dds",
                            ["furnitureId"] = 4971,
                            ["id"] = 5086,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Longhair Welwa",
                        },
                        [5087] = 
                        {
                            ["description"] = "No one can look at the glistening plumage of the Shimmering Indrik and doubt its enchanted nature, for it sparkles with Magicka and virtue. Here is a creature untainted by aggression, though it will ably defend itself at need.",
                            ["icon"] = "/esoui/art/icons/pet_193_indrik-illustrious-gold.dds",
                            ["furnitureId"] = 4972,
                            ["id"] = 5087,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Shimmering Indrik",
                        },
                        [5088] = 
                        {
                            ["description"] = "The giant crimson beetles that scuttle through the gloom of Mephala's Spiral Skein are said to use their pointed probosces to drink the blood of whatever they catch. True or not, it's a fine gruesome story for cultists to tell about their Daedric pets.",
                            ["icon"] = "/esoui/art/icons/pet_mephalabeetle.dds",
                            ["furnitureId"] = 4973,
                            ["id"] = 5088,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Skein Shalk",
                        },
                        [5089] = 
                        {
                            ["description"] = "It should surprise no one familiar with Mephala, the Webspinner, that spiders are among the most common denizens of the Spiral Skein, the Daedric Prince's Oblivion realm. They're not exactly affectionate pets, but they are fiercely loyal.",
                            ["icon"] = "/esoui/art/icons/pet_spidermephala.dds",
                            ["furnitureId"] = 4974,
                            ["id"] = 5089,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Skein Spider",
                        },
                        [5090] = 
                        {
                            ["description"] = "Knights of the Spider Cult, known as Deathweavers, often disdain the cultists' usual Daedric Spider companions, preferring Skein Scorpions to present a more warlike attitude.",
                            ["icon"] = "/esoui/art/icons/pet_mephalascorpion.dds",
                            ["furnitureId"] = 4975,
                            ["id"] = 5090,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Skein Scorpion",
                        },
                        [5091] = 
                        {
                            ["description"] = "When Mephala populated the Spiral Skein with \"improved\" versions of Tamrielic invertebrates, she outdid herself with the Skein Wasp, a giant menacing insect guaranteed to give any mortal the shivers!",
                            ["icon"] = "/esoui/art/icons/pet_mephalawasp.dds",
                            ["furnitureId"] = 4976,
                            ["id"] = 5091,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Skein Wasp",
                        },
                        [5092] = 
                        {
                            ["description"] = "When spring comes to the sun-dappled forests of southern Wrothgar, Echatere babies are sometimes born with temporary spotted camouflage that fades as the Echalette matures. It's pretty while it lasts.",
                            ["icon"] = "/esoui/art/icons/pet_echalette_fawn.dds",
                            ["furnitureId"] = 4977,
                            ["id"] = 5092,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Fawn Echalette",
                        },
                        [5093] = 
                        {
                            ["description"] = "The handsome breed of Masked Bears are native to the Pale Pass region of the Jerall Mountains, which has given rise to the legend that they came in the First Era with the invaders from Akavir who ended up there. Bears from Akavir? Really?",
                            ["icon"] = "/esoui/art/icons/pet_1151.dds",
                            ["furnitureId"] = 4978,
                            ["id"] = 5093,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Masked Bear Cub",
                        },
                        [5094] = 
                        {
                            ["description"] = "This perky but enigmatic equine glows with Magicka through the mystic runes that embellish its possibly-illusory epidermis. Enchanting!",
                            ["icon"] = "/esoui/art/icons/pet_psijicpony.dds",
                            ["furnitureId"] = 4979,
                            ["id"] = 5094,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Psijic Mascot Pony",
                        },
                        [5095] = 
                        {
                            ["description"] = "Are the Psijic Mascot pets real animals with an enchanted appearance, or illusory beast companions created from Magicka? The Psijic monks know which it is, but ask one, and all you get in reply is a smile.",
                            ["icon"] = "/esoui/art/icons/pet_psijicwolfpup.dds",
                            ["furnitureId"] = 4980,
                            ["id"] = 5095,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Psijic Mascot Wolf Pup",
                        },
                        [5096] = 
                        {
                            ["description"] = "The first Guar came to Artaeum when a Psijic advisor to the Tribunal returned from Mournhold with a Pony Guar in the middle of the First Era, and they've been favorites of the Psijics ever since. There's even a glowing Psijic Mascot Guar!",
                            ["icon"] = "/esoui/art/icons/pet_psijicguar.dds",
                            ["furnitureId"] = 4981,
                            ["id"] = 5096,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Psijic Mascot Guar Calf",
                        },
                        [5097] = 
                        {
                            ["description"] = "By tradition, the Psijic Mascot of the order's Ritemaster is always a Bear Cub—but since there's been only one Ritemaster, Iachesis, for over 3,000 years, the tradition hasn't had much opportunity to change. Fortunately, others can befriend them as well!",
                            ["icon"] = "/esoui/art/icons/pet_psijicbearcub.dds",
                            ["furnitureId"] = 4982,
                            ["id"] = 5097,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Psijic Mascot Bear Cub",
                        },
                        [5098] = 
                        {
                            ["description"] = "\"Some say that Psijic Mascot creatures aren't true animals at all, but illusory constructs created by Psijic monks as portable storage batteries of Magicka,\" says Sapiarch Soraturil. \"What nonsense!\"",
                            ["icon"] = "/esoui/art/icons/pet_psijicsenchecub.dds",
                            ["furnitureId"] = 4983,
                            ["id"] = 5098,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Psijic Mascot Senche Cub",
                        },
                        [5099] = 
                        {
                            ["description"] = "\"I don't know, something about being followed around by a tame miniature giant elemental amphibian just seems right to me, you know? Expresses my inner newt.\" —Dinuviel Darkwater of Rellenthil",
                            ["icon"] = "/esoui/art/icons/pet_salamander_01.dds",
                            ["furnitureId"] = 4984,
                            ["id"] = 5099,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Pocket Salamander",
                        },
                        [5101] = 
                        {
                            ["description"] = "The thief-god Rajhin is said to have stolen these enchanted purple Ponies from somewhere in Oblivion, but when his worshipers are asked where he got them, they just laugh and say, \"Noweyr!\"",
                            ["icon"] = "/esoui/art/icons/pet_psijicpony_twitch.dds",
                            ["furnitureId"] = 4986,
                            ["id"] = 5101,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Noweyr Pony",
                        },
                        [5102] = 
                        {
                            ["description"] = "This ominous yet playful pet, conjured by Psijic magic in shape of a glowing senche cub, represents an Artaeum monk's regrettable choices that may yet be reversed by proper adherence to the Old Ways.",
                            ["icon"] = "/esoui/art/icons/pet_psijicsenchecub_twitch.dds",
                            ["furnitureId"] = 4987,
                            ["id"] = 5102,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Senche Cub of Scarlet Regret",
                        },
                        [5105] = 
                        {
                            ["description"] = "Though eventually it will grow into a massive beast with a vast wingspan, a Fledgling Gryphon is just the right size for a companion creature, and its juvenile antics are hilarious!",
                            ["icon"] = "/esoui/art/icons/pet_fledgelinggryphon.dds",
                            ["furnitureId"] = 4990,
                            ["id"] = 5105,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Fledgling Gryphon",
                        },
                        [9235] = 
                        {
                            ["description"] = "These black-and-gold barded destriers carry their riders with distinction as they sweep across Cyrodiil, serving as but one symbol of goals and experiences their dauntless combatants share. \n\n|cFFFFFFRiding Skill does not affect this mount's appearance.|r",
                            ["icon"] = "/esoui/art/icons/mount_dauntlessbananas.dds",
                            ["furnitureId"] = 7604,
                            ["id"] = 9235,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Bonds of Battle Destrier",
                        },
                        [9236] = 
                        {
                            ["description"] = "The envy of treasure-seekers throughout Tamriel, this sure-footed steed serves as both a sturdy companion and an enduring reminder of what fellowship and camaraderie can achieve.\n\n|cFFFFFFRiding Skill does not affect this mount's appearance.|r",
                            ["icon"] = "/esoui/art/icons/mount_goldleafacquisitions.dds",
                            ["furnitureId"] = 7605,
                            ["id"] = 9236,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Guild's Pride Charger",
                        },
                        [9238] = 
                        {
                            ["description"] = "\"If the creature following behind me truly is a ghost, then this is the gentlest haunting I have ever seen. The crustation only skitters at my feet and occasionally clacks its claws at unwelcome houseguests.\"—Bensharaz, Spirit Hunter",
                            ["icon"] = "/esoui/art/icons/pet_spectralmudcrab.dds",
                            ["furnitureId"] = 7606,
                            ["id"] = 9238,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Spectral Mudcrab",
                        },
                        [9240] = 
                        {
                            ["description"] = "In the wild, Topaz Terror Birds cloak themselves in wind-blown sand to ambush unsuspecting prey. This little fledgling is keen to practice the technique, so be sure to warn your companions before a sandstorm hits. No one wants to lose a toe!",
                            ["icon"] = "/esoui/art/icons/pet_terrorbirdyellow.dds",
                            ["furnitureId"] = 7607,
                            ["id"] = 9240,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Topaz Fledgling Terror Bird",
                        },
                        [9243] = 
                        {
                            ["description"] = "\"Which lowland does this ornery creature call home? Why, all of them! Think I'm exaggerating? Believe what you want, but know that unless trained while young, they'll charge you in a heartbeat. Best have them on your side.\"—Miet, Breeder",
                            ["icon"] = "/esoui/art/icons/pet_lowlandbristleback.dds",
                            ["furnitureId"] = 7608,
                            ["id"] = 9243,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Lowland Bristleback",
                        },
                        [9244] = 
                        {
                            ["description"] = "These feral pigs prowl through the boreal forests of Bleakrock Isle. They grudgingly adapt to domestication, and take pleasure in plowing through deep snow, mud, or grasslands alongside their owners.",
                            ["icon"] = "/esoui/art/icons/pet_snowbarrowboar.dds",
                            ["furnitureId"] = 7609,
                            ["id"] = 9244,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Snowbarrow Boar",
                        },
                        [11293] = 
                        {
                            ["description"] = "Fangtomes know not the importance or content of the books they inhabit. In the event that your rare first editions or vital academic texts have gained a tenant, simply befriend the tome via ample spine massages and a gentle ruffling of its pages.",
                            ["icon"] = "/esoui/art/icons/pet_bibliosophfangtome.dds",
                            ["furnitureId"] = 8998,
                            ["id"] = 11293,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Albinoscript Fangtome",
                        },
                        [9246] = 
                        {
                            ["description"] = "A product of wizardry and selective breeding, these chimeric steeds descend from Summerset gryphons. According to creator Irastimil Direnni, their wingless frame kept upkeep costs low, while maintaining superiority over the upstart Bretons' clumsy steeds.",
                            ["icon"] = "/esoui/art/icons/mount_baldgryphon.dds",
                            ["furnitureId"] = 7615,
                            ["id"] = 9246,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Quasigriff",
                        },
                        [9247] = 
                        {
                            ["description"] = "A miniature statue of Syrabane, an Aldmeri god-ancestor of magic.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettesyrabane001.dds",
                            ["furnitureId"] = 7616,
                            ["id"] = 9247,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Syrabane, the Warlock",
                        },
                        [9248] = 
                        {
                            ["description"] = "A miniature statue of Kynareth, Divine patron of sailors and travelers.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettekynareth001.dds",
                            ["furnitureId"] = 7617,
                            ["id"] = 9248,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Kynareth, Air Goddess",
                        },
                        [9249] = 
                        {
                            ["description"] = "\"This lithe feline possesses the quiet madness of a clever assassin, making it a harmonious steed for those methodically ending the lives of others. Even better—mine sometimes brings gifts of mangled Mer. Perhaps you'll be so lucky?\"—Mother Regrets",
                            ["icon"] = "/esoui/art/icons/mount_grimsenche.dds",
                            ["furnitureId"] = 7619,
                            ["id"] = 9249,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Grinning Terror Senche",
                        },
                        [9250] = 
                        {
                            ["description"] = "\"I can't pick a favorite from the Grinning Terrors, but this ominous horse kissed by madness appeals to me on a visceral level. Perhaps because they enjoy spreading the viscera of unwelcome riders about with their hooves.\"—Mother Regrets",
                            ["icon"] = "/esoui/art/icons/mount_grimhorse.dds",
                            ["furnitureId"] = 7620,
                            ["id"] = 9250,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Grinning Terror Steed",
                        },
                        [9251] = 
                        {
                            ["description"] = "\"You need more than colorful barding to harness one of these bears—a splash of blood freed by Neb-Crescen and a teardrop from a watcher's eye might bind one to your cause. Might. Otherwise, stand clear. You won't survive their hugs.\"—Mother Regrets",
                            ["icon"] = "/esoui/art/icons/mount_grimbear.dds",
                            ["furnitureId"] = 7621,
                            ["id"] = 9251,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Grinning Terror Bear",
                        },
                        [9252] = 
                        {
                            ["description"] = "\"Croon to this guar, describing recent murder sprees, and you might win a place at this guar's side. Or capture its attention by emulating loud bodily functions. Either delights this creature.\"—Mother Regrets",
                            ["icon"] = "/esoui/art/icons/mount_grimguar.dds",
                            ["furnitureId"] = 7622,
                            ["id"] = 9252,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Grinning Terror Guar",
                        },
                        [9253] = 
                        {
                            ["description"] = "\"This wolf might seem a playful Jester's Festival creature—a performer's beast ready to entertain. But no. Its sharp wit and sharper teeth care not for another's amusement, favoring its own. Only its rider is safe from its joy-nips.\"—Mother Regrets",
                            ["icon"] = "/esoui/art/icons/mount_grimwolf.dds",
                            ["furnitureId"] = 7623,
                            ["id"] = 9253,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Grinning Terror Wolf",
                        },
                        [9254] = 
                        {
                            ["description"] = "According to the Ash'abah, if you receive one of these fierce sep adders as a gift and you both survive for a year with each other, you have passed the first trial necessary to trade in poisons. Bonus? You keep the jewel-toned creature—if you live.",
                            ["icon"] = "/esoui/art/icons/pet_sapphiresepadder.dds",
                            ["furnitureId"] = 7632,
                            ["id"] = 9254,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Sapphire Sep Adder",
                        },
                        [9255] = 
                        {
                            ["description"] = "Nearly driven to extinction a century ago by Nibenese, who used their brilliant ruby wing dust as rouge, these moths made a comeback in a different area: Valenwood. Friendly to a fault, they are now favored companions among alchemists.",
                            ["icon"] = "/esoui/art/icons/pet_carminewoodmoth.dds",
                            ["furnitureId"] = 7633,
                            ["id"] = 9255,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Carmine Wood Moth",
                        },
                        [9256] = 
                        {
                            ["description"] = "Farmers in Southern Cyrodiil carry an antidote to Spotted Plow Spiders since it is not uncommon to accidentally rake through a nest and be bitten by thousands of tiny hatchlings. Despite the dangers and if raised correctly, the spiders make good pets.",
                            ["icon"] = "/esoui/art/icons/pet_spottedplowspider.dds",
                            ["furnitureId"] = 7634,
                            ["id"] = 9256,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Spotted Plow Spider",
                        },
                        [9257] = 
                        {
                            ["description"] = "A staple of Morthal wardens, these imposing bears trundle near the outskirts of town, serving as extra guards when not in use as steeds or resting. Those who seek to one day become valiant defenders of their town often sneak away to feed them extra treats.",
                            ["icon"] = "/esoui/art/icons/mount_sunbackbear.dds",
                            ["furnitureId"] = 7639,
                            ["id"] = 9257,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Sunback Bear",
                        },
                        [7217] = 
                        {
                            ["description"] = "Enterprising siegemasters need to move quickly when working to overthrow a fortification. Whether you plan to conquer Castle Alessia, take over Fort Warden, or overwhelm Chalman Keep, the Holdbreaker Horse is a valuable addition to your stable!",
                            ["icon"] = "/esoui/art/icons/mount_holdbreakerwarhorse.dds",
                            ["furnitureId"] = 6543,
                            ["id"] = 7217,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Holdbreaker Warhorse",
                        },
                        [7219] = 
                        {
                            ["description"] = "When the winter air grows quiet and heavy just before snowfall, woodsmoke touched by Magicka swirls into the form of an Icebreath Indrik. Summerset scholars believe these mounts allow those with insight and wisdom to understand their deepest wish.",
                            ["icon"] = "/esoui/art/icons/mounts_icebreathindrik.dds",
                            ["furnitureId"] = 6544,
                            ["id"] = 7219,
                            ["category"] = "Cervines",
                            ["hint"] = "Obtained by combining four different Icebreath Berries with a Nascent Indrik mount. The Nascent Indrik will become the Icebreath Indrik.",
                            ["name"] = "Icebreath Indrik",
                        },
                        [7220] = 
                        {
                            ["description"] = "The Laughing Lion has taken a liking to you! Place this ancient sarcophagus in your home and his carefree wisdom will always be close to hand.",
                            ["icon"] = "/esoui/art/icons/housing_els_duc_khunzarrisarcophugus001.dds",
                            ["furnitureId"] = 6545,
                            ["id"] = 7220,
                            ["category"] = "General",
                            ["hint"] = "Awarded for completing the \"A Hero's Song\" achievement in Southern Elsweyr.",
                            ["name"] = "Khunzar-ri's Rest",
                        },
                        [7221] = 
                        {
                            ["description"] = "After arriving on Firemoth Island, the slavers found and trained a flame-hued variant of the nix-ox steed. Its vibrant colors belie its fiery temperament, making it a suitable match for those seeking to ride into the midst of combat.",
                            ["icon"] = "/esoui/art/icons/mount_firemothnixox.dds",
                            ["furnitureId"] = 6546,
                            ["id"] = 7221,
                            ["category"] = "Arthropods",
                            ["hint"] = "",
                            ["name"] = "Firemoth Nix-Ox",
                        },
                        [5176] = 
                        {
                            ["description"] = "The hissing and twitching farmer who sells these claims they're just ordinary black roosters. And probably they are. You must have just imagined that this Cockerel's eyes glow after dark. You must have!",
                            ["icon"] = "/esoui/art/icons/pet_229_blackrooster.dds",
                            ["furnitureId"] = 5444,
                            ["id"] = 5176,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Daemon Cockerel",
                        },
                        [9275] = 
                        {
                            ["description"] = "Said to have been bred by Coral-Splitter Goblins to hunt for fresh fish, these aqua-blue and coral-striped durzogs spread to the shores of Topal Bay decades ago. To this day, they still love to dive into the surf and snag aquatic bounty!",
                            ["icon"] = "/esoui/art/icons/pet_topaldurzog.dds",
                            ["furnitureId"] = 7640,
                            ["id"] = 9275,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Topal Durzog",
                        },
                        [9276] = 
                        {
                            ["description"] = "With dappled skin perfectly matched to the white rock and marshy wetlands east of Bthanual, these Kagouti favor stealth and ambushes over brute force attacks. Ride one of these creatures and you'll be sure to turn heads in Mournhold.",
                            ["icon"] = "/esoui/art/icons/mount_chalkhidekagouti.dds",
                            ["furnitureId"] = 7641,
                            ["id"] = 9276,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Chalkhide Kagouti",
                        },
                        [9277] = 
                        {
                            ["description"] = "The Knights of the Silver Rose spent years finding the best felines to rid their fortress of pests and annoyances. Generations later, and these senche-servals can clear out banekin infestations in a single day.",
                            ["icon"] = "/esoui/art/icons/pet_silverroseservalsenche.dds",
                            ["furnitureId"] = 7642,
                            ["id"] = 9277,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Silver Rose Senche-Serval",
                        },
                        [9278] = 
                        {
                            ["description"] = "Woe to any who ride this fiery steed without its consent! Sanctified by ashes from the funeral pyres of venerated witches, this wicker steed blazes a path across Tamriel and beyond, reminding any mortals who see it of their own short lifespans.",
                            ["icon"] = "/esoui/art/icons/mount_bonefirewickersteed.dds",
                            ["furnitureId"] = 7643,
                            ["id"] = 9278,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Bonfire Wicker-Steed",
                        },
                        [5188] = 
                        {
                            ["description"] = "Craglorn Companions of Belkarth had no luck at all exporting Fellrunners for the High Rock and Hammerfell pet markets—until they sold a flock of the Teal-Faced variety to Fahara'jad's menagerie in Sentinel. Suddenly they were all the rage!",
                            ["icon"] = "/esoui/art/icons/pet_194_teal-fellrunner.dds",
                            ["furnitureId"] = 5531,
                            ["id"] = 5188,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Teal-Faced Fellrunner",
                        },
                        [5190] = 
                        {
                            ["description"] = "The werewolf hunters of the Silver Dawn rely on the courage and keen noses of these great High Rock hounds to help them track Tamriel's lycanthropes to their lairs.",
                            ["icon"] = "/esoui/art/icons/pet_204_greatdanehunter.dds",
                            ["furnitureId"] = 5510,
                            ["id"] = 5190,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Silver Daenian Werewolf Tracker",
                        },
                        [5196] = 
                        {
                            ["description"] = "The Gryphons that nest on the highest pinnacles of Eton Nir, the tallest mountain on Summerset, have a distinctive bluish tint to their plumage. Some sapiarchs call this sky-blue camouflage, but the Priests of Auri-El see in it a touch of the Divine.",
                            ["icon"] = "/esoui/art/icons/pet_183_azuregryphon.dds",
                            ["furnitureId"] = 5419,
                            ["id"] = 5196,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Azure Fledgling Gryphon",
                        },
