                        [1268] = 
                        {
                            ["description"] = "Trophy taken from the Maw of the Infernal in honor of an Undaunted victory in Banished Cells II.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophydaedroth001.dds",
