                        [12775] = 
                        {
                            ["description"] = "A painting of Oathsworn Pit, where followers of Malacath train in three different forms of combat.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingu43oathswornpitpainting001.dds",
                            ["furnitureId"] = 10234,
                            ["id"] = 12775,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Painting: Oathsworn Pit",
                        },
                        [1303] = 
                        {
                            ["description"] = "A night-black senche-tiger with burning paws and flames hissing from its face: this is surely the stuff of evil dreams. The origin of this horrific mount is obscure, but some see the hand of Mehrunes Dagon in it.",
                            ["icon"] = "/esoui/art/icons/mounticon_senche_h.dds",
                            ["furnitureId"] = 4448,
                            ["id"] = 1303,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Nightmare Senche",
                        },
                        [12774] = 
                        {
                            ["description"] = "A miniature statue of a Tojay Khajiit, dancing in celebration.",
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_statuettetojay001.dds",
                            ["furnitureId"] = 10233,
                            ["id"] = 12774,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Dancing Tojay",
                        },
                        [12773] = 
                        {
                            ["description"] = "A miniature statue of Daedric Prince Sanguine, hoisting a tankard during a revelry.",
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_sanguinestatuette001.dds",
                            ["furnitureId"] = 10232,
                            ["id"] = 12773,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Sanguine",
                        },
                        [12712] = 
                        {
                            ["description"] = "The shards on this wildcat's body are dull and safe to touch. The same can't be said for its fangs and claws, which prick like needles. As it grows in size, those shards become razor-sharp glass—a terrifying defense mechanism.",
                            ["icon"] = "/esoui/art/icons/pet_scintillatingshardsenchecub.dds",
                            ["furnitureId"] = 10153,
                            ["id"] = 12712,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Mirrormoor Shard Wildcat",
                        },
                        [12693] = 
                        {
                            ["description"] = "Owners of these clever kittens must keep a close eye on them, especially in snowy environments. Their soft steps and white fur allow them to easily disappear in such places. However, most prefer the warmth of their companions to frosty dens.",
                            ["icon"] = "/esoui/art/icons/pet_snowclawsencheservalkitten.dds",
                            ["furnitureId"] = 10143,
                            ["id"] = 12693,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Snowclaw Senche-Serval Kitten",
                        },
                        [12692] = 
                        {
                            ["description"] = "\"Look, some might call it cheating to play with a ball that follows you around, but it's not like you asked it to! It's perfectly safe. Fine for a regulation game. I think. Might get confusing with two balls on the field, though.\"—Carrier Clairene",
                            ["icon"] = "/esoui/art/icons/pet_chaosballcohort.dds",
                            ["furnitureId"] = 10142,
                            ["id"] = 12692,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Chaosball Cohort",
                        },
                        [12691] = 
                        {
                            ["description"] = "\"He's just as smart and loyal as any Legion mastiff! And twice as affectionate! Although he has a habit of not actually retrieving his ball if it's under a bush, or in a puddle, or just not easy to see. But that's all right.\"—Legionary Audania",
                            ["icon"] = "/esoui/art/icons/pet_malabaltorretriever.dds",
                            ["furnitureId"] = 10140,
                            ["id"] = 12691,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "West Weald Retriever",
                        },
                        [12690] = 
                        {
                            ["description"] = "\"Some people think these lemurs are psychic, but that's just nonsense. They're just very persuasive. Look at those gigantic eyes! How could you not do whatever it wanted just to get it to stop staring at you?\"—Isabelle Onus, Wayrest",
                            ["icon"] = "/esoui/art/icons/pet_highrockringtail.dds",
                            ["furnitureId"] = 10139,
                            ["id"] = 12690,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "High Rock Red Lemur",
                        },
                        [12684] = 
                        {
                            ["description"] = "The one surefire way to tame a Dragontail Mountain Bear is to find one when it's young and tempt it with treats like honey and berries. The bears have a particularly strong sweet tooth and will do anything to satiate their cravings.",
                            ["icon"] = "/esoui/art/icons/pet_dragontailmountainbearcub.dds",
                            ["furnitureId"] = 10137,
                            ["id"] = 12684,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Dragontail Mountain Bear Cub",
                        },
                        [11552] = 
                        {
                            ["description"] = "\"Look, it may not have much personality, but it's entrancing, in its own way. It's happy to see you, I think. The students at the Mages Guild were very proud of this conjuration. The least you can do is act impressed.\"—Mage Student Hrantin",
                            ["icon"] = "/esoui/art/icons/pet_guildconjuredwisp.dds",
                            ["furnitureId"] = 9351,
                            ["id"] = 11552,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Guild Conjured Wisp",
                        },
                        [12683] = 
                        {
                            ["description"] = "\"Don't mind old Honeycheeks, here. He's just snuffling around to see if you have anything tasty on you. Don't worry, he's a strict vegetarian! Although he has been known to swallow a bee or two when he gets deep in a honeycomb.\"—Beniah Bear-friend",
                            ["icon"] = "/esoui/art/icons/mount_dragontailmountainbear.dds",
                            ["furnitureId"] = 10136,
                            ["id"] = 12683,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Dragontail Mountain Bear",
                        },
                        [12668] = 
                        {
                            ["description"] = "Though these dragon frogs are striking to look at, not much can be said for their intelligence. When two of them meet face to face, they become mesmerized by their own reflection in the other's body. The resulting standoff can last for hours.",
                            ["icon"] = "/esoui/art/icons/pet_mirrormoordragonfrog.dds",
                            ["furnitureId"] = 10128,
                            ["id"] = 12668,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Mirrormoor Dragon Frog",
                        },
                        [9507] = 
                        {
                            ["description"] = "\"Some claim these elk originate from necromantic rituals involving restless spirits. Perhaps, I say. Regardless, these fawns make for delightful companions, though they'll sometimes stare at nothing for hours.\"—Phrastus of Elinhir",
                            ["icon"] = "/esoui/art/icons/pet_platinumfawn.dds",
                            ["furnitureId"] = 7857,
                            ["id"] = 9507,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Palefrost Elk Fawn",
                        },
                        [12667] = 
                        {
                            ["description"] = "The wings on these bats are mesmerizing, though difficult to spot during the day. When backlit by the light of Tamriel's moons, they seem to ignite in the sky. The illusion draws insects, a happy feast for the Stainedwing Bat.",
                            ["icon"] = "/esoui/art/icons/pet_stainedwingbat.dds",
                            ["furnitureId"] = 10127,
                            ["id"] = 12667,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Stainedwing Bat",
                        },
                        [12666] = 
                        {
                            ["description"] = "\"I think Y'ffre has a lesson for us in all his creations. Moths especially. It's easy to overlook them. But they remind us how to be soft. How to move lightly through the world, and how to follow the light.\"—Gundelion of Vashabar",
                            ["icon"] = "/esoui/art/icons/pet_sylvansunbeammoth.dds",
                            ["furnitureId"] = 10126,
                            ["id"] = 12666,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Vashabar Petal Moth",
                        },
                        [9510] = 
                        {
                            ["description"] = "Moonlight glints off glittering snowflakes during a ritual to imbue a white elk with the intelligence of a ghost captured from the frigid seas near Jehanna—or so claims High Rock lore. True or not, this steed understands more than most expect.",
                            ["icon"] = "/esoui/art/icons/mount_platinumelk.dds",
                            ["furnitureId"] = 7858,
                            ["id"] = 9510,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Palefrost Elk Mount",
                        },
                        [9511] = 
                        {
                            ["description"] = "Granted to the winner of the 2020 Tamriel Together Sweepstakes.",
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_playerstatue001.dds",
                            ["furnitureId"] = 7859,
                            ["id"] = 9511,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statue of Gloria",
                        },
                        [7464] = 
                        {
                            ["description"] = "\"When a Bright Moons Lunar Moth follows you, the blessings of Jone and Jode flutter close behind.\"—Moon-Priest Tedaza",
                            ["icon"] = "/esoui/art/icons/pet_brightmoonslunarmoth.dds",
                            ["furnitureId"] = 6630,
                            ["id"] = 7464,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Bright Moons Lunar Moth",
                        },
                        [9513] = 
                        {
                            ["description"] = "\"Don't let this bear's mesmerizing stars fool you into thinking it's a harmless bit of magical transport. Recall the sway of the Constellations, and understand that this creature embodies that power.\"—Wheezing Wilren",
                            ["icon"] = "/esoui/art/icons/mount_apexcelestialbear.dds",
                            ["furnitureId"] = 7861,
                            ["id"] = 9513,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Star-Born Guardian Bear",
                        },
                        [9514] = 
                        {
                            ["description"] = "Legends in Fulstrom say that a star-studded guar brought the bastard child of King Vrage to their village one snowy night. No one heard or saw the pair arrive, until a child cried out for warmth. The guar disappeared before dawn.",
                            ["icon"] = "/esoui/art/icons/mount_celestialguar.dds",
                            ["furnitureId"] = 7862,
                            ["id"] = 9514,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Star-Born Guardian Guar",
                        },
                        [7467] = 
                        {
                            ["description"] = "Born when a sunset's light tickles Magicka-imbued bird feathers, the Crimson Indrik possesses a flowing gait. Scholars observe that the indrik's magical nature promotes self-reflection.",
                            ["icon"] = "/esoui/art/icons/mount_crimsonindrik.dds",
                            ["furnitureId"] = 6631,
                            ["id"] = 7467,
                            ["category"] = "Cervines",
                            ["hint"] = "Obtained by combining four different Crimson Berries with a Nascent Indrik mount. The Nascent Indrik will become the Crimson Indrik.",
                            ["name"] = "Crimson Indrik",
                        },
                        [7468] = 
                        {
                            ["description"] = "Summerset scholars state this indrik, which comes into being at the base of the oldest tree in the forest, possesses an air of profound agelessness. Those riding these magical creatures find that weighty matters ease away.",
                            ["icon"] = "/esoui/art/icons/mount_mossheartindrik.dds",
                            ["furnitureId"] = 6632,
                            ["id"] = 7468,
                            ["category"] = "Cervines",
                            ["hint"] = "Obtained by combining four different Mossheart Berries with a Nascent Indrik mount. The Nascent Indrik will become the Mossheart Indrik.",
                            ["name"] = "Mossheart Indrik",
                        },
                        [9517] = 
                        {
                            ["description"] = "A painting of Leyawiin, the Nibenese city standing at the mouth of the Niben River and known for its majestic chapel honoring Zenithar.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingblackwoodkeyartpainting001.dds",
                            ["furnitureId"] = 7618,
                            ["id"] = 9517,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Painting: Leyawiin Awaits",
                        },
                        [12665] = 
                        {
                            ["description"] = "Mage faithful of Julianos create these unique creatures as a form of devotional art. The wisp represents orderly aesthetics, a sense of balance, and focused energy. It also makes for a beautiful focusing tone while meditating.",
                            ["icon"] = "/esoui/art/icons/pet_julianosstonewisp.dds",
                            ["furnitureId"] = 10125,
                            ["id"] = 12665,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Stonewisp of Truth and Law",
                        },
                        [12664] = 
                        {
                            ["description"] = "White sep adders are rare in the wild since their distinctive coloration doesn't allow for natural camouflage. They are typically found only in captivity, bred for the shine and luster of their scales and their beautiful novelty.",
                            ["icon"] = "/esoui/art/icons/pet_pearlysepadder.dds",
                            ["furnitureId"] = 10124,
                            ["id"] = 12664,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Pearl White Sep Adder",
                        },
                        [12657] = 
                        {
                            ["description"] = "The armor on this gleaming senche isn't just for its own protection. It's a necessary barrier between the rider and the knifelike shards that cover the beast's body. With time, a patient rider can learn where it's safe to touch the beast.",
                            ["icon"] = "/esoui/art/icons/mount_scintillatingshardsenche.dds",
                            ["furnitureId"] = 10117,
                            ["id"] = 12657,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Mirrormoor Shard Senche",
                        },
                        [12479] = 
                        {
                            ["description"] = "Traded in the merchant stalls of Fargrave, this beast is far from its native home in the depths of Valenwood. Specially trained to hunt Daedra from every realm, it tracks even the largest Ogrim without fear or uncertainty.",
                            ["icon"] = "/esoui/art/icons/mount_lucentguardianwolf.dds",
                            ["furnitureId"] = 9901,
                            ["id"] = 12479,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Lucent Guardian Wolf",
                        },
                        [1330] = 
                        {
                            ["description"] = "This appears to be a reanimated undead corpse of a wolf mount that was burned to death in some horrific event, and has returned hell-bent on vengeance. An intimidating ride, for sure!",
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_cinder-skeletal.dds",
                            ["furnitureId"] = 4449,
                            ["id"] = 1330,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Cinder Wolf",
                        },
                        [9523] = 
                        {
                            ["description"] = "A perfect replica of the Adytum Gate from the Zenithar Abbey.",
                            ["icon"] = "/esoui/art/icons/housing_bad_str_leyroundmagicalvaultdoorhousing001.dds",
                            ["furnitureId"] = 7878,
                            ["id"] = 9523,
                            ["category"] = "General",
                            ["hint"] = "Created by combining 50 Inscribed Shards from the Zenithar Abbey in Blackwood.",
                            ["name"] = "Replica Zenithar Adytum Gate",
                        },
                        [1332] = 
                        {
                            ["description"] = "In the valley of the Karth, the Reach clans have domesticated the fierce ice wolves, which they have bred for size and endurance to serve as mounts. A raiding party of Reach warriors riding Karthwolf Chargers is a fearsome sight indeed.",
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_f.dds",
                            ["furnitureId"] = 4450,
                            ["id"] = 1332,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Karthwolf Charger",
                        },
                        [12478] = 
                        {
                            ["description"] = "Chirhazi has fought more Daedra than most know exist. She's become accustomed to the protective armor necessary for such battles and willingly allows her partner to be her eyes.",
                            ["icon"] = "/esoui/art/icons/mount_lucentguardiansencheraht.dds",
                            ["furnitureId"] = 9900,
                            ["id"] = 12478,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Lucent Guardian Senche-Raht",
                        },
                        [12477] = 
                        {
                            ["description"] = "Specially bred to fight Daedra, this ornaug has a jaw that has been left free of armor. Its powerful bite can cut through even Daedroth hide, and its tough scales are resistant to scrapes and cuts.",
                            ["icon"] = "/esoui/art/icons/mount_lucentguardianornaug.dds",
                            ["furnitureId"] = 9899,
                            ["id"] = 12477,
                            ["category"] = "Serpentes",
                            ["hint"] = "",
                            ["name"] = "Lucent Guardian Ornaug",
                        },
                        [1335] = 
                        {
                            ["description"] = "When the Two Moons are full, the undead wolf pack rises from the grave, point their canine craniums at the sky, and try to howl—but the only sound is a dismal rattling in their bony throats.",
                            ["icon"] = "/esoui/art/icons/pet_145.dds",
                            ["furnitureId"] = 4451,
                            ["id"] = 1335,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Skeletal Pack Wolf",
                        },
                        [1336] = 
                        {
                            ["description"] = "The planes of Oblivion are infinite in their variation—and so are their vermin. The Jackdaw Daedrat is a bony Daedric rodent that likes to collect shiny things like your jewelry, and nip and nibble at things it shouldn't, but at least it's cute, right?",
                            ["icon"] = "/esoui/art/icons/pet_143.dds",
                            ["furnitureId"] = 4452,
                            ["id"] = 1336,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Jackdaw Daedrat",
                        },
                        [1337] = 
                        {
                            ["description"] = "Is Necromancy always wrong? Not even death can stop this loyal senche-leopard from stalking to adventure at your side!",
                            ["icon"] = "/esoui/art/icons/pet_146.dds",
                            ["furnitureId"] = 4453,
                            ["id"] = 1337,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Skeletal Senche-Leopard",
                        },
                        [12473] = 
                        {
                            ["description"] = "\"Meet my faithful steed, Honor. He's always getting into my foodstuffs. Has the appetite of a mammoth and the cunning of a fox, that one!\"—Cadwell",
                            ["icon"] = "/esoui/art/icons/pet_honorbantamguar.dds",
                            ["furnitureId"] = 9897,
                            ["id"] = 12473,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Golden Honor",
                        },
                        [12467] = 
                        {
                            ["description"] = "\"Be careful! This beast is meaner than a durzog and hot as a fire atronach. The furnace in its chest gives it incredible power and an appetite to match. I can't remember when last this one was fed. Best not to find out.\"—Kallin, House Ravenwatch",
                            ["icon"] = "/esoui/art/icons/mount_fireheartdeathhound.dds",
                            ["furnitureId"] = 9894,
                            ["id"] = 12467,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Brimstone Death Hound",
                        },
                        [12466] = 
                        {
                            ["description"] = "\"The Dwemer of old are known for their clever inventions. Here, they've captured the likeness of a senche through ingenious carving and materials. All these years later, the creature still easily heeds its master's call.\"—Dwarven Constructs: A Guide",
                            ["icon"] = "/esoui/art/icons/mount_cyandwarvensenche.dds",
                            ["furnitureId"] = 9893,
                            ["id"] = 12466,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Cyan Dwarven Senche",
                        },
                        [12458] = 
                        {
                            ["description"] = "Having been created through selective breeding and magic, quasigriffs have a penchant for absorbing any excess magicka they're exposed to. This stock was raised within the penumbral realms of Evergloam, as you can see.",
                            ["icon"] = "/esoui/art/icons/mount_reapersendquasigriff.dds",
                            ["furnitureId"] = 9888,
                            ["id"] = 12458,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Reaper's End Quasigriff",
                        },
                        [12457] = 
                        {
                            ["description"] = "Though adorable at this tender age, Bloodmoon pups still possess the incredible hunting drive of their adult counterparts. However, their hunts often lead to squirrels and insects, and a falling leaf is more than enough to distract them from the scent.",
                            ["icon"] = "/esoui/art/icons/pet_hircinesbloodmoonwolfpup.dds",
                            ["furnitureId"] = 9887,
                            ["id"] = 12457,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Bloodmoon Wolf Pup",
                        },
                        [12448] = 
                        {
                            ["description"] = "Perhaps the only thing sweeter than this cub are the snuggles it happily bestows on anyone it sees. It's rather addictive, and many who've begun petting the cub find it incredibly difficult to stop. Somehow, it always smells like roses.",
                            ["icon"] = "/esoui/art/icons/pet_heartsawecub.dds",
                            ["furnitureId"] = 9885,
                            ["id"] = 12448,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Mara's Awe Cub",
                        },
                        [12447] = 
                        {
                            ["description"] = "Never again want for a nightlight with this enchanted, flaming larval yaghra at your side. Just beware that while it does keep the darkness at bay, prolonged exposure to its horrible legs and beady little eyes has been known to increase nightmares.",
                            ["icon"] = "/esoui/art/icons/pet_nightflamelarvalyaghra.dds",
                            ["furnitureId"] = 9884,
                            ["id"] = 12447,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Nightflame Larval Yaghra",
                        },
                        [1345] = 
                        {
                            ["description"] = "If one lives in a house haunted by spirits of the departed, acquiring a Haunted House Cat to keep the ghosts company will distract them from haunting you. The fact that it can see the spirits of the dead doesn't keep this cat from being sweet and sociable.",
                            ["icon"] = "/esoui/art/icons/pet_152.dds",
                            ["furnitureId"] = 4454,
                            ["id"] = 1345,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Haunted House Cat",
                        },
                        [12424] = 
                        {
                            ["description"] = "The gifting of live animals is sometimes practiced among Mara's faithful as a sign of a couple's commitment to one another. Though bears are rarely used for this purpose, this one is immeasurably affectionate, with soft fur that begs to be petted.",
                            ["icon"] = "/esoui/art/icons/mount_heartsawebear.dds",
                            ["furnitureId"] = 9879,
                            ["id"] = 12424,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Mara's Awe Bear",
                        },
                        [12423] = 
                        {
                            ["description"] = "Nix-oxen are incredibly adaptable, thriving across Tamriel. This subspecies developed bright markings to attract one another across the heat waves of the desert. Their long legs also allow them to cross the sands easily and stay cool in harsh conditions.",
                            ["icon"] = "/esoui/art/icons/mount_padomaicnixoxsteed.dds",
                            ["furnitureId"] = 9878,
                            ["id"] = 12423,
                            ["category"] = "Arthropods",
                            ["hint"] = "",
                            ["name"] = "Oasis-Strider Nix-Ox",
                        },
                        [12421] = 
                        {
                            ["description"] = "Trophy taken from the Orphic Shattered Shard in honor of an Undaunted victory in the Lucent Citadel.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyshatteredshard001.dds",
                            ["furnitureId"] = 9865,
                            ["id"] = 12421,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Lucent Citadel.",
                            ["name"] = "Trophy: Orphic Shattered Shard",
                        },
                        [12418] = 
                        {
                            ["description"] = "A miniature statue of Peryite, the Daedric Prince of Pestilence.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuetteperyite001.dds",
                            ["furnitureId"] = 9860,
                            ["id"] = 12418,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Peryite, Blightlord",
                        },
                        [12417] = 
                        {
                            ["description"] = "A miniature statue of Auriel, King of the Aldmer. Based on the storied effigy of the same name in the ruins of Garlas Agea along the Gold Coast.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettegarlasagea001.dds",
                            ["furnitureId"] = 9859,
                            ["id"] = 12417,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Auriel of Garlas Agea",
                        },
                        [12416] = 
                        {
                            ["description"] = "\"The metamorphic nature of the voriplasm is a bit of a passion of mine. Nothing in all of Tamriel is as adaptive as this simple-minded gel. My lab sample collection grows daily, showing unbelievable specificity in their adaptations.\"—Gabrielle Benele",
                            ["icon"] = "/esoui/art/icons/pet_vineyardvoriplasm.dds",
                            ["furnitureId"] = 9837,
                            ["id"] = 12416,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Vineyard Voriplasm",
                        },
                        [12273] = 
                        {
                            ["description"] = "When activated, plays a music box arrangement of the profound \"Oath of the Keepers\" composition.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_necfunerarymusicbox001.dds",
                            ["furnitureId"] = 9123,
                            ["id"] = 12273,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Music Box, Oath of the Keepers",
                        },
                        [12272] = 
                        {
                            ["description"] = "This is a small house item.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_bookofwhispers001.dds",
                            ["furnitureId"] = 9164,
                            ["id"] = 12272,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Apocryphal Tome",
                        },
                        [4672] = 
                        {
                            ["description"] = "Perhaps the Atmoran totems and dread-knots sported by the Frostbane Camel actually do help protect it from the bitter cold of Skyrim. Or maybe camels are just too ornery to care.",
                            ["icon"] = "/esoui/art/icons/mounticon_camel_scalecaller.dds",
                            ["furnitureId"] = 4769,
                            ["id"] = 4672,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Frostbane Camel",
                        },
                        [8455] = 
                        {
                            ["description"] = "\"During the long journey from Nenalata to High Rock, beloved mounts became saviors. A song, nearly forgotten, details how a bear named Sunnawend saved Ayleids from a watery grave as they sought to cross a rain-swollen river.\"—Beredalmo the Signifier",
                            ["icon"] = "/esoui/art/icons/mount_ayleidbear.dds",
                            ["furnitureId"] = 7265,
                            ["id"] = 8455,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Nenalata Ayleid Bear",
                        },
                        [1356] = 
                        {
                            ["description"] = "Shadowghost Horses are never bred, only found, and then only on misty nights when both moons are dark. Then they are summoned from beyond by hooded Shadowghost Wranglers, roped and saddled and broken for riding by ordinary mortals.",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_shadow-ghost.dds",
                            ["furnitureId"] = 4455,
                            ["id"] = 1356,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Shadowghost Horse",
                        },
                        [7501] = 
                        {
                            ["description"] = "Once these death hounds served crypt wardens exclusively, stalking the gloomy barrows of Skyrim in search of prey. Now, thanks to an ingenious mage from Solitude, these mounts can serve you, lending you their menacing air.",
                            ["icon"] = "/esoui/art/icons/mount_deathhound.dds",
                            ["furnitureId"] = 6633,
                            ["id"] = 7501,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Crypt Warden Death Hound",
                        },
                        [7502] = 
                        {
                            ["description"] = "Some Alinor scholars claim these indriks form when Magicka mingles with the petals of early-blooming roses. Others note that the roses' thorns need to have drawn blood first. Regardless, this creature inspires creativity in any it follows.",
                            ["icon"] = "/esoui/art/icons/pet_rosethornindrik.dds",
                            ["furnitureId"] = 6634,
                            ["id"] = 7502,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Rosethorn Indrik",
                        },
                        [7503] = 
                        {
                            ["description"] = "As trees awaken in the spring, the first light of dawn sparks the formation of a Sapling Indrik from Magicka-touched acorns. Boundless hope fills those they choose to follow.",
                            ["icon"] = "/esoui/art/icons/pet_saplingindrik.dds",
                            ["furnitureId"] = 6635,
                            ["id"] = 7503,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Sapling Indrik",
                        },
                        [7504] = 
                        {
                            ["description"] = "A miniature statue of Sithis, patron of the Dark Brotherhood.",
                            ["icon"] = "/esoui/art/icons/housing_uni_exc_sithissmall001.dds",
                            ["furnitureId"] = 6636,
                            ["id"] = 7504,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Sithis, Dread Lord",
                        },
                        [7505] = 
                        {
                            ["description"] = "A miniature version of the enigmatic mermaid statue found in Anvil.",
                            ["icon"] = "/esoui/art/icons/housing_nib_exc_dbhselkiestatuesmall001.dds",
                            ["furnitureId"] = 6637,
                            ["id"] = 7505,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Mermaid of Anvil",
                        },
                        [5458] = 
                        {
                            ["description"] = "Trophy taken from Z'Maja in honor of an Undaunted victory in Cloudrest.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtropheysload001.dds",
                            ["furnitureId"] = 5008,
                            ["id"] = 5458,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Cloudrest.",
                            ["name"] = "Trophy: Z'Maja",
                        },
                        [5459] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Cloudrest.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteransload001.dds",
                            ["furnitureId"] = 5007,
                            ["id"] = 5459,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Cloudrest.",
                            ["name"] = "Bust: Z'Maja",
                        },
                        [5460] = 
                        {
                            ["description"] = "This fan allows its bearer to steal another's face; though at the cost of slowly losing themselves.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_handfan001.dds",
                            ["furnitureId"] = 5009,
                            ["id"] = 5460,
                            ["category"] = "General",
                            ["hint"] = "Acquired by completing the \"Relics of Summerset\" achievement.",
                            ["name"] = "Fan of False-Face",
                        },
                        [12263] = 
                        {
                            ["description"] = "\"It's a strange creature, no doubt about that. I'm not sure if it's a bear that became enchanted too close to the sea, or a magical oceanic construct that just happens to look like a bear. Either way, it's a good swimmer.\"—Mage Adept Erwan Cottret",
                            ["icon"] = "/esoui/art/icons/mount_lambentshoalmount.dds",
                            ["furnitureId"] = 9819,
                            ["id"] = 12263,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Shoal Bear",
                        },
                        [8460] = 
                        {
                            ["description"] = "\"Those riding the Nenalata wolves during the evacuation to High Rock served as scouts, moving ahead of the group. Many wrote of Nenagai, who seemed almost prescient in finding hidden dangers and indicating them to his rider.\"—Beredalmo the Signifier",
                            ["icon"] = "/esoui/art/icons/mount_ayleidwolf.dds",
                            ["furnitureId"] = 7270,
                            ["id"] = 8460,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Nenalata Ayleid Wolf",
                        },
                        [8513] = 
                        {
                            ["description"] = "The blazing orange of its hide hints at both the origin and temperament of this guar mount. Though born from and shaped in the fiery Deadlands, you hold the power to temper it into a fierce but loyal mount.",
                            ["icon"] = "/esoui/art/icons/mount_deadlandsguar.dds",
                            ["furnitureId"] = 7341,
                            ["id"] = 8513,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Deadlands Guar",
                        },
                        [12260] = 
                        {
                            ["description"] = "\"Why the flowers? Because this one finds them beautiful, that's why. Charging into battle together does not mean we can't enjoy their colors. And a battlefield littered with petals is a sight to behold.\"—Mathi-jo",
                            ["icon"] = "/esoui/art/icons/mount_ardorsdevotionsencheraht_fix2.dds",
                            ["furnitureId"] = 9816,
                            ["id"] = 12260,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Ardor's Devotion Senche-Raht",
                        },
                        [12259] = 
                        {
                            ["description"] = "\"The great expanse between the planes of the Aurbis is endless night, the Outer Darkness of the Void. Some few things, blessedly few things, live in this endless nothingness. And they are strange beyond imagining.\"—Azandar al-Cybiades",
                            ["icon"] = "/esoui/art/icons/mount_hollowsoulsteed.dds",
                            ["furnitureId"] = 9814,
                            ["id"] = 12259,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Hollowsoul Steed",
                        },
                        [12258] = 
                        {
                            ["description"] = "\"To follow the Dawnway requires faith. We are returning to our roots—to the old magic that the Wild Elves used. You can't expect it to be without its share of weeds. Still, the Green provides.\"—Priest Nothelas, Vashabar",
                            ["icon"] = "/esoui/art/icons/mount_wildburntigerlynx.dds",
                            ["furnitureId"] = 9813,
                            ["id"] = 12258,
                            ["category"] = "Felines",
                            ["hint"] = "Acquired by completing the \"Savior of West Weald\" achievement.",
                            ["name"] = "Wildburn Lynx",
                        },
                        [7515] = 
                        {
                            ["description"] = "Bears afflicted by a necromancer's curse become baneful, easily enraged beasts. Loyal only to their masters, these transformed ursines show no fear in the face of danger, making them excellent battlefield companions.",
                            ["icon"] = "/esoui/art/icons/mount_curseboundbear.dds",
                            ["furnitureId"] = 6639,
                            ["id"] = 7515,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Cursebound Bear",
                        },
                        [7516] = 
                        {
                            ["description"] = "The roar of a sabre cat bridled by a deathless curse shreds a soul to pieces, or so say those at the Bards College in Solitude. Yet that doesn't deter ambitious necromancers from trying to tame these frightening creatures.",
                            ["icon"] = "/esoui/art/icons/mount_curseboundsenche.dds",
                            ["furnitureId"] = 6640,
                            ["id"] = 7516,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Cursebound Sabre Cat",
                        },
                        [7517] = 
                        {
                            ["description"] = "Glorious and deadly. Majestic and haunting. This well-armored steed serves its master faithfully, though its nightmarish appearance once inspired rumors of a ghoulish nature in the area around Cragwallow.",
                            ["icon"] = "/esoui/art/icons/mount_cursebondhorse.dds",
                            ["furnitureId"] = 6641,
                            ["id"] = 7517,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Cursebound Horse",
                        },
                        [5470] = 
                        {
                            ["description"] = "It's said that when Meridia's Aurorans need mounts in Tamriel they conjure these shining Warhorses out of pure light. Perhaps so, but they're certainly solid enough to support a heavily armed warrior at the charge!",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_zenithauroran.dds",
                            ["furnitureId"] = 5410,
                            ["id"] = 5470,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Auroran Zenith Warhorse",
                        },
                        [7519] = 
                        {
                            ["description"] = "The dramatic black and white coloration of this lithe mount makes for striking entrances. Watch out, though! Karthstalkers show affection by trying to groom your face.",
                            ["icon"] = "/esoui/art/icons/mount_sabercatorange.dds",
                            ["furnitureId"] = 6643,
                            ["id"] = 7519,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Karthstalker Sabre Cat",
                        },
                        [7520] = 
                        {
                            ["description"] = "Originally tamed and bred as mounts by the ancient Grimfang Reach clan, these riding bears became popular among Nords who captured them in raids. Despite their inherent docility, these bears anger swiftly when threatened.",
                            ["icon"] = "/esoui/art/icons/mount_duradachbear.dds",
                            ["furnitureId"] = 6644,
                            ["id"] = 7520,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Druadach Mountain Bear",
                        },
                        [7521] = 
                        {
                            ["description"] = "Battlemages within the perfidious Legion Zero conjure these powerful warhorses out of thin air using forbidden Daedric magic. The sight of this otherworldly charger inspires both fear and awe on the battlelines.",
                            ["icon"] = "/esoui/art/icons/mount_legionzero.dds",
                            ["furnitureId"] = 6645,
                            ["id"] = 7521,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Legion Zero Charger",
                        },
                        [7522] = 
                        {
                            ["description"] = "When seen at night, this elk emanates a faint glow, rivaling the unusual color shifts in the northern skies of Skyrim or the glowing fungus of Blackreach's vast caves. Stunning!",
                            ["icon"] = "/esoui/art/icons/mount_valedeerxb.dds",
                            ["furnitureId"] = 6646,
                            ["id"] = 7522,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Pineblossom Vale Elk",
                        },
                        [7523] = 
                        {
                            ["description"] = "This elk's blue luminescence stems from its origins, claim Mages Guild scholars: they coalesce from a beam of pure light, blessed by Azura, that falls upon a drift of snow. Or perhaps, as others state, its diet of blue entolomas causes the azure glow.",
                            ["icon"] = "/esoui/art/icons/mount_valedeerp4.dds",
                            ["furnitureId"] = 6647,
                            ["id"] = 7523,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Snowdrift Vale Elk",
                        },
                        [7524] = 
                        {
                            ["description"] = "Some claim a ghost possesses this proud steed, providing it with a haunting glow. Others point to its chosen diet: glowing flora and fungi. Regardless, riders feel as if they're gliding on air.",
                            ["icon"] = "/esoui/art/icons/mount_valedeerpc.dds",
                            ["furnitureId"] = 6648,
                            ["id"] = 7524,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Hailcinder Vale Elk",
                        },
                        [1381] = 
                        {
                            ["description"] = "Unlike nearly all other wolves, the Shadowghost Wolf has no pack and lives a solitary life, haunting lonely moors and wastelands, appearing only at night and rarely then. Some doubt it is a real creature of the mortal plane at all.",
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_shadow-ghost.dds",
                            ["furnitureId"] = 4472,
                            ["id"] = 1381,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Shadowghost Wolf",
                        },
                        [7526] = 
                        {
                            ["description"] = "\"Pure white, these bats, making them hard to see in wintry conditions. But give one a bit of banana, and it'll stick close to you for a while. With a constant diet of bananas and other fruits? You are its boon companion.\"—Tanandra, Scholar-Errant",
                            ["icon"] = "/esoui/art/icons/pet_batwhite.dds",
                            ["furnitureId"] = 6650,
                            ["id"] = 7526,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Snow Throat Fruit Bat",
                        },
                        [7527] = 
                        {
                            ["description"] = "\"Normally you don't see these black bats because they prefer caves and other areas avoided by people. However, if trained, these fellows consider you a member of their colony and hate to leave your side.\"—Tanandra, Scholar-Errant",
                            ["icon"] = "/esoui/art/icons/pet_batblack.dds",
                            ["furnitureId"] = 6651,
                            ["id"] = 7527,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Shadowswift Bat",
                        },
                        [7528] = 
                        {
                            ["description"] = "\"People blessed by these brown bat companions experience very few issues with insects. They love hiding in your pack during the day, and they'll keep you bug-free while you sleep at night.\"—Tanandra, Scholar-Errant",
                            ["icon"] = "/esoui/art/icons/pet_batbrown.dds",
                            ["furnitureId"] = 6652,
                            ["id"] = 7528,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Brown Steeple Bat",
                        },
                        [7529] = 
                        {
                            ["description"] = "\"Sometimes called Friends of the Caravan, these black-and-white bats migrate among cacti stands in arid regions. Trackers follow their guano to find hydrating, safe cacti when in need. Easily trained to be a companion.\"—Tanandra, Scholar-Errant",
                            ["icon"] = "/esoui/art/icons/pet_batspotted.dds",
                            ["furnitureId"] = 6653,
                            ["id"] = 7529,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Dappled Cactus Bat",
                        },
                        [7530] = 
                        {
                            ["description"] = "\"So colorful! And common around orchards, farms, and other places with cultivated fruit and flowers. A priceless companion for foragers and travelers since they can lead you to food.\"—Tanandra, Scholar-Errant",
                            ["icon"] = "/esoui/art/icons/pet_batorange.dds",
                            ["furnitureId"] = 6654,
                            ["id"] = 7530,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Duskfire Nectar Bat",
                        },
                        [7531] = 
                        {
                            ["description"] = "Legends claim that Dibella sent one of these joyful gryphon fledglings to the Bards College during the bards' opening performance, marking it as being the first creature inside the building.",
                            ["icon"] = "/esoui/art/icons/pet_bardscollegegryphon.dds",
                            ["furnitureId"] = 6655,
                            ["id"] = 7531,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Skald-Muse Fledgling Gryphon",
                        },
                        [7532] = 
                        {
                            ["description"] = "Decades ago, Nords whispered stories of a reclusive dark-furred lynx that ate spirits barred from Sovngarde. Imagine the Nords' surprise when they found these lynxes domesticated as tent guards during a raid on Reach natives.",
                            ["icon"] = "/esoui/art/icons/pet_lynxumbral.dds",
                            ["furnitureId"] = 6656,
                            ["id"] = 7532,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Twilight Striped Lynx",
                        },
                        [7533] = 
                        {
                            ["description"] = "Known for both their stubbornness and their ability to climb on structures at the worst possible times, the Whiterun Mottled Goat picks a favorite person and tries to follow them. Affectionate? Only if you find gentle headbutts to be so.",
                            ["icon"] = "/esoui/art/icons/pet_goatvariant.dds",
                            ["furnitureId"] = 6657,
                            ["id"] = 7533,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Whiterun Mottled Goat",
                        },
                        [7534] = 
                        {
                            ["description"] = "\"Though I lost many trained frostbite spiders to those who took them for an aggressive infestation of Solitude, I moved outside town and now give them away. They are trained, venomous, and ready to follow you in your travels!\"—Hlokela of Solitude",
                            ["icon"] = "/esoui/art/icons/pet_frostbitespider.dds",
                            ["furnitureId"] = 6658,
                            ["id"] = 7534,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Frostbite Spider",
                        },
                        [7535] = 
                        {
                            ["description"] = "Enterprising merchants seek out and capture these delightful little creatures, calling them either \"bunnies\" or, if the buyer prefers accuracy or a certain level of decorum, Pale Pass Mountain Hares. So cute!",
                            ["icon"] = "/esoui/art/icons/pet_palepasshare.dds",
                            ["furnitureId"] = 6659,
                            ["id"] = 7535,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Pale Pass Mountain Hare",
                        },
                        [7536] = 
                        {
                            ["description"] = "\"These fastidious cats bring the blessing of Tu'whacca and hold a place of honor within their chosen homes. Further, they often start sleeping with any who near death, and thus we venerate them as guides to the Far Shores.\"—Tanandra, Scholar-Errant",
                            ["icon"] = "/esoui/art/icons/pet_graysphynx.dds",
                            ["furnitureId"] = 6660,
                            ["id"] = 7536,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Tu'whacca's Sphynx Cat",
                        },
                        [1393] = 
                        {
                            ["description"] = "Flame Atronachs are summoned from the Oblivion plane of Infernace, a realm so hot that molten rock flows across its surface, and its Daedra are creatures of living flame. Summoned to Tamriel, such atronachs can be given almost any shape, even a Guar!",
                            ["icon"] = "/esoui/art/icons/mounticon_flameatronach_guar_a.dds",
                            ["furnitureId"] = 4475,
                            ["id"] = 1393,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Flame Atronach Guar",
                        },
                        [1394] = 
                        {
                            ["description"] = "When the Empress Hestra led her legions in harrying the Vampire King Styriche and his Gray Host into western Hammerfell, it's said she did so while riding a great Flame Atronach Bear Mount named Fiery Ursula.",
                            ["icon"] = "/esoui/art/icons/mounticon_flameatronach_bear_a.dds",
                            ["furnitureId"] = 4476,
                            ["id"] = 1394,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Flame Atronach Bear",
                        },
                        [1395] = 
                        {
                            ["description"] = "Blending in with the shifting gray ash clouds on the slopes of Red Mountain, the Shadowghost Guar are the only known nocturnal breed of the species, and thus are rarely seen, even by the native Dark Elves.",
                            ["icon"] = "/esoui/art/icons/mounticon_guar_shadow-ghost.dds",
                            ["furnitureId"] = 4477,
                            ["id"] = 1395,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Shadowghost Guar",
                        },
                        [1396] = 
                        {
                            ["description"] = "Rarely seen outside the ash clouds of Vvardenfell's great volcano, the little Shadowghost pony guar is scary cute.",
                            ["icon"] = "/esoui/art/icons/pet_148.dds",
                            ["furnitureId"] = 4478,
                            ["id"] = 1396,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Shadowghost Guar",
                        },
                        [12257] = 
                        {
                            ["description"] = "\"Many strange and wonderous things hail from Mirrormoor. Perhaps this creature walked here along the threads of fate to assist you on your journey.\"—Keeper Adiir",
                            ["icon"] = "/esoui/art/icons/mount_refulgentmirrormoorsteed.dds",
                            ["furnitureId"] = 9812,
                            ["id"] = 12257,
                            ["category"] = "Equines",
                            ["hint"] = "Acquired by completing the \"Knot Worthy\" achievement.",
                            ["name"] = "Refulgent Mirrormoor Steed",
                        },
                        [8539] = 
                        {
                            ["description"] = "Originally from General Thibault's hunting pack, these dogs later gained a reputation as fierce defenders of Greenhill's livestock and grain. If you're looking to keep rats out of your bags plus gain a loyal companion to hug, this handsome dog is for you.",
                            ["icon"] = "/esoui/art/icons/pet_greenhillfarmdog.dds",
                            ["furnitureId"] = 7367,
                            ["id"] = 8539,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Greenhill Farmdog",
                        },
                        [11639] = 
                        {
                            ["description"] = "A miniature statue of a Telvanni Mage, carved to venerate a Magister long past but not forgotten.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingu40magistratestatuette003.dds",
                            ["furnitureId"] = 9357,
                            ["id"] = 11639,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Telvanni Magister",
                        },
                        [11640] = 
                        {
                            ["description"] = "A painting depicting just one of the innumerable studies within the Endless Library of Hermaeus Mora.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingu40apocryphalibrarypainting001.dds",
                            ["furnitureId"] = 9358,
                            ["id"] = 11640,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Painting: The Endless Library",
                        },
                        [11641] = 
                        {
                            ["description"] = "\"Trust the Tharns to find a way to make a senche even more regal than it already was. I feel underdressed. Do you think it outranks me?\"—Legionary Liodes Salvius",
                            ["icon"] = "/esoui/art/icons/mount_companionrevelrysenche.dds",
                            ["furnitureId"] = 9359,
                            ["id"] = 11641,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Tharn's Lucent Revelry Senche",
                        },
                        [11642] = 
                        {
                            ["description"] = "Legend says that Mannimarco himself indoctrinated this Senche-raht to the way of the Anchorite. It's unknown if Zalzagh knows whether this is true, or if they have any recollection of life before joining the Worm Cult.",
                            ["icon"] = "/esoui/art/icons/mount_wormanchoritesencheraht.dds",
                            ["furnitureId"] = 9360,
                            ["id"] = 11642,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Worm Cultist Senche-Raht",
                        },
                        [11643] = 
                        {
                            ["description"] = "\"I've always preferred moose to elk or horses. In battle they're more reliable, they're cussed strong, and for overland travel they can't be beat. Plus, their noses are just so soft!\" —Yvon Serielle, Daggerfall",
                            ["icon"] = "/esoui/art/icons/pet_highrockpillionmoose.dds",
                            ["furnitureId"] = 9361,
                            ["id"] = 11643,
                            ["category"] = "Multi-Rider",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["name"] = "Seaghost Pillion Moose",
                        },
                        [11644] = 
                        {
                            ["description"] = "\"Yes, this one will do nicely. As vengeful and accursed as my master. It bears the mark of Malacath well—our enemies will cower before us! May it lap the blood of its prey on the broken path we ride.\"—Ogmash the Mighty",
                            ["icon"] = "/esoui/art/icons/mount_ashbonesabrecat.dds",
                            ["furnitureId"] = 9362,
                            ["id"] = 11644,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Ashbone Sabre Cat",
                        },
                        [11645] = 
                        {
                            ["description"] = "Even at this small size, this echalette is rather vicious. It's not afraid to use its tiny tusks to ram perceived threats, other echalettes, or really anything that moves. It's not a very effective tactic, but it is strangely cute.",
                            ["icon"] = "/esoui/art/icons/pet_ashborneechalette.dds",
                            ["furnitureId"] = 9363,
                            ["id"] = 11645,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ashbone Echalette",
                        },
                        [11646] = 
                        {
                            ["description"] = "\"Look at the scales on this one! I did not know Useful Lizards could be so beautiful. Perhaps that is its use? Spreading beauty throughout the marsh? I will wallow with it and see if the Hist grant any more insight.\"—Thinks-too-Much, Stormhold",
                            ["icon"] = "/esoui/art/icons/pet_goldcrestancestorlizard.dds",
                            ["furnitureId"] = 9383,
                            ["id"] = 11646,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Goldcrest Ancestor Lizard",
                        },
                        [11647] = 
                        {
                            ["description"] = "Prized for their striking plumage, Ashen Scar fellrunners are also highly intelligent. They bond quickly with their caretakers but are known to be quite ornery when stared at for too long. It's best to avoid eye contact when possible.",
                            ["icon"] = "/esoui/art/icons/pet_highsavannahfellrunner.dds",
                            ["furnitureId"] = 9384,
                            ["id"] = 11647,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ashen Scar Fellrunner",
                        },
                        [11648] = 
                        {
                            ["description"] = "Less fearsome than they look, the native guar of Alavelis have developed peculiar markings. Some believe they are a mimicry of the poisonous beasts of the Telvanni Peninsula, though the guar themselves have no such defense.",
                            ["icon"] = "/esoui/art/icons/mount_alavelisringedguar.dds",
                            ["furnitureId"] = 9385,
                            ["id"] = 11648,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Alavelis Ringed Guar",
                        },
                        [1409] = 
                        {
                            ["description"] = "It was the master summoners of the Direnni who first discovered that a conjurer could impose any desired shape on a Flame Atronach—even that of a horse. Direnni mages mounted on flaming horses first appeared at the Battle of Glenumbria Moors.",
                            ["icon"] = "/esoui/art/icons/mounticon_flameatronach_horse_a.dds",
                            ["furnitureId"] = 4479,
                            ["id"] = 1409,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Flame Atronach Horse",
                        },
                        [1410] = 
                        {
                            ["description"] = "For centuries the conjurers' standard spell for summoning Flame Atronachs has been Koron's Peremptory Summons, which is easily modified to change both the duration of the summoned atronach's binding and its form—for example, into that of a senche-tiger.",
                            ["icon"] = "/esoui/art/icons/mounticon_flameatronach_senche_a.dds",
                            ["furnitureId"] = 4480,
                            ["id"] = 1410,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Flame Atronach Senche",
                        },
                        [1411] = 
                        {
                            ["description"] = "\"An oversized Flame Atronach Wolf makes for an impressive mount,\" wrote arch-conjurer Corvus Direnni, \"but it's inconvenient to house such a steed in flammable stables. When I'm not riding mine, I temporarily lodge it in a pocket realm Adjacent Place.\"",
                            ["icon"] = "/esoui/art/icons/mounticon_flameatronach_wolf_a.dds",
                            ["furnitureId"] = 4481,
                            ["id"] = 1411,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Flame Atronach Wolf",
                        },
                        [1412] = 
                        {
                            ["description"] = "Summoned from the Infernace plane of Oblivion, this Flame Atronach variant is given the form of a charming little bear cub. Good for warming hearts and hands alike!",
                            ["icon"] = "/esoui/art/icons/pet_160.dds",
                            ["furnitureId"] = 4482,
                            ["id"] = 1412,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Flame Atronach Bear Cub",
                        },
                        [1413] = 
                        {
                            ["description"] = "Sabre Cats, of course, are inured to the harsh, wintry conditions of Skyrim, and scarcely need warding from the cold; kitting them out as Frostbane mounts is therefore more a question of tradition than of protection.",
                            ["icon"] = "/esoui/art/icons/mounticon_senche_scalecaller.dds",
                            ["furnitureId"] = 4773,
                            ["id"] = 1413,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Frostbane Sabre Cat",
                        },
                        [1414] = 
                        {
                            ["description"] = "Summoned from Oblivion, this shadow atronach was made all the more grand by being compelled to take the form of a senche mount. It's popular amongst those who wish to move quickly and quietly through the more dangerous realms of Tamriel.",
                            ["icon"] = "/esoui/art/icons/mounticon_senche_shadowatronach.dds",
                            ["furnitureId"] = 4484,
                            ["id"] = 1414,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Shadow Atronach Senche",
                        },
                        [1415] = 
                        {
                            ["description"] = "The first summoner of this fiery kitten was attempting to compel the Daedra into the form of a full-grown senche-jaguar. Though initially embarrassed by her mistake, she nonetheless grew an attachment to this far more adorable form.",
                            ["icon"] = "/esoui/art/icons/pet_161.dds",
                            ["furnitureId"] = 4485,
                            ["id"] = 1415,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Flame Atronach Senche-Jaguar",
                        },
                        [1416] = 
                        {
                            ["description"] = "\"Though smaller than its mount counterpart,\" wrote arch-conjurer Corvus Direnni, \"it's necessary to take all precautions when handling the Flame Atronach Pack Wolf. I've found their curiosity insatiable, especially when near flammable objects.\"",
                            ["icon"] = "/esoui/art/icons/pet_158.dds",
                            ["furnitureId"] = 4486,
                            ["id"] = 1416,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Flame Atronach Pack Wolf",
                        },
                        [1417] = 
                        {
                            ["description"] = "Due to the unusually tame nature of the Flame Atronach Pocket Horse, it has a long tradition of being the companion of younger members of the Direnni clan. It's a good introduction to Daedric summoning for any budding conjurer.",
                            ["icon"] = "/esoui/art/icons/pet_157.dds",
                            ["furnitureId"] = 4487,
                            ["id"] = 1417,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Flame Atronach Pocket Horse",
                        },
                        [1418] = 
                        {
                            ["description"] = "After years of conjuring, Peregine Direnni sought a new Daedra to compel to be her mount. She took an immediate liking to the Cold-Flame Atronach, found in the Daedric realm of Takubar. Summoning it in the form of a wolf just added extra flair.",
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_coldflameatronach.dds",
                            ["furnitureId"] = 4488,
                            ["id"] = 1418,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Cold-Flame Atronach Wolf",
                        },
                        [8540] = 
                        {
                            ["description"] = "Both the fleecy white sheep and their doughty shepherds enjoy the clear water of Cloud Spring in High Rock. Though dangers abound, the sheep avoid the worst of it, making the rumors of their ability to sense and avoid peril seem plausible.",
                            ["icon"] = "/esoui/art/icons/pet_sheep.dds",
                            ["furnitureId"] = 7368,
                            ["id"] = 8540,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Cloud Spring White Sheep",
                        },
                        [8847] = 
                        {
                            ["description"] = "Javinus Tirnendo left the Order of the Waking Flame, a cult dedicated to Mehrunes Dagon. Now he seeks refuge from his former allies. Will you help? After adding Javinus to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/assistant_javinustirnendo.dds",
                            ["furnitureId"] = 7401,
                            ["id"] = 8847,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Javinus Tirnendo",
                        },
                        [7525] = 
                        {
                            ["description"] = "In an annual Windhelm competition, contestants must ride their potential prizes up a mountain then down at top speeds—bareback and without falling off. Most rams toss riders into the air on purpose, validating the claim that the ram chooses its rider.",
                            ["icon"] = "/esoui/art/icons/mount_ram.dds",
                            ["furnitureId"] = 6649,
                            ["id"] = 7525,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Yorgrim River Ram",
                        },
                        [9009] = 
                        {
                            ["description"] = "Scholars disagree on whether these iron atronach steeds took on the aeonstone hues during the summoning ritual intentionally or after by mistake. Motives aside, riders magically summon these mounts, creating an impressively explosive visual impact.",
                            ["icon"] = "/esoui/art/icons/mount_radironatrohorse.dds",
                            ["furnitureId"] = 7524,
                            ["id"] = 9009,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Viridian Iron Steed",
                        },
                        [9516] = 
                        {
                            ["description"] = "\"There's something out there, stalking me through the dark underbrush. My eyes deceive me and see only stars moving across a starless sky. They growl and bare their pointed teeth. Vaermina take pity.\"—Havaldar the Crazed",
                            ["icon"] = "/esoui/art/icons/mount_celestialwolf.dds",
                            ["furnitureId"] = 7864,
                            ["id"] = 9516,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Star-Born Guardian Wolf",
                        },
                        [9524] = 
                        {
                            ["description"] = "Exquisitely designed, this warm-hued tapestry of Blackwood serves as both an art piece and a practical guide to the region.",
                            ["icon"] = "/esoui/art/icons/housing_bad_inc_leyblackwoodtapestry001.dds",
                            ["furnitureId"] = 7885,
                            ["id"] = 9524,
                            ["category"] = "General",
                            ["hint"] = "Acquired as an Antiquity, found in Blackwood.",
                            ["name"] = "Blackwood Tapestry",
                        },
                        [9565] = 
                        {
                            ["description"] = "\"When Sir Byric's flames razed the ground outside our walls and the Reachfolk hurled stones at our walls. I stood tall at my post, knowing that our smallest knights padded the ramparts alongside me.\"—Sir Hughes, Alcaire Castle",
                            ["icon"] = "/esoui/art/icons/pet_kotfrpup.dds",
                            ["furnitureId"] = 7892,
                            ["id"] = 9565,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Knights of the Flame Pup",
                        },
                        [9566] = 
                        {
                            ["description"] = "A miniature statue of Sai Sahan, the liberator of Leyawiin.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettesaisahan001.dds",
                            ["furnitureId"] = 7895,
                            ["id"] = 9566,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Sai Sahan, Deliverer",
                        },
                        [1427] = 
                        {
                            ["description"] = "This colorful guar was once thought to be poisonous by many, but found to be relatively harmless by an adventuresome rider. Caution! Patience is needed to bring this obstinate mount to heed.",
                            ["icon"] = "/esoui/art/icons/mounticon_guar_skyfire.dds",
                            ["furnitureId"] = 4489,
                            ["id"] = 1427,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Skyfire Guar",
                        },
                        [9567] = 
                        {
                            ["description"] = "A miniature statue of Zenithar, holding an anvil.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettezenithar001.dds",
                            ["furnitureId"] = 7896,
                            ["id"] = 9567,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Zenithar, God of Toil",
                        },
                        [9568] = 
                        {
                            ["description"] = "The Khajiit called M'aiq the Liar travels widely, speaking foolishly—or wisely, depending on whom you ask. Host him before deciding, yes? After adding M'aiq to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/houseguest_maiq.dds",
                            ["furnitureId"] = 7901,
                            ["id"] = 9568,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "M'aiq the Liar",
                        },
                        [9569] = 
                        {
                            ["description"] = "Is your home bedecked in shiny treasures? Did you leave carrion out in the sun? Regardless, Blackfeather Court's most nettlesome squire noticed! After adding Squire Caw to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/houseguest_squirecaw.dds",
                            ["furnitureId"] = 7902,
                            ["id"] = 9569,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Squire Caw",
                        },
                        [1431] = 
                        {
                            ["description"] = "These perky metal creations are known to pack quite the pinch. Though their rust-resistant coatings do enable them to enter into water, they're far better at sinking than swimming.",
                            ["icon"] = "/esoui/art/icons/pet_156.dds",
                            ["furnitureId"] = 4763,
                            ["id"] = 1431,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Prodigious Brass Mudcrab",
                        },
                        [1432] = 
                        {
                            ["description"] = "Hailing from the heart of Elsweyr, these striped mounts are known for their gentle and trusting natures. Once they found them incompetent as watchdogs, the villagers of Helkarn bred them to mountable size.",
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_helkarn.dds",
                            ["furnitureId"] = 4757,
                            ["id"] = 1432,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Helkarn Wolf",
                        },
                        [9570] = 
                        {
                            ["description"] = "Trained in the Battlespire, Lucilla Caprenia made a decision that altered her future. As she ponders her next steps, invite her into your abode! After adding Lucilla to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["icon"] = "/esoui/art/icons/houseguest_lucilla.dds",
                            ["furnitureId"] = 7903,
                            ["id"] = 9570,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Lucilla Caprenia",
                        },
                        [9571] = 
                        {
                            ["description"] = "A painting of the Havocrel named Baron Zaudrus, defeating those who oppose him.",
                            ["icon"] = "/esoui/art/icons/housing_bad_inc_housingwoodframewakingflamepainting001.dds",
                            ["furnitureId"] = 7897,
                            ["id"] = 9571,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Painting: Baron Zaudrus Triumphs",
                        },
                        [10202] = 
                        {
                            ["description"] = "\"We value elk for their nimble hooves and gentle nature. They accompany us where larger beasts cannot go. They do not shirk in the face of danger or abandon their work. I wish I could say the same about some of the initiates! Hmph!\"—Druid Barjot",
                            ["icon"] = "/esoui/art/icons/mount_stoneloreelk.dds",
                            ["furnitureId"] = 8252,
                            ["id"] = 10202,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Stonelore Elk",
                        },
                        [10203] = 
                        {
                            ["description"] = "Druid stories say that the first foxes swam from Y'ffelon shortly before Mount Firesong spewed ash and flame. Those who befriend a Stonelore fox live long lives, though the Stonelore insist it has nothing to do with the fox's survival instincts.",
                            ["icon"] = "/esoui/art/icons/mount_stonelorefox.dds",
                            ["furnitureId"] = 8253,
                            ["id"] = 10203,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Stonelore Fox",
                        },
                        [1437] = 
                        {
                            ["description"] = "This festive horse is sure to spread holiday cheer! The proud owner of such a steed can be almost assured that they have the handsomest horse in town.",
                            ["icon"] = "/esoui/art/icons/mounticon_wintergarlanddapplegray.dds",
                            ["furnitureId"] = 4758,
                            ["id"] = 1437,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Winter Garland Dapple Gray",
                        },
                        [10204] = 
                        {
                            ["description"] = "\"This one adores the guar with its useless small arms and big round head. J'zurdru and the guar bonded over a love of belly rubs. Also napping on warm rocks and watching the clouds in the sky. Lazy but very relaxing, yes?\"—Druid J'zurdru",
                            ["icon"] = "/esoui/art/icons/mount_stoneloreguar.dds",
                            ["furnitureId"] = 8254,
                            ["id"] = 10204,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Stonelore Guar",
                        },
                        [9631] = 
                        {
                            ["description"] = "Trophy taken from Prior Thierric Sarazen in honor of an Undaunted victory in Red Petal Bastion.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyartifactmaster001.dds",
                            ["furnitureId"] = 8024,
                            ["id"] = 9631,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Red Petal Bastion.",
                            ["name"] = "Trophy: Prior Thierric Sarazen",
                        },
                        [1440] = 
                        {
                            ["description"] = "This experimental variation on the standard Brassilisk has certain key components fabricated from an Ebony alloy for enhanced durability out in the storms of the Radius.",
                            ["icon"] = "/esoui/art/icons/pet_154.dds",
                            ["furnitureId"] = 4469,
                            ["id"] = 1440,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ebony Brassilisk",
                        },
                        [1441] = 
                        {
                            ["description"] = "Compelled to take the form of a small guar, this flame atronach makes for a great traveling companion, especially in colder climates. It's best to summon your newfound friend only when outdoors, since its mischievous nature might lead to accidents.",
                            ["icon"] = "/esoui/art/icons/pet_159.dds",
                            ["furnitureId"] = 4761,
                            ["id"] = 1441,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Flame Atronach Pony Guar",
                        },
                        [9634] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in the Dread Cellar.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranearthincarnate001.dds",
                            ["furnitureId"] = 8025,
                            ["id"] = 9634,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran The Dread Cellar.",
                            ["name"] = "Bust: Magma Incarnate",
                        },
                        [5539] = 
                        {
                            ["description"] = "This headstrong crystal skull ignored your decision to give it away and elected to stay with you instead. It could tell you all about the sublime mysteries of creation, but would much rather rant, joke, and complain.",
                            ["icon"] = "/esoui/art/icons/quest_crystalskull001.dds",
                            ["furnitureId"] = 5418,
                            ["id"] = 5539,
                            ["category"] = "General",
                            ["hint"] = "Acquired by completing the \"Psijic Sage\" achievement.",
                            ["name"] = "Augur of the Obscure",
                        },
                        [1444] = 
                        {
                            ["description"] = "This chilling steed was created from a Frost Atronach that was conjured into the shape of a horse. Perfect for an adventurer visiting a warmer climate, this steed can help you stay cool even in extreme temperatures.",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_nightfrostatronach.dds",
                            ["furnitureId"] = 4755,
                            ["id"] = 1444,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Night Frost Atronach Steed",
                        },
                        [9637] = 
                        {
                            ["description"] = "Happiest when climbing their native Valus Mountains, these sure-footed mounts grudgingly accept both saddle and reins for as long as their rider allows them to keep moving—or provides them with prodigious amounts of mountain flower treats.",
                            ["icon"] = "/esoui/art/icons/mount_clawhornmountaingoat.dds",
                            ["furnitureId"] = 7914,
                            ["id"] = 9637,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Clawhorn Mountain Goat",
                        },
                        [10205] = 
                        {
                            ["description"] = "\"It may be a little biased of us, but predators take longer to earn their horns. I suppose we just want proof that they're well-trained before we give them another weapon. Still, little Ivy was so proud when she got hers.\"—Druid Celina, Beast Master",
                            ["icon"] = "/esoui/art/icons/mount_stonelorelynx.dds",
                            ["furnitureId"] = 8255,
                            ["id"] = 10205,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Stonelore Lynx",
                        },
                        [1447] = 
                        {
                            ["description"] = "Even for the elusive senche-leopard, the Spotted Snow is a rare variety. Despite its frosty-looking fur, this adorable companion makes for a great cuddle buddy during long winter nights.",
                            ["icon"] = "/esoui/art/icons/pet_163.dds",
                            ["furnitureId"] = 4765,
                            ["id"] = 1447,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Spotted Snow Senche-Leopard",
                        },
                        [1448] = 
                        {
                            ["description"] = "The White-Gold Imperial Pony was said to have made its debut as the birthday present for a noble's daughter, though which family claims this prestige is still hotly debated throughout Cyrodiil.",
                            ["icon"] = "/esoui/art/icons/pet_155.dds",
                            ["furnitureId"] = 4767,
                            ["id"] = 1448,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "White-Gold Imperial Pony",
                        },
                        [10328] = 
                        {
                            ["description"] = "\"Studies into ragebound breeds trace their lineage to Hircine and the Reach. Legend says the Lord of the Hunt gifted the first Ragebound Horse to a tribe after witnessing them chase down a vampire. On foot. In the dark.\"—Beastmaster's Practical Bestiary",
                            ["icon"] = "/esoui/art/icons/mount_rageboundhorse.dds",
                            ["furnitureId"] = 8388,
                            ["id"] = 10328,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Ragebound Steed",
                        },
                        [10329] = 
                        {
                            ["description"] = "\"When you're at your worst—when the only thing keeping you going is pure rage? That is the moment you know its strength. These cats will happily teach you this lesson, if you need a tutor.\"—Arparnagh of Markarth",
                            ["icon"] = "/esoui/art/icons/mount_rageboundsabrecat.dds",
                            ["furnitureId"] = 8389,
                            ["id"] = 10329,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Ragebound Sabre Cat",
                        },
                        [5547] = 
                        {
                            ["description"] = "While it's unclear whether this little netch understands the nuances behind the Witches Festival's many traditions, its joyous tootling is reason enough to let it join in the celebrations.",
                            ["icon"] = "/esoui/art/icons/pet_witchespartyghostnetch.dds",
                            ["furnitureId"] = 5438,
                            ["id"] = 5547,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Witches Festival Ghost Netch",
                        },
                        [5548] = 
                        {
                            ["description"] = "Less common than the usual variety, the Pale-Plume Gryphons are found only along the seacoast cliffs near the Tower of Dusk in southeast Summerset. Their Fledglings make engaging pets that can be trained to follow their masters even into danger.",
                            ["icon"] = "/esoui/art/icons/pet_187_eaglegryphon.dds",
                            ["furnitureId"] = 5441,
                            ["id"] = 5548,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Pale-Plume Fledgling Gryphon",
                        },
                        [5549] = 
                        {
                            ["description"] = "It's believed by some of the Sapiarchs of the High Elves that an Onyx Indrik comes about when a Nascent Indrik is exposed to certain berries imbued with geological Earthbones essences.",
                            ["icon"] = "/esoui/art/icons/mounticon_indrik_onyx.dds",
                            ["furnitureId"] = 5420,
                            ["id"] = 5549,
                            ["category"] = "Cervines",
                            ["hint"] = "Obtained by combining four different Onyx Berries with a Nascent Indrik mount. The Nascent Indrik will become the Onyx Indrik.",
                            ["name"] = "Onyx Indrik",
                        },
                        [5550] = 
                        {
                            ["description"] = "Some find it strange that the Pure-Snow Indrik should exist in Summerset, where winter never comes, but as the Sapiarch of Elemental Arcana points out, \"Frost magic works everywhere.\"",
                            ["icon"] = "/esoui/art/icons/mounticon_indrik_snow.dds",
                            ["furnitureId"] = 5421,
                            ["id"] = 5550,
                            ["category"] = "Cervines",
                            ["hint"] = "Obtained by combining four different Pure-Snow Berries with a Nascent Indrik mount. The Nascent Indrik will become the Pure-Snow Indrik.",
                            ["name"] = "Pure-Snow Indrik",
                        },
                        [5551] = 
                        {
                            ["description"] = "Calamity and mischance seem to follow in the hoofprints of this dark charger—but not for its rider! Gallop into battle on the back of this Soot Stallion and curse your opponents with all the ill luck of Black Fredas!",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_blackfredas.dds",
                            ["furnitureId"] = 5422,
                            ["id"] = 5551,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Black Fredas Soot Stallion",
                        },
                        [5552] = 
                        {
                            ["description"] = "When the dro-m'Athra ride from the Dark Behind the World, they go mounted on these dread steeds: the Rahd-m'Athra! Are they spirits from the Dark Moons, or tangible creatures of evil?",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_rahdmanthra.dds",
                            ["furnitureId"] = 5423,
                            ["id"] = 5552,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Rahd-m'Athra",
                        },
                        [5553] = 
                        {
                            ["description"] = "\"Almost every stablemaster of the Marsh has fine, scaly lizard mounts available for purchase in various forms, all familiar to dryskins but specifically adapted to deep swamp conditions. So convenient, our lizard-steeds, so scaly and personable!\" —Ukaspa",
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_wolf.dds",
                            ["furnitureId"] = 5424,
                            ["id"] = 5553,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Wolf-Lizard Steed",
                        },
                        [5554] = 
                        {
                            ["description"] = "\"More than once I have been asked, 'Ukaspa, why are your lizard-steeds shaped like mounts from other parts of Tamriel? Why aren't your so-very-handsome mounts shaped like, well, lizards?' These are good questions!\" —Ukaspa of Lilmoth",
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_senche.dds",
                            ["furnitureId"] = 5425,
                            ["id"] = 5554,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Senche-Lizard Steed",
                        },
                        [5555] = 
                        {
                            ["description"] = "\"Some dryskins ask, 'Since a Guar is already a swamp reptile mount, why create Lizard-Steeds shaped like Guar? Isn't that somewhat redundant?' These dryskins are unusually perceptive!\" —Ukaspa of Lilmoth",
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_guar.dds",
                            ["furnitureId"] = 5426,
                            ["id"] = 5555,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Guar-Lizard Steed",
                        },
                        [5556] = 
                        {
                            ["description"] = "\"Maybe the Camel-Lizard was created so we heroic Argonian adventurers could travel in arid climes like Anequina—or maybe it was so heroic Khajiiti adventurers could have something to ride in Black Marsh. I don't know, I just want one.\" —Heem-Jas",
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_camel.dds",
                            ["furnitureId"] = 5427,
                            ["id"] = 5556,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Camel-Lizard Steed",
                        },
                        [5557] = 
                        {
                            ["description"] = "\"So, it's a Bear. Only it's a Lizard. And you can ride it? Shor's bones! That's all I need to know. I'll take it!\" —Celebrated Nord Envoy Rigurt the Brash",
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_bear.dds",
                            ["furnitureId"] = 5428,
                            ["id"] = 5557,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Bear-Lizard Steed",
                        },
                        [5558] = 
                        {
                            ["description"] = "\"Sometimes Argonians want to travel a long way for a long time, and how do people do that? On mounts! And so useful lizards become Lizard Steeds of proven shapes, and then Argonians can ride, tall in the saddle and proud!\" —Ukaspa of Lilmoth",
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_horse.dds",
                            ["furnitureId"] = 5429,
                            ["id"] = 5558,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Horse-Lizard Steed",
                        },
                        [5559] = 
                        {
                            ["description"] = "A Frost Mage of Clan Direnni spent her entire life perfecting a spell to permanently summon a Frost Atronach in the shape of a Sabre Cat. (Why? Who knows? Balfiera Island is a strange place.)",
                            ["icon"] = "/esoui/art/icons/mounticon_senche_frost.dds",
                            ["furnitureId"] = 5430,
                            ["id"] = 5559,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Sabre Cat Frost Atronach",
                        },
                        [5560] = 
                        {
                            ["description"] = "Argonian heavy troops are informally known as Shellbacks—so inevitably, their heavy cavalry mounts are called Shellback Warhorses. They are among the strongest breeds known.",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_shellback.dds",
                            ["furnitureId"] = 5431,
                            ["id"] = 5560,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Shellback Warhorse",
                        },
                        [5561] = 
                        {
                            ["description"] = "\"These Glowgill Guar mounts come from a coastal tribe over near Archon. Handsome, are they not? I've been told they can breathe underwater through those gills, though personally, I have never tested this.\" —Ukaspa, Stablemaster of Lilmoth",
                            ["icon"] = "/esoui/art/icons/mounticon_guar_glowgill.dds",
                            ["furnitureId"] = 5432,
                            ["id"] = 5561,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Glowgill Guar",
                        },
                        [5562] = 
                        {
                            ["description"] = "There is some debate among naturalists as to whether the Ice Nixad is a separate breed that is mainly seen in the winter because it hibernates during the warm months, or whether it's just a winter phase of ordinary Nixads that sometimes stays year-round.",
                            ["icon"] = "/esoui/art/icons/pet_235_icenixad.dds",
                            ["furnitureId"] = 5433,
                            ["id"] = 5562,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Ice Nixad",
                        },
                        [5563] = 
                        {
                            ["description"] = "Though Argonians do relish the elastic flesh of the Black Marsh Swamp Jellies, the whimsical names they give them refer more to their appearance than to their flavor.",
                            ["icon"] = "/esoui/art/icons/pet_233_yellowjelly.dds",
                            ["furnitureId"] = 5434,
                            ["id"] = 5563,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Cantaloupe Swamp Jelly",
                        },
                        [5564] = 
                        {
                            ["description"] = "Though the Argonians claim that they name each breed of Black Marsh Swamp Jelly for its hue rather than its taste, there's no denying that the Mint Jelly does have a gratifyingly refreshing flavor.",
                            ["icon"] = "/esoui/art/icons/pet_226_tealswampjelly.dds",
                            ["furnitureId"] = 5435,
                            ["id"] = 5564,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Mint Swamp Jelly",
                        },
                        [5565] = 
                        {
                            ["description"] = "The Plum Swamp Jelly is the rarest of the so-called \"Flavor\" Jellies, and seeing one is considered by many Argonians to be a sign of good fortune. It's not at all unusual for an Argonian to wear a Plum Jelly's feeler as a \"Good Luck Tentacle.\"",
                            ["icon"] = "/esoui/art/icons/pet_227_pinkswampjelly.dds",
                            ["furnitureId"] = 5436,
                            ["id"] = 5565,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Plum Swamp Jelly",
                        },
                        [11924] = 
                        {
                            ["description"] = "War hero and governor of Gideon, Keshu seeks to better the Saxhleel people while searching for peace and good companionship for a time. After adding Keshu to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["icon"] = "/esoui/art/icons/houseguest_keshutheblackfin.dds",
                            ["furnitureId"] = 9600,
                            ["id"] = 11924,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Keshu the Black Fin",
                        },
                        [10708] = 
                        {
                            ["description"] = "Smuggler crews in Hew's Bane first trained these palfreys to bear two riders. Originally, the training was just a cover story to hide their illicit work. But they quickly found having a mount that could hold two extremely useful for heists.",
                            ["icon"] = "/esoui/art/icons/mount_hewsbanepillionpalfrey.dds",
                            ["furnitureId"] = 8600,
                            ["id"] = 10708,
                            ["category"] = "Multi-Rider",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["name"] = "Hew's Bane Pillion Palfrey",
                        },
                        [1472] = 
                        {
                            ["description"] = "These short-haired, large-eared cats are a common sight in Mages Guildhalls, where it's said their keen senses enable them to detect all manner of intruders, even those that are magically concealed or from realms of Oblivion.",
                            ["icon"] = "/esoui/art/icons/pet_168.dds",
                            ["furnitureId"] = 4760,
                            ["id"] = 1472,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Mages Guild Sentry Cat",
                        },
                        [1473] = 
                        {
                            ["description"] = "\"Since our Incarnatoriums can be modified to produce Fabricants modeled on almost any creature of Tamriel Above, why are Scorpion Fabricants of differing sizes so popular? They're our most-requested fabs!\" says Clockwork Apostle Dringest.",
                            ["icon"] = "/esoui/art/icons/pet_164.dds",
                            ["furnitureId"] = 4483,
                            ["id"] = 1473,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Scorpion Fabricant",
                        },
                        [1474] = 
                        {
                            ["description"] = "Before Saints Llothis and Olms had to be confined in the Asylum Sanctorium, they used to ride through the Brass Fortress on holy days on these bizarre Fabricant mounts. But the parades are long gone, and the synthetic steeds have been repurposed.",
                            ["icon"] = "/esoui/art/icons/mounticon_lustrousnixoxfabricant.dds",
                            ["furnitureId"] = 4754,
                            ["id"] = 1474,
                            ["category"] = "Arthropods",
                            ["hint"] = "",
                            ["name"] = "Lustrous Nix-Ox Fabricant Steed",
                        },
                        [11882] = 
                        {
                            ["description"] = "This bantam guar's coloring provides camouflage. This is both a blessing and a curse, as it has a habit of wandering off if left unattended. With a trusting attitude, few natural defenses, and no innate survival instincts … don't leave it unattended.",
                            ["icon"] = "/esoui/art/icons/pet_twilightbantamguar.dds",
                            ["furnitureId"] = 9565,
                            ["id"] = 11882,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Twilight Bantam Guar",
                        },
                        [10717] = 
                        {
                            ["description"] = "\"The mix of hues in this Auroran wolf reminds me of the Colored Rooms. The beauty pains me, piercing my heart like a dagger. And if you stare too hard, you get lost in the eternity of its radiance. So, don't stare too hard.\"—Yaduur, Scholar",
                            ["icon"] = "/esoui/art/icons/mount_auroranpolychromaticwolf.dds",
                            ["furnitureId"] = 8602,
                            ["id"] = 10717,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Auroran Polychrome Wolf",
                        },
                        [10847] = 
                        {
                            ["description"] = "Stablers who see this impressive steed enter yards say they're blessed with good luck. Not only does caring for these Glenumbran rams bring profit, but their presence is said to herald a calm and peaceful night ahead.",
                            ["icon"] = "/esoui/art/icons/mount_cathbedraudram.dds",
                            ["furnitureId"] = 8613,
                            ["id"] = 10847,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "King's Guard Ram",
                        },
                        [10848] = 
                        {
                            ["description"] = "Not long after the Battle of Sungard, these sabre cats started prowling the area. Scholars at the time believed some element of the battle disturbed their normal habitat. Seeing an opportunity, animal handlers found cubs and started raising them as pets.",
                            ["icon"] = "/esoui/art/icons/pet_sungardsabrecat.dds",
                            ["furnitureId"] = 8614,
                            ["id"] = 10848,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Sungard Sabre Cat",
                        },
                        [10849] = 
                        {
                            ["description"] = "Commonly seen trotting alongside carts and coaches in Stormhaven, these perceptive dogs serve as deterrents to bandits and other road hazards. Within recent years, they've become popular in other parts of Tamriel, including Blackwood and the Rift.",
                            ["icon"] = "/esoui/art/icons/pet_meneviacoachdog.dds",
                            ["furnitureId"] = 8615,
                            ["id"] = 10849,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Menevian Coachdog",
                        },
                        [11877] = 
                        {
                            ["description"] = "Tzozabrar will intake items you don't need, expelling useful materials no doubt scavenged from a Dwarven construct. Tonal interference makes it unusable in Cyrodiil or Battlegrounds.\n\nAfter it's summoned, you and your groupmates can use its services.",
                            ["icon"] = "/esoui/art/icons/assistant_tzozabrar_dwarvendeconstructor.dds",
                            ["furnitureId"] = 9560,
                            ["id"] = 11877,
                            ["category"] = "Assistants",
                            ["hint"] = "",
                            ["name"] = "Tzozabrar, Dwarven Deconstructor",
                        },
                        [10853] = 
                        {
                            ["description"] = "Though the artist who sculpted this statue remains unknown, those who have faced the Ascendant Lord declare it captures this leader's might and presence perfectly. Claimed from the treasure trove of the Ascendant Order.",
                            ["icon"] = "/esoui/art/icons/housing_str_exc_statueascendantlord001.dds",
                            ["furnitureId"] = 8622,
                            ["id"] = 10853,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statue, Ascendant Lord",
                        },
                        [9674] = 
                        {
                            ["description"] = "\"I thought my salvation was at hand. That someone came for me here in this abyss. I was wrong, it was unnatural—a saddle with no horse beneath it. A form but no soul. Death itself would've been more kind.\"—Torn page in the cell of Vignac Ence",
                            ["icon"] = "/esoui/art/icons/mount_soulrazersteed.dds",
                            ["furnitureId"] = 7920,
                            ["id"] = 9674,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Soulrazer Steed",
                        },
                        [9675] = 
                        {
                            ["description"] = "The soulrazer wolves protected the crypt of House Penot near Breakwater cave. Now that the crypt is in ruins, they wander the shoreline during stormy nights, letting the wind howl mournfully as it passes beneath their cuirasses.",
                            ["icon"] = "/esoui/art/icons/mount_soulrazerwolf.dds",
                            ["furnitureId"] = 7921,
                            ["id"] = 9675,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Soulrazer Wolf",
                        },
                        [1484] = 
                        {
                            ["description"] = "Created after years of extensive breeding, the White-Gold Imperial Courser is said to be the most beautiful horse in all of Tamriel. With its almost ethereal beauty, these horses are owned by only the wealthiest riders.",
                            ["icon"] = "/esoui/art/icons/mounticon_whitegoldimperialcourser.dds",
                            ["furnitureId"] = 4756,
                            ["id"] = 1484,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "White-Gold Imperial Courser",
                        },
                        [1485] = 
                        {
                            ["description"] = "These rare Brassilisks are powered by blue soul gems brought back from the Psijic hideaway of Artaeum at the end of the First Era by Sotha Sil himself.",
                            ["icon"] = "/esoui/art/icons/pet_165_ps4.dds",
                            ["furnitureId"] = 4764,
                            ["id"] = 1485,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Psijic Brassilisk",
                        },
                        [1486] = 
                        {
                            ["description"] = "These mysterious green-glowing Brassilisks have been showing up in the environment outside the Brass Fortress. Some Clockwork Apostles suspect there's a rogue Incarnatorium assembling them somewhere out in the Radius.",
                            ["icon"] = "/esoui/art/icons/pet_165_xb1.dds",
                            ["furnitureId"] = 4762,
                            ["id"] = 1486,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Foxbat Brassilisk",
                        },
                        [1487] = 
                        {
                            ["description"] = "With soul gems in short supply, the Clockwork Apostles invented this experimental Brassilisk powered by steam stored under high pressure.",
                            ["icon"] = "/esoui/art/icons/pet_165_steam.dds",
                            ["furnitureId"] = 4766,
                            ["id"] = 1487,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Steam-Driven Brassilisk",
                        },
                        [9680] = 
                        {
                            ["description"] = "\"Horses may be speedy enough for open roads, but they can't board a ship in the dead of night or delight the crew when there's nary a breeze to fill the sails. And no horse ever ripped out the throat of the night watch.\"—Kylian, Bosun of the Red Sky",
                            ["icon"] = "/esoui/art/icons/mount_abeceanstriderwolf.dds",
                            ["furnitureId"] = 7925,
                            ["id"] = 9680,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Dreadsail Howler",
                        },
                        [9681] = 
                        {
                            ["description"] = "The distinctive blue colors of the Iliac Bay Crab make it both a sought-after adventuring friend for those who adore crabs as companions and a target for fisherfolk seeking the shellfish's tender meat. Are you the former, the latter, or maybe both?",
                            ["icon"] = "/esoui/art/icons/pet_tealsheenmudcrab.dds",
                            ["furnitureId"] = 7926,
                            ["id"] = 9681,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Iliac Bay Crab",
                        },
