                        [11563] = 
                        {
                            ["description"] = "This Orc mercenary usually keeps busy, but now he wants some actual quiet time. Not to reflect, though—his well-used gear needs some attention. After adding Skordo to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/houseguest_skordo.dds",
                            ["furnitureId"] = 9354,
                            ["id"] = 11563,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Skordo the Knife",
                        },
                        [11562] = 
                        {
                            ["description"] = "With no mysteries for this Khajiit of action to solve, he's at loose ends. Perhaps he can discover some curious doings around your abode? After adding Mizzik to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/houseguest_mizzikthunderboots.dds",
                            ["furnitureId"] = 9353,
                            ["id"] = 11562,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Mizzik Thunderboots",
                        },
                        [11561] = 
                        {
                            ["description"] = "Oh, the ignominy of being an agent of justice trapped inside a small floating doll! Now Heiruna intends to plot vengeance—in your retreat. After adding Heiruna to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["icon"] = "/esoui/art/icons/houseguest_heiruna.dds",
                            ["furnitureId"] = 9352,
                            ["id"] = 11561,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Heiruna",
                        },
                        [11537] = 
                        {
                            ["description"] = "\"It appears Sabhir has earned your admiration. This is not the first time his stunning spots have stolen hearts. Shh, don't let him see you looking. He has enough of an ego as it is.\"—Stablehand Ghazaleh",
                            ["icon"] = "/esoui/art/icons/pet_piebaldcamel.dds",
                            ["furnitureId"] = 9350,
                            ["id"] = 11537,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Piebald Camel",
                        },
                        [11536] = 
                        {
                            ["description"] = "\"This titan failed the Dark Lord once, and paid the price for it. After he ripped off its wings, Molag Bal bound it to his dark will, making it a useful—if grounded—mount for his more faithful servants.\"—Worm Cultist Valoel",
                            ["icon"] = "/esoui/art/icons/mount_fallentitan.dds",
                            ["furnitureId"] = 9349,
                            ["id"] = 11536,
                            ["category"] = "Heavyweights",
                            ["hint"] = "|cFFFFFFDaedric Anchor effects appear only when paired with the Molag Bal Illusion polymorph.|r",
                            ["name"] = "Shackled Titan",
                        },
                        [11535] = 
                        {
                            ["description"] = "\"The Imperials do love their regalia, don't they? Even I have to admit it's a rather dashing look, for a horse. Anyone who comes in astride that steed is certain to make an entrance.\"—Abelle Gernand of Kvatch",
                            ["icon"] = "/esoui/art/icons/mount_jubileesteed.dds",
                            ["furnitureId"] = 9348,
                            ["id"] = 11535,
                            ["category"] = "Equines",
                            ["hint"] = "Acquired by completing the \"Jubilee Confetti Conveyor\" achievement.",
                            ["name"] = "Jubilee Steed",
                        },
                        [11534] = 
                        {
                            ["description"] = "\"These mudcrabs developed their shine as both a defensive tactic and mating ritual. By angling their bodies, they can reflect blinding rays at would-be predators or signal their availability to potential mates.\"—Mirrormoor: More Than an Illusion",
                            ["icon"] = "/esoui/art/icons/pet_mirrormoormudcrap.dds",
                            ["furnitureId"] = 9347,
                            ["id"] = 11534,
                            ["category"] = "Exotic",
                            ["hint"] = "Awarded by completing the \"Prisoner of Fate\" quest.",
                            ["name"] = "Mirrormoor Mudcrab",
                        },
                        [11533] = 
                        {
                            ["description"] = "Said to have been tamed by Lyris Titanborn herself, this fierce wolf easily bears its rider across nearly any terrain. While the beast is a frenzied fighter on the battlefield, one word from its rider will have it waiting docilely for the next command.",
                            ["icon"] = "/esoui/art/icons/mount_companionrevelrywolf.dds",
                            ["furnitureId"] = 9346,
                            ["id"] = 11533,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Titanborn's Revelry Wolf",
                        },
                        [11532] = 
                        {
                            ["description"] = "A steed worthy of an emperor, this courser represents the finest traits of Imperial equestrian skill. Steady and strong with an incredibly smooth gait, this mount could help its rider fell countless kingdoms.",
                            ["icon"] = "/esoui/art/icons/mount_companionrevelryhorse.dds",
                            ["furnitureId"] = 9345,
                            ["id"] = 11532,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Varen's Revelry Courser",
                        },
                        [11531] = 
                        {
                            ["description"] = "\"Ah, this is a beast worthy of a hero! Don't worry, faithful Minana here has seen her share of battles and more than earned the armor she now wears. She will be a staunch companion to you, no matter where HoonDing bids you.\"—Dragonguard Zarina",
                            ["icon"] = "/esoui/art/icons/mount_companionrevelrybear.dds",
                            ["furnitureId"] = 9344,
                            ["id"] = 11531,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Sai-Sahan's Revelry Ursine",
                        },
                        [11530] = 
                        {
                            ["description"] = "These playful golden canines happily accompany their people on journeys near and far, making friends with anyone they meet along the way. The downside to this endearing show of trust is, of course, that they're not the best guard dogs.",
                            ["icon"] = "/esoui/art/icons/pet_chorralretriever.dds",
                            ["furnitureId"] = 9343,
                            ["id"] = 11530,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Chorrol Retriever",
                        },
                        [11523] = 
                        {
                            ["description"] = "Swift as a stream and silent as a shadow, this creature appears in many folktales across Tamriel. In some, the lynx stalks its quarry across the night sky. In others it's an agile companion, perfect for worthy hunters prowling the darkest nights.",
                            ["icon"] = "/esoui/art/icons/mount_celestiallynx.dds",
                            ["furnitureId"] = 9341,
                            ["id"] = 11523,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Celestial Lynx",
                        },
                        [11522] = 
                        {
                            ["description"] = "Though fearsome in appearance, these ursauks make staunch companions when properly socialized. Their thick fur and hardy constitutions allow them to thrive even in the harshest environments, especially those in the northern reaches of Tamriel.",
                            ["icon"] = "/esoui/art/icons/mount_atmoransnowursauk.dds",
                            ["furnitureId"] = 9333,
                            ["id"] = 11522,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Atmoran Snow Ursauk",
                        },
                        [5619] = 
                        {
                            ["description"] = "Is this just a dark fowl, mere poultry of sinister visage—or does it hail from realms beyond Nirn, mayhap from the Deadlands of Mehrunes Dagon or the Ashpit of Malacath? Dare you ask yourself the dread question: Which came first?",
                            ["icon"] = "/esoui/art/icons/pet_203_blackchicken.dds",
                            ["furnitureId"] = 5475,
                            ["id"] = 5619,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Daemon Chicken",
                        },
                        [5620] = 
                        {
                            ["description"] = "A hardy domestic chicken found all along Skyrim's White River, said to have been originally bred in the old town of Riverwood. Owners grow extremely attached to them, and become outraged if they're harmed.",
                            ["icon"] = "/esoui/art/icons/pet_215_roosterwhite.dds",
                            ["furnitureId"] = 5476,
                            ["id"] = 5620,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Riverwood White Hen",
                        },
                        [11520] = 
                        {
                            ["description"] = "This beast is the result of a collaboration between Shad Astula students and Mages Guild apprentices. Rumor is it may be slightly psychic, responding to its rider's commands almost before they're uttered aloud. The color is a nice bonus, too.",
                            ["icon"] = "/esoui/art/icons/mount_alterationornaug.dds",
                            ["furnitureId"] = 9331,
                            ["id"] = 11520,
                            ["category"] = "Serpentes",
                            ["hint"] = "",
                            ["name"] = "Altered Ornaug",
                        },
                        [11519] = 
                        {
                            ["description"] = "Trophy taken from Ansuul the Tormentor in honor of an Undaunted victory in Sanity's Edge.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyvaerminagloamknight001.dds",
                            ["furnitureId"] = 9329,
                            ["id"] = 11519,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Sanity's Edge.",
                            ["name"] = "Trophy: Ansuul the Tormentor",
                        },
                        [11518] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Sanity's Edge.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialvaerminagloamknight001.dds",
                            ["furnitureId"] = 9328,
                            ["id"] = 11518,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Sanity's Edge.",
                            ["name"] = "Bust: Ansuul the Tormentor",
                        },
                        [11515] = 
                        {
                            ["description"] = "\"This cub is special, yes. Beautiful and quite friendly. Not the softest companion, but others have said the same about me.\"—Scholar Zansora",
                            ["icon"] = "/esoui/art/icons/pet_prismaticsenchecub.dds",
                            ["furnitureId"] = 9270,
                            ["id"] = 11515,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Prismatic Senche Cub",
                        },
                        [11514] = 
                        {
                            ["description"] = "This impressive vision is the work of a very dedicated illusion imp. The shimmering form sparks the adoration of all who see it, making for easy handouts and safe havens for this tiny so-called Dragon.",
                            ["icon"] = "/esoui/art/icons/pet_conjureddragonimp.dds",
                            ["furnitureId"] = 9269,
                            ["id"] = 11514,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Conjured Dragon Imp",
                        },
                        [11513] = 
                        {
                            ["description"] = "Though alarming at first glance, this fawn is perfectly content with its strangely blazing body. Those who can tame this extreme example of mystical adaptation will find its back an excellent medium for cooking over an open flame.",
                            ["icon"] = "/esoui/art/icons/pet_tinderflarevalefawn.dds",
                            ["furnitureId"] = 9268,
                            ["id"] = 11513,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Destruction Dale Fawn",
                        },
                        [11508] = 
                        {
                            ["description"] = "\"HoonDing knows they don't look fast. But that's actually a good thing. No one will expect you to cover as much ground as you do. And there is truly nothing more terrifying than a camel charging you at full speed.\"—Bilami the Caravaneer",
                            ["icon"] = "/esoui/art/icons/mount_swordsingerstuftedcamel.dds",
                            ["furnitureId"] = 9266,
                            ["id"] = 11508,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Sword-Singer's Tufted Camel",
                        },
                        [11507] = 
                        {
                            ["description"] = "\"Emerald Oak Nixads are known for their mischief. Their coloration allows them to hide in forests, waiting for unsuspecting travelers to pass by. Upon leaving, travelers will find their rations much lighter, especially sweets.\"—Gold Coast Field Guide",
                            ["icon"] = "/esoui/art/icons/pet_emeraldoaknixad.dds",
                            ["furnitureId"] = 9265,
                            ["id"] = 11507,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Emerald Oak Nixad",
                        },
                        [11506] = 
                        {
                            ["description"] = "\"Watch your moon sugar around these ones. They have keen eyes and clever hands. This one has lost her lunch to Zuzdu more times than she can count. Still, they can be quite sweet when they want to be. Probably from all the stolen sugar.\"—Tahara",
                            ["icon"] = "/esoui/art/icons/pet_moonsugarmonkey.dds",
                            ["furnitureId"] = 9264,
                            ["id"] = 11506,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Sugarsnow Monkey",
                        },
                        [11505] = 
                        {
                            ["description"] = "The eye-catching hue of this haj mota may be beautiful, but it belies a fiery demeanor. Haj motas are known for their harsh temperaments, but this one is not to be trifled with. Thankfully, it's too small to do more than snap at ankles.",
                            ["icon"] = "/esoui/art/icons/pet_lus_begottenhajmota.dds",
                            ["furnitureId"] = 9263,
                            ["id"] = 11505,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ruby Haj Mota",
                        },
                        [11472] = 
                        {
                            ["description"] = "All statues of the Inevitable Knower are, after a fashion, access points from Apocrypha to Nirn. Given that, go carefully as you invite Hermaeus Mora into your home.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_hermaeusmorastatuette001.dds",
                            ["furnitureId"] = 9232,
                            ["id"] = 11472,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Mora, Lord of Secrets",
                        },
                        [11457] = 
                        {
                            ["description"] = "\"I've only seen a wild brindle bear once, and I don't wish to repeat the experience. The creature found me in the woods, bagging up a deer. It growled. I froze. But then it walked right by me. It must have already eaten.\"—Scarius Barbatus of Kvatch",
                            ["icon"] = "/esoui/art/icons/mount_brindlebear.dds",
                            ["furnitureId"] = 9220,
                            ["id"] = 11457,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Brindle Bear",
                        },
                        [11454] = 
                        {
                            ["description"] = "Gilded from head to hoof, this indrik practically glows with the light of inspiration. It may have been a fabled companion of Vanus Galerion. Whether or not the legends are true, its rider will see a world full of shimmering ideas and possibilities.",
                            ["icon"] = "/esoui/art/icons/mount_lightgiverindrik.dds",
                            ["furnitureId"] = 9190,
                            ["id"] = 11454,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Galerion's Indrik",
                        },
                        [11441] = 
                        {
                            ["description"] = "Many have met their ends at the jaws of a fully grown Solstheim wolf. This trained version, however, still has snowflakes in its fur and frolics whenever it comes across a fresh snow drift. It even gives freezing cold kisses when called.",
                            ["icon"] = "/esoui/art/icons/pet_solstheimtundrawolf.dds",
                            ["furnitureId"] = 9153,
                            ["id"] = 11441,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Solstheim Shiver Wolf",
                        },
                        [11438] = 
                        {
                            ["description"] = "The shallows of Buraniim Isle are rife with a unique subspecies of ornaug. Vibrant and playful, these ornaugs have been known to splash in the surf to attract the curiosity of would-be prey. When the unsuspecting meal draws too close, they strike.",
                            ["icon"] = "/esoui/art/icons/mount_buraniim-ornaug.dds",
                            ["furnitureId"] = 9149,
                            ["id"] = 11438,
                            ["category"] = "Serpentes",
                            ["hint"] = "",
                            ["name"] = "Buraniim Isle Ornaug",
                        },
                        [11437] = 
                        {
                            ["description"] = "Divergences in fate's threads draw Scruut's attention. Yet, this mighty Watchling seeks your company until the Great Eye summons her. Coincidence? After adding Scruut to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["icon"] = "/esoui/art/icons/houseguest_scruut.dds",
                            ["furnitureId"] = 9133,
                            ["id"] = 11437,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Scruut",
                        },
                        [11436] = 
                        {
                            ["description"] = "The inimitable Captain Kaleen seeks some shore leave before setting sail for her next job. If you've a bunk for her, she'll gladly take it. After adding Captain Kaleen to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["icon"] = "/esoui/art/icons/houseguest_captainkaleen.dds",
                            ["furnitureId"] = 9131,
                            ["id"] = 11436,
                            ["category"] = "Houseguests",
                            ["hint"] = "Acquired by completing the achievement \"Memories of the Spearhead.\"",
                            ["name"] = "Captain Kaleen",
                        },
                        [11435] = 
                        {
                            ["description"] = "Need some mirth and mystery in your home? Invite Alchemy, a renowned performer from the House of Reveries, to stay with you. After adding Alchemy to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["icon"] = "/esoui/art/icons/houseguest_alchemy.dds",
                            ["furnitureId"] = 9132,
                            ["id"] = 11435,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Alchemy",
                        },
                        [5639] = 
                        {
                            ["description"] = "The Psijic Order has bred these senches for centuries, selecting only the brightest among the litters to sire the next generation. Psijics who choose them as companions often form telepathic bonds and claim they are wonderful conversationalists.",
                            ["icon"] = "/esoui/art/icons/mounticon_senche_psijicv2.dds",
                            ["furnitureId"] = 5792,
                            ["id"] = 5639,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Sagacious Psijic Senche",
                        },
                        [5640] = 
                        {
                            ["description"] = "Though the Psijics are not a combat order, the monks do concede a need for protection when venturing beyond Artaeum, and when their fighting escorts need to be mounted, they conjure up these impressive warhorses for them.",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_psijicv2.dds",
                            ["furnitureId"] = 5794,
                            ["id"] = 5640,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Psijic Escort Charger",
                        },
                        [11434] = 
                        {
                            ["description"] = "\"The ravens of Rivenspire are some of the smartest in all of Tamriel. Something about surviving in such an inhospitable land, I think. This fine fellow has been my companion on many a long night in the study.\"—Lady Felyse Talemelier",
                            ["icon"] = "/esoui/art/icons/pet_evermoreraven.dds",
                            ["furnitureId"] = 9130,
                            ["id"] = 11434,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Eyebright Raven",
                        },
                        [5642] = 
                        {
                            ["description"] = "As a sign of the blessing of Mara, Goddess of Fertility, in spring certain breeds of Tamriel's hens lay eggs with shells in a variety of colors.",
                            ["icon"] = "/esoui/art/icons/pet_216_coloredchicken.dds",
                            ["furnitureId"] = 5516,
                            ["id"] = 5642,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Mara's Spring Chicken",
                        },
                        [11433] = 
                        {
                            ["description"] = "The light of dawn caresses the spires of Bal Foyen as a trader and their travel-burdened guar arrive at this Dark Elf sanctum by the sea.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingpaintingbalfoyen001.dds",
                            ["furnitureId"] = 9129,
                            ["id"] = 11433,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Painting: Arrival at Bal Foyen",
                        },
                        [11432] = 
                        {
                            ["description"] = "A miniature statue of a sentinel found outside many Dwarven ruins in Morrowind.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettedwemer001.dds",
                            ["furnitureId"] = 9128,
                            ["id"] = 11432,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Dwemer Guardian",
                        },
                        [11431] = 
                        {
                            ["description"] = "A miniature statue of the Daedric Prince Vaermina, the Lady of Nightmares.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettevaermina001.dds",
                            ["furnitureId"] = 9127,
                            ["id"] = 11431,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Vaermina, Dreamweaver",
                        },
                        [11425] = 
                        {
                            ["description"] = "Though not the most fearsome mounts, these recent additions to the Lamp Knight stable are treasured for their loyalty, surefootedness, and tracking skills. Some mages claim they can smell magicka, making them invaluable to the Order of the Lamp.",
                            ["icon"] = "/esoui/art/icons/mount_orderofthelampvvardvark.dds",
                            ["furnitureId"] = 9116,
                            ["id"] = 11425,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Order of the Lamp Vvardvark",
                        },
                        [9743] = 
                        {
                            ["description"] = "This factotum exists to serve as your personal banker—except in Cyrodiil or Battlegrounds, where it shuts down and vanishes to hyperogonal points unknown.\n\nAfter it's summoned, you and your groupmates can use its services.",
                            ["icon"] = "/esoui/art/icons/assistant_factotumbanker.dds",
                            ["furnitureId"] = 7947,
                            ["id"] = 9743,
                            ["category"] = "Assistants",
                            ["hint"] = "",
                            ["name"] = "Factotum Property Steward",
                        },
                        [9744] = 
                        {
                            ["description"] = "Need to sell a few things? Do so with this shiny factotum—except in Cyrodiil or Battlegrounds, which initiate its retreat protocols.\n\nAfter it's summoned, you and your groupmates can use its services.",
                            ["icon"] = "/esoui/art/icons/assistant_factotummerchant.dds",
                            ["furnitureId"] = 7948,
                            ["id"] = 9744,
                            ["category"] = "Assistants",
                            ["hint"] = "",
                            ["name"] = "Factotum Commerce Delegate",
                        },
                        [9745] = 
                        {
                            ["description"] = "You and your groupmates can prepare for combat by summoning Ghrasharog to change and save builds outside of your home. He avoids Cyrodiil or Battlegrounds, which he swears made him complacent after winning victory upon victory.",
                            ["icon"] = "/esoui/art/icons/assistant_ghrashorogmasteratarms.dds",
                            ["furnitureId"] = 7949,
                            ["id"] = 9745,
                            ["category"] = "Assistants",
                            ["hint"] = "",
                            ["name"] = "Ghrasharog, Armory Assistant",
                        },
                        [11424] = 
                        {
                            ["description"] = "\"Magicka depleted. Enemies on all sides. The cornered mages despaired. Until they heard a growl erupt into a roar as a Lamp Knight and his leonine steed smashed through the enemy ranks.\"—Tale of the Palatinus, translated",
                            ["icon"] = "/esoui/art/icons/mount_orderofthelamplion.dds",
                            ["furnitureId"] = 9115,
                            ["id"] = 11424,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Order of the Lamp Lion",
                        },
                        [11403] = 
                        {
                            ["description"] = "\"The Wild Elves did something right when they tamed these adorable beasties! Look at those eyes, and that tail! Plus with that handsome armor, they'll be well protected on the road.\" —Apprentice Odrethin",
                            ["icon"] = "/esoui/art/icons/pet_wenayawend-wolf-pup.dds",
                            ["furnitureId"] = 9034,
                            ["id"] = 11403,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Welkyndstone Ruins Pup",
                        },
                        [5652] = 
                        {
                            ["description"] = "Hardy and good-natured, the faithful Skyrim Paint Pony wants to be near its master regardless of the weather, leaning into the wind even in a tundra blizzard.",
                            ["icon"] = "/esoui/art/icons/pet_213_paintedpony.dds",
                            ["furnitureId"] = 5852,
                            ["id"] = 5652,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Scruffy Skyrim Paint Pony",
                        },
                        [11402] = 
                        {
                            ["description"] = "\"Cute little critters, aren't they? The white pelt helps them blend into the mountains of Skyrim. That's good, because they're just about the tastiest thing the winter has to offer. Except for that one. He's off limits.\"—Narrald Snow-Bourne",
                            ["icon"] = "/esoui/art/icons/pet_deepsnowprairiedog.dds",
                            ["furnitureId"] = 9033,
                            ["id"] = 11402,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Deepsnow Prairie Dog",
                        },
                        [11391] = 
                        {
                            ["description"] = "Azandar al-Cybiades is a consummate researcher and peerless arcanist. Just ask him! After adding Azandar to your home, you can set him on a path. You and your guests can also talk to him. Trust us, he's got plenty to say.",
                            ["icon"] = "/esoui/art/icons/houseguest_azandar_2.dds",
                            ["furnitureId"] = 9174,
                            ["id"] = 11391,
                            ["category"] = "Houseguests",
                            ["hint"] = "Obtained by completing quest \"Tempting Fates.\"",
                            ["name"] = "Azandar",
                        },
                        [11390] = 
                        {
                            ["description"] = "Solitary mercenary Sharp-as-Night isn't used to company, but if you invite him into your home, this warden will leave his icy demeanor at the door. Mostly. Talk to him to hear his unfiltered thoughts, or set him on a path to let him wander your estate.",
                            ["icon"] = "/esoui/art/icons/houseguest_sharp.dds",
                            ["furnitureId"] = 9175,
                            ["id"] = 11390,
                            ["category"] = "Houseguests",
                            ["hint"] = "Obtained by completing quest \"Light the Way to Freedom\".",
                            ["name"] = "Sharp-as-Night",
                        },
                        [5656] = 
                        {
                            ["description"] = "Though obviously related to the netches of northeast Tamriel, the swamp jellies of southern Black Marsh also have a disquieting resemblance to aquatic jellyfish. Natural philosophers have no adequate explanation for this.",
                            ["icon"] = "/esoui/art/icons/pet_206_swampjelly.dds",
                            ["furnitureId"] = 5541,
                            ["id"] = 5656,
                            ["category"] = "Flying Pets",
                            ["hint"] = "Acquired by finding its seven Runebox Fragments in Cyrodilic Collections Daily Contract Recompense containers and combining them.",
                            ["name"] = "Swamp Jelly",
                        },
                        [5657] = 
                        {
                            ["description"] = "This little critter's bright, beautiful colors are actually a warning to predators that it's a potent mouthful of poison. Fortunately for Tamriel's humanoid mortals, its venom affects them as no more than a mild hallucinogen.",
                            ["icon"] = "/esoui/art/icons/pet_211_kaleidascope.dds",
                            ["furnitureId"] = 5547,
                            ["id"] = 5657,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Kaleidotropic Dragon Frog",
                        },
                        [5658] = 
                        {
                            ["description"] = "\"The Butterscotch Dragon Frog presumably got its name from the Argonian practice of naming creatures after flavors, whether those things taste like that or not. This one has no intention of finding out whether it does.\" —M'aiq the Liar",
                            ["icon"] = "/esoui/art/icons/pet_207_butterscotch.dds",
                            ["furnitureId"] = 5548,
                            ["id"] = 5658,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Butterscotch Dragon Frog",
                        },
                        [5659] = 
                        {
                            ["description"] = "All the large Salamanders of southern Tamriel have elemental powers, but some specialize in particular forces; the Flame Skin breed, for example, almost ripples with fire.",
                            ["icon"] = "/esoui/art/icons/pet_208_orangesalamander.dds",
                            ["furnitureId"] = 5552,
                            ["id"] = 5659,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Flame Skin Salamander",
                        },
                        [5660] = 
                        {
                            ["description"] = "The large, lumbering Salamanders of southern Tamriel are known for defending themselves with various elemental bursts—all but one, the Toxin Skin variety, which relies on venom instead. Not even the Sapiarchs of the Crystal Tower can account for it.",
                            ["icon"] = "/esoui/art/icons/pet_210_greensalamander.dds",
                            ["furnitureId"] = 5553,
                            ["id"] = 5660,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Toxin Skin Salamander",
                        },
                        [5661] = 
                        {
                            ["description"] = "The lumbering great Salamanders of southern Tamriel all defend themselves with bursts of elemental power, but the Shock Skin variety specializes in electrical discharges. Fortunately, they can be trained not to zap their masters!",
                            ["icon"] = "/esoui/art/icons/pet_209_bluesalamander.dds",
                            ["furnitureId"] = 5554,
                            ["id"] = 5661,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Shock Skin Salamander",
                        },
                        [5662] = 
                        {
                            ["description"] = "\"Cats with odd-colored eyes see into the depths of those around them. Those with white fur? They see into time itself.\" —Zamarak",
                            ["icon"] = "/esoui/art/icons/pet_prongearoddeyed-cat.dds",
                            ["furnitureId"] = 5557,
                            ["id"] = 5662,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Prong-Eared Odd-Eyed Cat",
                        },
                        [11380] = 
                        {
                            ["description"] = "These ponderous moths flap slowly between pools of moonlight, attracted by the glow. During the day, they either rest on shady tree trunks or follow behind those who make them feel safe. Their delicate wings are famously soft to the touch.",
                            ["icon"] = "/esoui/art/icons/pet_hearthhomemoth.dds",
                            ["furnitureId"] = 9021,
                            ["id"] = 11380,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Hearthhome Moth",
                        },
                        [11379] = 
                        {
                            ["description"] = "\"How many times have I told you to keep your fingers away from the claws? Now look at you, knuckles bruised and nothing learned. The crab did nothing wrong. Maybe it's time this one found a more appropriate home.\"—Overheard on the Necrom docks",
                            ["icon"] = "/esoui/art/icons/pet_prodigiouscrimsonmudcrab.dds",
                            ["furnitureId"] = 9020,
                            ["id"] = 11379,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Prodigious Crimson Mudcrab",
                        },
                        [11326] = 
                        {
                            ["description"] = "Some find the color unnerving, but many riders enjoy the onyx shade and welcome the superstitious tales that follow this mount. Just know that countless legends and tales of woe begin when a Black Fredas beast crosses one's path.",
                            ["icon"] = "/esoui/art/icons/mount_blackfredassenchelizard.dds",
                            ["furnitureId"] = 8999,
                            ["id"] = 11326,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Black Fredas Senche-Lizard",
                        },
                        [11240] = 
                        {
                            ["description"] = "Aloof and strangely mournful, there's no question Pirzbi wields powerful magic. Some say their innate ability and keen intellect have become an obstacle for those who wish to partner with them. Perhaps you will find success where they did not.",
                            ["icon"] = "/esoui/art/icons/mount_sagaciouspsijicsencheraht.dds",
                            ["furnitureId"] = 8995,
                            ["id"] = 11240,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Sagacious Psijic Senche-Raht",
                        },
                        [11239] = 
                        {
                            ["description"] = "Docile and hardy, these sheep were first tamed near Whiterun. Their thick wool is woven into cloaks and blankets, protecting the wearer during harsh winters. Nord children sometimes bed down among the flock, enjoying the sheep's warmth.",
                            ["icon"] = "/esoui/art/icons/pet_silentmoonssheep.dds",
                            ["furnitureId"] = 8994,
                            ["id"] = 11239,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Silent Moons Sheep",
                        },
                        [11238] = 
                        {
                            ["description"] = "Some claim this breed of bird from Cyrodiil's heartland has a deeper connection to Shezarr than the name. This is likely due to their escape artist reputation, which finds them \"being misplaced\" quite regularly.",
                            ["icon"] = "/esoui/art/icons/pet_shezarrchicken.dds",
                            ["furnitureId"] = 8993,
                            ["id"] = 11238,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Shezarr's Chicken",
                        },
                        [11237] = 
                        {
                            ["description"] = "Aethereal light pours off this unearthly fawn. Some say it's a blessing from the Divines, while others think it's a Daedric trick. Still, it's a rare thing to be trusted by such an elusive creature, placing its companions in auspicious company.",
                            ["icon"] = "/esoui/art/icons/pet_star-orphan-fawn.dds",
                            ["furnitureId"] = 8992,
                            ["id"] = 11237,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Star-Orphan Fawn",
                        },
                        [11233] = 
                        {
                            ["description"] = "Much like the pocket mammoths first domesticated near Bonerock Cavern, these creatures are docile and affectionate, plus make excellent livestock. This sub-species is particularly prized among breeders for its distinctive fur color.",
                            ["icon"] = "/esoui/art/icons/pet_gingerpocketmammoth.dds",
                            ["furnitureId"] = 8989,
                            ["id"] = 11233,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ginger Pocket Mammoth",
                        },
                        [11232] = 
                        {
                            ["description"] = "Guar have long been at home in the Black Marsh, making them steady companions to the Argonians. It is not uncommon for Lavender Guar to bond deeply with their riders, standing watch while they sleep and affectionately nuzzling them.",
                            ["icon"] = "/esoui/art/icons/mount_lavenderguar2.dds",
                            ["furnitureId"] = 8968,
                            ["id"] = 11232,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Lavender Guar",
                        },
                        [11219] = 
                        {
                            ["description"] = "A painting presenting a peaceful blending of Breton and druidic architecture, set against the wild lushness of Galen's flora.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingpaintingu37firesonggalenzone001.dds",
                            ["furnitureId"] = 8965,
                            ["id"] = 11219,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Painting: Galen in Harmony",
                        },
                        [11217] = 
                        {
                            ["description"] = "A miniature statue of Kaalgrontiid, the emerald sovereign of wrath and terror.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettedemonspire001.dds",
                            ["furnitureId"] = 8963,
                            ["id"] = 11217,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Kaalgrontiid",
                        },
                        [11210] = 
                        {
                            ["description"] = "A fabricant from the hidden laboratories of Sotha Sil, the clockwork nix-hound is a small but lifelike imitation. It even \"hunts\" and consumes tiny scraps of metal in its vicinity. Watch out for your coinpurse!",
                            ["icon"] = "/esoui/art/icons/pet_clockworknixhound.dds",
                            ["furnitureId"] = 8951,
                            ["id"] = 11210,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Clockwork Nix-Hound",
                        },
                        [11209] = 
                        {
                            ["description"] = "\"Some of father's creations can be so frightening what with the way they hiss and stutter, but not this small scarab, no. After all, its bright glow does wonders to keep the monsters beneath my bed at bay.\"—Fabricator Anzalf's Daughter",
                            ["icon"] = "/esoui/art/icons/pet_ebonyscarab.dds",
                            ["furnitureId"] = 8950,
                            ["id"] = 11209,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ebony Dwarven Scarab",
                        },
                        [11204] = 
                        {
                            ["description"] = "\"Twisted twigs, a scent of death, a dance amid the briars. A dash of howls and drip of gore starts sinister fires. Stir round with haunted bone, then call me with your screams. If I approve, a mount you gain to torment your foes' dreams.\"—Lord Hollowjack",
                            ["icon"] = "/esoui/art/icons/mount_hollowjackindrik.dds",
                            ["furnitureId"] = 8937,
                            ["id"] = 11204,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Hollowjack Indrik",
                        },
                        [11203] = 
                        {
                            ["description"] = "Originally seen as a mistake by its creator, vvardvarks grew in popularity, compelling Telvanni magisters to expand its development. This dark-hued mount is perfectly suited to carry riders in funerary processions honoring revered ancient ancestors.",
                            ["icon"] = "/esoui/art/icons/mount_ashmournvvardvark.dds",
                            ["furnitureId"] = 8936,
                            ["id"] = 11203,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Ashmourning Vvardvark",
                        },
                        [11202] = 
                        {
                            ["description"] = "\"After weeks of searching, I finally caught a glimpse of that illustrious beast on the horizon. I thought it was a vision from Meridia, but then it approached on the icy tundra and I felt the warmth of its breath on my hand.\" —Journal of Mage Abzrolg",
                            ["icon"] = "/esoui/art/icons/mount_starorphanelk.dds",
                            ["furnitureId"] = 8934,
                            ["id"] = 11202,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Star-Orphan Elk",
                        },
                        [9775] = 
                        {
                            ["description"] = "Taken from the nest almost as soon as it breaks through its shell, this quasigriff is pampered and preened as befits a creature sacred to Auriel. Its golden feathers are used as fletching by archers in Balfiera.",
                            ["icon"] = "/esoui/art/icons/mount_aurielicquasigriff.dds",
                            ["furnitureId"] = 7951,
                            ["id"] = 9775,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Aurielic Quasigriff",
                        },
                        [11201] = 
                        {
                            ["description"] = "\"And thus did Alkosh bestow a companion of pure light upon his champion. From atop the beast, the champion rode a noble path. And wherever the lion's paws fell, light and justice soon followed thereafter.\" —Path of the Highmane, translated",
                            ["icon"] = "/esoui/art/icons/mount_alkoshs-blessing-lion.dds",
                            ["furnitureId"] = 8933,
                            ["id"] = 11201,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Blessed Highmane Lion",
                        },
                        [11200] = 
                        {
                            ["description"] = "Ready to learn more about Peryite, the Prince of Pestilence? Then Filbert's ready to visit and share his knowledge. After adding Filbert to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/houseguest_filbertcienne.dds",
                            ["furnitureId"] = 8932,
                            ["id"] = 11200,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Filbert Cienne",
                        },
                        [11180] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Bal Sunnar.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterannixox001.dds",
                            ["furnitureId"] = 8866,
                            ["id"] = 11180,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Bal Sunnar.",
                            ["name"] = "Bust: Roksa the Warped",
                        },
                        [11179] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Scrivener's Hall.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteraninfernium001.dds",
                            ["furnitureId"] = 8865,
                            ["id"] = 11179,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Scrivener's Hall.",
                            ["name"] = "Bust: Ozezan the Inferno",
                        },
                        [11121] = 
                        {
                            ["description"] = "Hermit crabs are nothing if not adaptable. Those from the Telvanni Peninsula use hollowed mushroom caps as their homes and serve as ornaments in Dark Elf gardens.",
                            ["icon"] = "/esoui/art/icons/pet_telvannihermitcrab.dds",
                            ["furnitureId"] = 8821,
                            ["id"] = 11121,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Peninsula Hermit Crab",
                        },
                        [11120] = 
                        {
                            ["description"] = "Dremnaken runts do not take kindly to acts of aggression. They include chin scratches and head pats in this category, more's the pity. In fact, it's best you avoid even the gentlest of eye contact.",
                            ["icon"] = "/esoui/art/icons/pet_discorddremnaken.dds",
                            ["furnitureId"] = 8820,
                            ["id"] = 11120,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Discord Dremnaken Runt",
                        },
                        [11072] = 
                        {
                            ["description"] = "\"Intense shudders wracked the spider of Dwarven make. 'It smells most foul. Let us repair its workings for Lord Vivec. Its perpetual existence shall provoke needed change among us.' And so it joined the bear.\"—Armiger Tharys's Journal",
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerdwarvenspider.dds",
                            ["furnitureId"] = 8704,
                            ["id"] = 11072,
                            ["category"] = "Constructs",
                            ["hint"] = "",
                            ["name"] = "Buoyant Armiger Dwarven Spider",
                        },
                        [11071] = 
                        {
                            ["description"] = "\"Curious, the horned beast sniffed at food before turning away. 'Ah, curiosity drives it, but caution tempers it. A wise beast for Lord Vivec's study. Perhaps it can teach fools wisdom and open sages to hope.' And so it ended.\"—Armiger Tharys's Journal",
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerram.dds",
                            ["furnitureId"] = 8703,
                            ["id"] = 11071,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Buoyant Armiger Ram",
                        },
                        [9784] = 
                        {
                            ["description"] = "\"Ride one of these piebalds for any travel outside Sentinel. They love the heat more than any senche-serval I've stabled. Makes me believe the tales of Summerset outcasts raising them out in one of the bandit caves nearby decades ago.\"—Burhan, Stablehand",
                            ["icon"] = "/esoui/art/icons/mount_tyrigelsenche.dds",
                            ["furnitureId"] = 7952,
                            ["id"] = 9784,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Piebald Senche-Serval",
                        },
                        [9785] = 
                        {
                            ["description"] = "Argonian farmers sell Fellrunner feathers to hunters by the sack. Even one armband of pale Fellrunner down allows hunters to slink through the swamps of Murkwood unnoticed.",
                            ["icon"] = "/esoui/art/icons/pet_nightcrestfellrunn.dds",
                            ["furnitureId"] = 7953,
                            ["id"] = 9785,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Nightcrest Fellrunner",
                        },
                        [7738] = 
                        {
                            ["description"] = "Though this adorable fawn's kin shimmer with hues different than its own, the first color ever seen was the pearly white glow on this one. Give it enough care and you can help it overcome its shyness, allowing it to cavort at your side.",
                            ["icon"] = "/esoui/art/icons/pet_valefawn.dds",
                            ["furnitureId"] = 6724,
                            ["id"] = 7738,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Vale Fawn",
                        },
                        [7739] = 
                        {
                            ["description"] = "\"The red glow of a Nightrose stems from its time of birth,\" a spelunker claims. \"If the sky above is red, so is the fawn.\" While some scoff at this, all agree on one thing: Nightroses have a sixth sense for danger, nudging awake any chosen family.",
                            ["icon"] = "/esoui/art/icons/pet_valefawnred.dds",
                            ["furnitureId"] = 6725,
                            ["id"] = 7739,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Nightrose Vale Fawn",
                        },
                        [7740] = 
                        {
                            ["description"] = "Its amber-gold glimmer creates a warmth that one stablemaster states, \"Can get you through chilly nights under the Skyrim stars.\" All it takes to keep one of these vale fawns at your side is a lick of honey now and again.",
                            ["icon"] = "/esoui/art/icons/pet_valefawnyellow.dds",
                            ["furnitureId"] = 6726,
                            ["id"] = 7740,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ambersheen Vale Fawn",
                        },
                        [7741] = 
                        {
                            ["description"] = "For a time, scholars thought only one type of vale fawn existed. Now, knowing better, some wonder why the variation? The fawns care not. But, ones with a green shimmer love to race. Choose one as a companion, and it might even race you!",
                            ["icon"] = "/esoui/art/icons/pet_valefawngreen.dds",
                            ["furnitureId"] = 6727,
                            ["id"] = 7741,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Emerald Vale Fawn",
                        },
                        [7742] = 
                        {
                            ["description"] = "One scholar studying vale fawns notes that the purple-hued Orchidfall fawn—named after a now-lost flora-filled cavern in Skyrim—enjoys eating flowers. \"Give it a flower, and it's your friend for life!\" Do you have your flower in hand?",
                            ["icon"] = "/esoui/art/icons/pet_valefawnpurple.dds",
                            ["furnitureId"] = 6728,
                            ["id"] = 7742,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Orchidfall Vale Fawn",
                        },
                        [9791] = 
                        {
                            ["description"] = "Brigands in Wayrest tried to use these creatures to help them harass nobles of that town, but after that plan backfired on them, they sold their stock. Lucky for you, these fiery salamanders receive loyalty training before being sold now.",
                            ["icon"] = "/esoui/art/icons/pet_magmaskinsalamander.dds",
                            ["furnitureId"] = 8021,
                            ["id"] = 9791,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Appleback Salamander",
                        },
                        [11070] = 
                        {
                            ["description"] = "\"Exuberance flowed from the emerald ornaug, then it despaired. 'It enjoyed its freedom from the cage, yet lack of purpose brought it low. Perhaps Lord Vivec can grant it one among us.' And so it joined our other three steeds.\"—Armiger Tharys's Journal",
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerornag.dds",
                            ["furnitureId"] = 8702,
                            ["id"] = 11070,
                            ["category"] = "Serpentes",
                            ["hint"] = "",
                            ["name"] = "Buoyant Armiger Ornaug",
                        },
                        [5697] = 
                        {
                            ["description"] = "\"It is hard to start a campfire in the damps of the deep marsh, yes? Not when you have a Scorching Horse-Lizard! With one of these as your mount, you will never again have to eat cold eel stew!\" —Ukaspa, Stablemaster of Lilmoth",
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_apex_horse.dds",
                            ["furnitureId"] = 5562,
                            ["id"] = 5697,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Scorching Horse-Lizard",
                        },
                        [5698] = 
                        {
                            ["description"] = "\"The Dwarven Spider Mounts from the Infernium Forge are unusual and distinctive, indicating to this Dwemer scholar that they all come from the hand of a single Deep Elf artisan.\" —Guylaine Marilie",
                            ["icon"] = "/esoui/art/icons/mounticon_dwarvenspider_flame..dds",
                            ["furnitureId"] = 5563,
                            ["id"] = 5698,
                            ["category"] = "Constructs",
                            ["hint"] = "",
                            ["name"] = "Infernium Dwarven Spider",
                        },
                        [5699] = 
                        {
                            ["description"] = "\"The Dwarven Spiderlings from the Infernium Forge are unusual and distinctive, indicating to this Dwemer scholar that they all come from the hand of a single Deep Elf artisan.\" —Guylaine Marilie",
                            ["icon"] = "/esoui/art/icons/pet_219_flamedwarvenspider.dds",
                            ["furnitureId"] = 5564,
                            ["id"] = 5699,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Infernium Dwarven Spiderling",
                        },
                        [11068] = 
                        {
                            ["description"] = "\"Vicious, the bear was, all a-rumble with menace, despite its chains. 'Let us please Lord Vivec with this two-toned creature. Its growls show promise in a world filled with craven whispers.' And so it began.\"—Armiger Tharys's Journal",
                            ["icon"] = "/esoui/art/icons/mount_buoyantarmigerbear.dds",
                            ["furnitureId"] = 8700,
                            ["id"] = 11068,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Buoyant Armiger Bear",
                        },
                        [9797] = 
                        {
                            ["description"] = "Native to the Systres Islands, these haj mota prefer coastal areas, where they spend so much time submerged that coral forms on them. So, if you love to spend quality time at the beach, this fierce predator might just make for a great beach buddy!",
                            ["icon"] = "/esoui/art/icons/pet_driftwaterhajmota.dds",
                            ["furnitureId"] = 8054,
                            ["id"] = 9797,
                            ["category"] = "Exotic",
                            ["hint"] = "Obtained by using 25 Coral Haj Mota Lures from Ghost Haven Bay in High Isle, and 25 Coral Haj Mota Decoys from the Spire of the Crimson Coin.",
                            ["name"] = "Coral Haj Mota",
                        },
                        [11059] = 
                        {
                            ["description"] = "Summoned from the fourth Sinus of Takubar, Hoarfrost will convey your goods (or the goods of your groupmates) to the cold-flame pits of Oblivion in exchange for mortal coins.\n\nAncient bindings prevent them from appearing in Cyrodiil or Battlegrounds.",
                            ["icon"] = "/esoui/art/icons/assistant_hoarfrost.dds",
                            ["furnitureId"] = 8996,
                            ["id"] = 11059,
                            ["category"] = "Assistants",
                            ["hint"] = "",
                            ["name"] = "Hoarfrost, Takubar Trader",
                        },
                        [10926] = 
                        {
                            ["description"] = "Before these colorful creatures served as mounts for the Urshilaku, their shells were ground up for pigment. Seeing their potential as fast-moving steeds, handlers trained them for scouting missions, often hiding their bright colors with dried mud.",
                            ["icon"] = "/esoui/art/icons/mount_urshilakunixox.dds",
                            ["furnitureId"] = 8685,
                            ["id"] = 10926,
                            ["category"] = "Arthropods",
                            ["hint"] = "",
                            ["name"] = "Urshilaku Nix-Ox",
                        },
                        [10906] = 
                        {
                            ["description"] = "\"Anu. Padomay. That's what this camel reminds me of. Where one ends, the other begins. What one begins, the other ends. Striations of stasis and change. One. Eternal. Quintessential. Just like this camel. Duck. It's about to spit.\"—Atazal of Sentinel",
                            ["icon"] = "/esoui/art/icons/mount_anupadomaycamel.dds",
                            ["furnitureId"] = 8681,
                            ["id"] = 10906,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Quintessential Camel",
                        },
                        [5705] = 
                        {
                            ["description"] = "\"This Chilling Senche-Lizard is quite rare; it comes from very deep in the swamp, from a tribe said to be dedicated to Frost spells as a means of living longer by living slower. Their Hist tree even drips with icicles (whatever they are)!\" —Ukaspa",
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_apex_senche.dds",
                            ["furnitureId"] = 5565,
                            ["id"] = 5705,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Chilling Senche-Lizard",
                        },
                        [5706] = 
                        {
                            ["description"] = "\"Nothing says 'Back off!' like riding into town on a mount so seething with poison that it glows in the dark. When one comes from a place as bizarre as Black Marsh, one really has to go over the top to be impressive.\" —Ukaspa of Lilmoth",
                            ["icon"] = "/esoui/art/icons/mounticon_murkmire_apex_wolf.dds",
                            ["furnitureId"] = 5566,
                            ["id"] = 5706,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Venomous Wolf-Lizard",
                        },
                        [5707] = 
                        {
                            ["description"] = "When Imperials of Akaviri descent settled in and around Rimmen toward the end of the Potentate, something about these local Ringtailed Wolves found favor with them, and they domesticated and bred them into distinctive mounts.",
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_ringtail.dds",
                            ["furnitureId"] = 5567,
                            ["id"] = 5707,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Rimmen Ringtailed Wolf",
                        },
                        [5708] = 
                        {
                            ["description"] = "Largest of all the furstocks, or \"breeds\" of Khajiit, the Senche-raht is fully intelligent, and in combat often serves simultaneously as warrior and mount.",
                            ["icon"] = "/esoui/art/icons/mounticon_monstroussenche_raht.dds",
                            ["furnitureId"] = 5568,
                            ["id"] = 5708,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Senche-Raht",
                        },
                        [5709] = 
                        {
                            ["description"] = "\"As the Sub-Sapiarch of Domestic Livestock, I was assigned by Larnatille to breed an appropriate mount for our sages to ride upon when working in the field. I proudly present my result: the loyal and majestic senche-serval!\" —Corderil of Sunhold",
                            ["icon"] = "/esoui/art/icons/mounticon_senche_summersetserval.dds",
                            ["furnitureId"] = 5569,
                            ["id"] = 5709,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Sapiarchic Senche-Serval",
                        },
                        [5710] = 
                        {
                            ["description"] = "As an incarnate nature spirit, an Indrik first appears in its comparatively drab Nascent form before somehow differentiating into one of their more splendid variations.",
                            ["icon"] = "/esoui/art/icons/mounticon_indrik_nascent.dds",
                            ["furnitureId"] = 5570,
                            ["id"] = 5710,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Nascent Indrik",
                        },
                        [10881] = 
                        {
                            ["description"] = "The scent of flowers precedes this cream-colored steed's arrival. White-and-merlot barding features the grinning silver-and-gold visage of Sanguine, Lord of Revelry. Will you let the promise made by its illusory roses and wine entice you into merriment?",
                            ["icon"] = "/esoui/art/icons/mount_steedofrevelry.dds",
                            ["furnitureId"] = 8678,
                            ["id"] = 10881,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Sanguine Revelry Steed",
                        },
                        [5712] = 
                        {
                            ["description"] = "This smaller breed of haj mota lurks in the brackish estuaries of Black Marsh's southern coast, camouflaged by the gray color of the murky tidewater. When hand-raised from hatching, they make surprisingly pleasant pets.",
                            ["icon"] = "/esoui/art/icons/pet_hajmota_slateback.dds",
                            ["furnitureId"] = 5571,
                            ["id"] = 5712,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Slateback Haj Mota",
                        },
                        [5713] = 
                        {
                            ["description"] = "A haj mota is an ambush predator, waiting patiently in concealment until its prey should come into attack range. The Verdigris breed tends to hide in algae-covered pools where its color acts as camouflage.",
                            ["icon"] = "/esoui/art/icons/pet_hajmota_verdigris.dds",
                            ["furnitureId"] = 5572,
                            ["id"] = 5713,
                            ["category"] = "Exotic",
                            ["hint"] = "Acquired by traveling to Lilmoth in Murkmire for the first time.",
                            ["name"] = "Verdigris Haj Mota",
                        },
                        [5714] = 
                        {
                            ["description"] = "Though the adult Bear-Lizards can be quite intimidating, even fearsome, the roly-poly lizard cubs are disarmingly cute. (For reptiles, that is.)",
                            ["icon"] = "/esoui/art/icons/pet_221_murkmirebearcub.dds",
                            ["furnitureId"] = 5573,
                            ["id"] = 5714,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Bear-Lizard Cub",
                        },
                        [5715] = 
                        {
                            ["description"] = "When young Argonian egg-siblings tell their creche-parents they want a pony, this is what they mean. And now that you've seen it, don't you want one, too?",
                            ["icon"] = "/esoui/art/icons/pet_223_murkmirepony.dds",
                            ["furnitureId"] = 5574,
                            ["id"] = 5715,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Pony-Lizard",
                        },
                        [5716] = 
                        {
                            ["description"] = "True, it does hiss rather than meow, and has shiny scales rather than soft fur, but otherwise the Senche-Lizard Cub is just as adorable as any other kitten.",
                            ["icon"] = "/esoui/art/icons/pet_224_murkmiresenchecub.dds",
                            ["furnitureId"] = 5575,
                            ["id"] = 5716,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Senche-Lizard Cub",
                        },
                        [5717] = 
                        {
                            ["description"] = "The Wolf-Lizard Pup is simply adorable when it tries to howl, just hisses instead, and looks ever so confused.",
                            ["icon"] = "/esoui/art/icons/pet_225_murkmirewolfpup.dds",
                            ["furnitureId"] = 5576,
                            ["id"] = 5717,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Wolf-Lizard Pup",
                        },
                        [5718] = 
                        {
                            ["description"] = "Though you know it's just going to grow up and become big, dumb, scaly livestock, how can you resist those lizard-calf eyes?",
                            ["icon"] = "/esoui/art/icons/pet_222_murkmireguar.dds",
                            ["furnitureId"] = 5577,
                            ["id"] = 5718,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Guar-Lizard Calf",
                        },
                        [5719] = 
                        {
                            ["description"] = "Most Echalettes are docile and fawn-like, but not the Badger Ruff breed, which are strangely fierce and irritable. They're so ornery they've been known to chase away inquisitive Sabre Cats.",
                            ["icon"] = "/esoui/art/icons/pet_217_badgerechelette.dds",
                            ["furnitureId"] = 5578,
                            ["id"] = 5719,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Badger Ruff Echalette",
                        },
                        [5720] = 
                        {
                            ["description"] = "The migratory Monarch Butterfly is a common sight across all of southern Tamriel, and it's seen in the northern provinces during summer. The Monarch is said to represent the souls of the present, in contrast to the Ancestor Moth that represents the past.",
                            ["icon"] = "/esoui/art/icons/pet_232_monarchorange.dds",
                            ["furnitureId"] = 5579,
                            ["id"] = 5720,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Monarch Butterfly",
                        },
                        [5721] = 
                        {
                            ["description"] = "\"Ha ha! Fooled you, didn't it? Looks just like a Baby Dragon, doesn't it? Well, there are no such things, and you should know better. It's just an Illusion Imp with a rather Peryite look to it. Baby Dragon, really!\" —Abnur Tharn",
                            ["icon"] = "/esoui/art/icons/pet_252_dragonimp_green.dds",
                            ["furnitureId"] = 5580,
                            ["id"] = 5721,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Green Dragon Imp",
                        },
                        [5722] = 
                        {
                            ["description"] = "\"The Jerboas, you say? Ah, yes, the little jumping skeevers with the so-big ears. There are many in the Ashen Scar, and if you catch one when it's small, it makes for a pleasant, fuzzy friend. I had one when I was a kitten!\" —Shuzirri of Riverhold",
                            ["icon"] = "/esoui/art/icons/pet_242_jerboa.dds",
                            ["furnitureId"] = 5581,
                            ["id"] = 5722,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Ashen Scar Jerboa",
                        },
                        [5723] = 
                        {
                            ["description"] = "The legend among the underworld explorers of the Undaunted is that these little incendiary sprites are responsible for lighting all the candles, torches, and lanterns found burning underground, flying ahead of adventurers to ignite them in the dark.",
                            ["icon"] = "/esoui/art/icons/pet_218_brimstonenixad.dds",
                            ["furnitureId"] = 5582,
                            ["id"] = 5723,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Brimstone Nixad",
                        },
                        [9820] = 
                        {
                            ["description"] = "Fresh from Madam Whim's in Fargrave, this irrepressible Skaafin immediately imparts a surprisingly upbeat atmosphere to your abode. After adding Hezehk to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/houseguest_hezehk.dds",
                            ["furnitureId"] = 8059,
                            ["id"] = 9820,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Hezehk",
                        },
                        [9821] = 
                        {
                            ["description"] = "With her initial Daedric studies finished, Marafar hopes to uncover more secrets as she assists Artaeum's Relicmaster. Will you host her efforts? After adding Marafar to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["icon"] = "/esoui/art/icons/houseguest_marafar.dds",
                            ["furnitureId"] = 8060,
                            ["id"] = 9821,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Relic-Apprentice Marafar",
                        },
                        [10873] = 
                        {
                            ["description"] = "\"You'd think a salamander warped by the Spellscar would be a frightening beast, but I find the play of energies in their form enthralling. Also, no matter the weather, having one at your feet helps you stay comfortably warm or cool.\"—Naifa, Scholar",
                            ["icon"] = "/esoui/art/icons/pet_spellscarsalamander.dds",
                            ["furnitureId"] = 8676,
                            ["id"] = 10873,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Spellscar Salamander",
                        },
                        [10870] = 
                        {
                            ["description"] = "\"This one isn't sure just when these adorable jerboa first showed up in Rimmen, but they are recent. Also, nuisances. They distract so much, plus this one's keeps getting underfoot. Maybe it seeks to kill Sharrasti.\"—Sharrasti, Scholar",
                            ["icon"] = "/esoui/art/icons/pet_rimmenjerboa.dds",
                            ["furnitureId"] = 8675,
                            ["id"] = 10870,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Rimmen Jerboa",
                        },
                        [10858] = 
                        {
                            ["description"] = "House Telvanni is renowned for the brutality of their scholarly infighting. In shadowy caves across the Inner Sea, a cult to Hermaeus Mora has grown up among those expelled from the House but still thirsting for knowledge, power, and one day … revenge.",
                            ["icon"] = "/esoui/art/icons/mount_abyssalguar.dds",
                            ["furnitureId"] = 8670,
                            ["id"] = 10858,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Antecedent Scholar's Guar",
                        },
                        [11873] = 
                        {
                            ["description"] = "The adaptable durzogs that roam Tamriel's deserts have thick skin to protect from abrasive sands and feathers on their neck and back to help with cooling. Their sandy coloring and decreased need for water make them efficient predators in the dunes.",
                            ["icon"] = "/esoui/art/icons/mount_sandsqualldurzog.dds",
                            ["furnitureId"] = 9557,
                            ["id"] = 11873,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Sandsquall Durzog",
                        },
                        [11874] = 
                        {
                            ["description"] = "These petulant welwas hail from Wrothgar and more than live up to their name. Hardened by their difficult landscape, the creatures delight in punishing their riders for the smallest slight, whether it's a late feeding or a slightly too-tight saddle.",
                            ["icon"] = "/esoui/art/icons/mount_dragontailwelwa.dds",
                            ["furnitureId"] = 9558,
                            ["id"] = 11874,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Grudge-Rock Welwa",
                        },
                        [10854] = 
                        {
                            ["description"] = "Trophy taken from Archdruid Devyric in honor of an Undaunted victory in Earthen Root Enclave.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophymonstrousbear001.dds",
                            ["furnitureId"] = 8626,
                            ["id"] = 10854,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Earthen Root Enclave.",
                            ["name"] = "Trophy: Archdruid Devyric",
                        },
                        [11876] = 
                        {
                            ["description"] = "You and your groupmates can tend to the grove of your mind by summoning Drinweth, who will allow you to change and save builds outside of your home. A challenging past with various martial forces means she won't aid you in Cyrodiil or the Battlegrounds.",
                            ["icon"] = "/esoui/art/icons/assistant_drinweth_valenwoodarmorer.dds",
                            ["furnitureId"] = 9559,
                            ["id"] = 11876,
                            ["category"] = "Assistants",
                            ["hint"] = "",
                            ["name"] = "Drinweth, Valenwood Armorer",
                        },
                        [9829] = 
                        {
                            ["description"] = "Soul Shriven knights ride only the most finely stitched steeds. As one old knight proclaimed, \"Don't mind the bit of fray at the bottom there. Or the pesky splinters sticking out of the handle. This guar is a jolly smooth ride!\"",
                            ["icon"] = "/esoui/art/icons/mount_stitchedwellstitchguar.dds",
                            ["furnitureId"] = 8061,
                            ["id"] = 9829,
                            ["category"] = "Toys",
                            ["hint"] = "|cff0000This mount doesn't increase your movement speed. Riding Lessons don't affect its appearance. This mount cannot path when placed as a furnishing.|r",
                            ["name"] = "Stitchedwell Stick Guar",
                        },
                        [11878] = 
                        {
                            ["description"] = "Often found crawling up the banks of the Strid River, these crabs have recently made their way upstream into West Weald. While they taste delicious, many collectors prefer to keep them as pets thanks to their dazzling color.",
                            ["icon"] = "/esoui/art/icons/pet_stridrivercrab.dds",
                            ["furnitureId"] = 9561,
                            ["id"] = 11878,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Strid River Crab",
                        },
                        [11879] = 
                        {
                            ["description"] = "Rarer than their alabaster cousins in High Rock, these spotted sheep are beloved for their gentle demeanors and extra soft wool. Many inexperienced farmers can't resist their sweet faces, and these sheep have been known to grow fat on extra treats.",
                            ["icon"] = "/esoui/art/icons/pet_coffeespottedsheep.dds",
                            ["furnitureId"] = 9562,
                            ["id"] = 11879,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Cream and Coffee Sheep",
                        },
                        [11880] = 
                        {
                            ["description"] = "Born in the blasted wastes of Coldharbour, Molag Bal's ferocious welwa pursue their prey with terrifying tenacity. It is said that only the chains of the Dark Anchors themselves can hold the beasts back once they've scented their quarry.",
                            ["icon"] = "/esoui/art/icons/mount_coldharbourwelwa.dds",
                            ["furnitureId"] = 9563,
                            ["id"] = 11880,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Anchorborn Welwa",
                        },
                        [11881] = 
                        {
                            ["description"] = "This feline fixes you with a gaze that seems to say, \"Your attempts to pet me are presumptuous! Do you think mice can stop the most powerful catromancer Tamriel has ever known? This form is my first step toward immortality! Witness my true kitty power!\"",
                            ["icon"] = "/esoui/art/icons/mount_meownimarco.dds",
                            ["furnitureId"] = 9564,
                            ["id"] = 11881,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Meownimarco",
                        },
                        [7786] = 
                        {
                            ["description"] = "Once known as the toughest Baandari thief in the Stitches, Abahayda ran afoul of a terrible curse in the Ashen Scar. She seeks a companion who will help restore her former life and vigor. Is that you?",
                            ["icon"] = "/esoui/art/icons/mount_curseboundraht.dds",
                            ["furnitureId"] = 6729,
                            ["id"] = 7786,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Cursebound Senche-Raht",
                        },
                        [10709] = 
                        {
                            ["description"] = "After forcing sabre cats to drink the Blood of Coldharbour, Legion Zero soldiers mounted up and secured the Imperial City Nobles District for Mannimarco. Many of these soldiers died, leaving their steeds without riders. Perfect—for you, anyway.",
                            ["icon"] = "/esoui/art/icons/mount_legionzerosabrecat.dds",
                            ["furnitureId"] = 8601,
                            ["id"] = 10709,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Legion Zero Sabre Cat",
                        },
                        [7788] = 
                        {
                            ["description"] = "\"It's said that when a worthy Nord seeks a glorious end, Sovngarde will send them a fleet steed to spirit them to their final battle, but pay no mind to skalds who sing of a horse of many legs.\"—Clever Woman Moritra",
                            ["icon"] = "/esoui/art/icons/horse_goldensteed.dds",
                            ["furnitureId"] = 6730,
                            ["id"] = 7788,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Valiant Sovngarde Charger",
                        },
                        [7789] = 
                        {
                            ["description"] = "\"The clawthanes of Sovngarde often stand watch over the Whalebone Bridge, but some choose to join forces with a courageous soul in Skyrim or beyond. Noble wolves, these are, and clever.\"—Clever Woman Moritra",
                            ["icon"] = "/esoui/art/icons/mount_sovngardeclawthanewolf.dds",
                            ["furnitureId"] = 6731,
                            ["id"] = 7789,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Sovngarde Clawthane Wolf",
                        },
                        [7790] = 
                        {
                            ["description"] = "\"Lithe sabre cats are prized among Sovngarde's heroes, particularly those called valorfangs, who died while defending their riders. They stand ready at the Hall of Valor, waiting to convey a hero to a warrior in need of aid.\"—Clever Woman Moritra",
                            ["icon"] = "/esoui/art/icons/mount_goldensteedsabercat.dds",
                            ["furnitureId"] = 6732,
                            ["id"] = 7790,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Sovngarde Valorfang Sabre Cat",
                        },
                        [11887] = 
                        {
                            ["description"] = "\"Beware lone roads and moonless nights. Beware the haunted hooves. Beware the burning-coal eyes and the fiery trail that follows each dogged step. Most of all, beware of the path of the steed's terrible riders.\"—Folk Legends of Tamriel",
                            ["icon"] = "/esoui/art/icons/mount_nightmarepillioncharger.dds",
                            ["furnitureId"] = 9569,
                            ["id"] = 11887,
                            ["category"] = "Multi-Rider",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["name"] = "Nightmare Pillion Courser",
                        },
                        [10646] = 
                        {
                            ["description"] = "Zuugarz of Orsinium says she first discovered these obsidian-worked animunculi, a claim backed up by the loyal construct that follows her around. She's since learned her scholarly companion \"gifted\" it to her, but that's not something she's eager to share.",
                            ["icon"] = "/esoui/art/icons/pet_obsidiandwarvensphere.dds",
                            ["furnitureId"] = 8574,
                            ["id"] = 10646,
                            ["category"] = "Exotic",
                            ["hint"] = "Acquired by completing the achievement \"Keeper of the Bastion.\"",
                            ["name"] = "Obsidian Dwarven Sphere",
                        },
                        [10645] = 
                        {
                            ["description"] = "A rare sight, these colorful foxes keep to the shadows in the wild. When trained to the saddle, they proudly display their glossy coats and fine saddlery. Their favorite food is snow berries, and they will do almost anything for their daily treat.",
                            ["icon"] = "/esoui/art/icons/mount_duskemberfox.dds",
                            ["furnitureId"] = 8573,
                            ["id"] = 10645,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Duskember Fox",
                        },
                        [10644] = 
                        {
                            ["description"] = "These brown-furred bats pollinate flowers along the Xylo River. Without them, nature's web in the Valenwood would be deeply disrupted. Plus they look adorable when they sneeze.",
                            ["icon"] = "/esoui/art/icons/pet_pollenbat.dds",
                            ["furnitureId"] = 8572,
                            ["id"] = 10644,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Xylo Pollen Bat",
                        },
                        [7795] = 
                        {
                            ["description"] = "\"During times of great need, Sovngarde releases some of its heroes back into the world, and legendary beasts to serve them. The stoutheart bear is one such creature. A fearless companion to carry true warriors to battle.\"—Clever Woman Moritra",
                            ["icon"] = "/esoui/art/icons/mount_sovngardebear.dds",
                            ["furnitureId"] = 6734,
                            ["id"] = 7795,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Sovngarde Stoutheart Bear",
                        },
                        [7796] = 
                        {
                            ["description"] = "\"Guar who fall in battle earn a place in Sovngarde. Some later walk among us, serving as faithful and courageous mounts to those who dedicate themselves to brave acts. They leap quickly into action when called.\"—Clever Woman Moritra",
                            ["icon"] = "/esoui/art/icons/mount_goldensteedguar.dds",
                            ["furnitureId"] = 6735,
                            ["id"] = 7796,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Valorous Sovngarde Guar Strider",
                        },
                        [7797] = 
                        {
                            ["description"] = "\"Camels do indeed thrive within Sovngarde. When called to join battle in Tamriel, these resplendent creatures eagerly race forward to meet their valorous riders. Do not believe the claims that they spit mead, though.\"—Clever Woman Moritra",
                            ["icon"] = "/esoui/art/icons/camelmount_goldensteed.dds",
                            ["furnitureId"] = 6736,
                            ["id"] = 7797,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Resplendent Sovngarde Camel",
                        },
                        [10633] = 
                        {
                            ["description"] = "\"Tales say Grahtwood's ancient oaks called these black-furred ursauks from the deep woods. But why? Every reason this one hears is different! Guards for a sapling grove. Help with a werewolf problem. Or maybe for bear hugs.\"—Zhiraz, Traveling Farmhand",
                            ["icon"] = "/esoui/art/icons/mount_inkheartmonstrousbear.dds",
                            ["furnitureId"] = 8571,
                            ["id"] = 10633,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Inkfur Ursauk",
                        },
                        [10632] = 
                        {
                            ["description"] = "\"Each morning during my travels around Grahtwood, one of the local fishers clung to the trunk of a nearby tree. I think it wanted some of my breakfast, so on the third day, I shared. Now it follows me everywhere.\"—Nurome",
                            ["icon"] = "/esoui/art/icons/pet_grahtwoodfisher.dds",
                            ["furnitureId"] = 8570,
                            ["id"] = 10632,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Grahtwood Fisher",
                        },
                        [10605] = 
                        {
                            ["description"] = "These adventurous cubs love playing in waterfalls, often using crevices behind them as lairs during the winter. The smell of butter draws them like nothing else. As a result, some claim a dairy farmer first tamed one of these cubs.",
                            ["icon"] = "/esoui/art/icons/pet_kvatchbrindlebearcub.dds",
                            ["furnitureId"] = 8553,
                            ["id"] = 10605,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Brindle Bear Cub",
                        },
                        [10604] = 
                        {
                            ["description"] = "\"To fear change wastes time one could spend engaging with the moment. These dark creatures are gifts from our past to both voh-vastei and those who need to be led into the present.\"—Nisswo Uaxal",
                            ["icon"] = "/esoui/art/icons/pet_duskfallancestorlizard.dds",
                            ["furnitureId"] = 8552,
                            ["id"] = 10604,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Duskfall Ancestor Lizard",
                        },
                        [10600] = 
                        {
                            ["description"] = "Using knowledge gained from the forbidden book Occaecium Beluaria, followers of Hermaeus Mora transformed a welwa into a multi-hued, darkly shimmering steed. He allows his most experienced agents in Tamriel to use them for overland tasks.",
                            ["icon"] = "/esoui/art/icons/mount_oilslickwelwa.dds",
                            ["furnitureId"] = 8550,
                            ["id"] = 10600,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Duskfall Welwa",
                        },
                        [10599] = 
                        {
                            ["description"] = "When this beautiful beast lost their rider while traversing a labyrinth, this banded Senche-raht left to seek mystical help to get back inside. Since their efforts often lead them into peril, Nushaben hopes to find a partner for the long journeys ahead.",
                            ["icon"] = "/esoui/art/icons/mount_umbralstripesencheraht.dds",
                            ["furnitureId"] = 8549,
                            ["id"] = 10599,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Umbral Striped Senche-Raht",
                        },
                        [10587] = 
                        {
                            ["description"] = "You may place the hourglass within your home. Focusing on its falling sands causes them to blur, and local perception of time to shift. Until the hourglass is disturbed, time seems to stand still. Enjoy everything from eternal sunrises to endless nights.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_antsealkoshhourglass001_fx.dds",
                            ["furnitureId"] = 8679,
                            ["id"] = 10587,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Sacred Hourglass of Alkosh",
                        },
                        [10586] = 
                        {
                            ["description"] = "In some towns, pledging oaths before Mother Mara is accompanied by a lavish gift. Legends describe a steed exchanged at Bravil, white as fresh snow and adorned with spring's first flowers. And thus a tradition was born that has survived until today.",
                            ["icon"] = "/esoui/art/icons/mount_mothermaramarehorse.dds",
                            ["furnitureId"] = 8547,
                            ["id"] = 10586,
                            ["category"] = "Multi-Rider",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["name"] = "Mara's Pledge Mare",
                        },
                        [10582] = 
                        {
                            ["description"] = "Hunters often rely on the services of a loyal dog to protect them as they retrieve their kills. This breed not only ensures that their hunter remains well-guarded, but also provides quiet companionship.",
                            ["icon"] = "/esoui/art/icons/pet_chorralbirddog.dds",
                            ["furnitureId"] = 8546,
                            ["id"] = 10582,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Biscuit Bear-Dog",
                        },
                        [10579] = 
                        {
                            ["description"] = "The shimmering blues and purples of this ornaug mimic the coral shallows around Galen. If you stumble upon these playful creatures cavorting in the water, move slowly and you may just tickle their curiosity. If they like you, one might even adopt you.",
                            ["icon"] = "/esoui/art/icons/mount_sapphireornaug.dds",
                            ["furnitureId"] = 8545,
                            ["id"] = 10579,
                            ["category"] = "Serpentes",
                            ["hint"] = "",
                            ["name"] = "Shallowstalker Ornaug",
                        },
                        [10578] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Dreadsail Reef.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialcoralatronach001.dds",
                            ["furnitureId"] = 8544,
                            ["id"] = 10578,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Dreadsail Reef.",
                            ["name"] = "Bust: Tideborn Taleria",
                        },
                        [10577] = 
                        {
                            ["description"] = "Trophy taken from Tideborn Taleria in honor of an Undaunted victory in Dreadsail Reef.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophycoralatronach001.dds",
                            ["furnitureId"] = 8543,
                            ["id"] = 10577,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Dreadsail Reef.",
                            ["name"] = "Trophy: Tideborn Taleria",
                        },
                        [10576] = 
                        {
                            ["description"] = "Scrolls from Direfrost Keep indicate that the ice witches first invoked these creatures as vessels to contain their rage and hunt those who had wronged them. Presumably they wanted loyal familiars, but found the bears also make formidable mounts.",
                            ["icon"] = "/esoui/art/icons/mount_iceragebear.dds",
                            ["furnitureId"] = 8542,
                            ["id"] = 10576,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Icerage Bear",
                        },
                        [10510] = 
                        {
                            ["description"] = "A perfect display case for your perfect decks! What more can you ask for other than victory?",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_totdisplaycase001.dds",
                            ["furnitureId"] = 8537,
                            ["id"] = 10510,
                            ["category"] = "General",
                            ["hint"] = "Acquired by completing the Deck Builder Achievement.",
                            ["name"] = "Tales of Tribute Decks, Display",
                        },
                        [10509] = 
                        {
                            ["description"] = "Set up your home's gaming room properly with this exquisite Tales of Tribute table.\n\n|cFFFFFFThis table does not allow you to play Tales of Tribute matches.|r",
                            ["icon"] = "/esoui/art/icons/housing_uni_fur_housingtottable001.dds",
                            ["furnitureId"] = 8536,
                            ["id"] = 10509,
                            ["category"] = "General",
                            ["hint"] = "Acquired by reaching Master Rank in Tales of Tribute.",
                            ["name"] = "Tales of Tribute Table, Display",
                        },
                        [5765] = 
                        {
                            ["description"] = "The rare and colorful Shock Nixad looks rather like a tiny, winged Storm Atronach, though without the whirling electric rocks. They make loyal companions—though they may also make your hair stand on end!",
                            ["icon"] = "/esoui/art/icons/pet_228_stormnixad.dds",
                            ["furnitureId"] = 5583,
                            ["id"] = 5765,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Blue Shock Nixad",
                        },
                        [10429] = 
                        {
                            ["description"] = "\"You wouldn't think a guar would get along with a murder of crows, but this fine fellow does! Maybe it's the exquisite purple hue? In any case, it's started leaving gemstones for the little menaces. Most peculiar.\"—Irastimil Direnni, Creature Creator",
                            ["icon"] = "/esoui/art/icons/pet_purpleguar.dds",
                            ["furnitureId"] = 8434,
                            ["id"] = 10429,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Crow Court Pony Guar",
                        },
                        [10427] = 
                        {
                            ["description"] = "Lady Joslin Garick brought her crew home safely until the last time—or so the legends state. Now that you have proven worthy of her heritage, you can hang this famous All Flags Navy captain's shield on your wall.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_sacredshield001.dds",
                            ["furnitureId"] = 8433,
                            ["id"] = 10427,
                            ["category"] = "General",
                            ["hint"] = "Awarded for completing the quest, \"Race for Honor\" in High Isle.",
                            ["name"] = "Lady Garick's Sacred Shield",
                        },
                        [10418] = 
                        {
                            ["description"] = "\"Harrowforged Durzog: Ready your quickest poisons and most potent spells. Your target defeated horrors possibly beyond your ken to earn this glorious crimson steed.\"—Recent notation in a chapbook for Dark Brotherhood Initiates",
                            ["icon"] = "/esoui/art/icons/mount_harrowforgeddurzog.dds",
                            ["furnitureId"] = 8431,
                            ["id"] = 10418,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Harrowforged Durzog",
                        },
                        [10399] = 
                        {
                            ["description"] = "The ancestry of this rambunctious dark-furred pup goes all the way back to the Five Hundred Companions of Ysgramor. That doesn't stop it from acting like a mischievous little furball, though!",
                            ["icon"] = "/esoui/art/icons/pet_goldcollaredwolfpup.dds",
                            ["furnitureId"] = 8416,
                            ["id"] = 10399,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Companion's Wolf Pup",
                        },
                        [10398] = 
                        {
                            ["description"] = "\"These hard-headed creatures might seem empty-minded. Yet, somehow, they keep you alive when you've angered the ornaugs. Such is the nature of a loyal mount.\"—Saissula, Stablemaster",
                            ["icon"] = "/esoui/art/icons/mount_xitahranagonizer.dds",
                            ["furnitureId"] = 8415,
                            ["id"] = 10398,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Scarlet War Pangrit",
                        },
                        [10397] = 
                        {
                            ["description"] = "\"What have you learned, Watcher? Mortals on Nirn keep small companions. Oh, is that so? Names you say? As my small companion, you wish one? Very well, I shall call you Ocula. You have indeed earned it.\"—Morian Zenas",
                            ["icon"] = "/esoui/art/icons/pet_doomtruthpocketwatcher.dds",
                            ["furnitureId"] = 8414,
                            ["id"] = 10397,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Cipher's Eye Pocket Watcher",
                        },
                        [10396] = 
                        {
                            ["description"] = "Easily identifiable by their flaming red feathers, this aggressive barnyard fowl has been used as an alternative to a guard dog by knights on crusade. Their loud crowing is nearly impossible to sleep through.",
                            ["icon"] = "/esoui/art/icons/pet_goldenglowchicken.dds",
                            ["furnitureId"] = 8413,
                            ["id"] = 10396,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Crusader's Coin Chicken",
                        },
                        [10389] = 
                        {
                            ["description"] = "\"You'd not think to see camels around this one's home of Black Heights, but you'd be wrong! We love to brighten these fragrant beasts with pigments and a touch of sleekening oil so that they provide both beauty and transport!\"—Hurzarr, Artist",
                            ["icon"] = "/esoui/art/icons/mount_blackheightscamel.dds",
                            ["furnitureId"] = 8412,
                            ["id"] = 10389,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Black Heights Camel",
                        },
                        [10384] = 
                        {
                            ["description"] = "\"The first pillion mount in Skingrad came about when two of Rislav's siblings wished to ride with fewer guards about. 'Two guards per horse,' they were told. Thus they created the first battle-hardened pillion mount.\"—Richon Charchere, Stablemaster",
                            ["icon"] = "/esoui/art/icons/mount_skingradpillioncourser.dds",
                            ["furnitureId"] = 8408,
                            ["id"] = 10384,
                            ["category"] = "Multi-Rider",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["name"] = "Skingrad Pillion Courser",
                        },
                        [10332] = 
                        {
                            ["description"] = "\"This beast lives a life of controlled fury that only its rider keeps in check. Unfortunately for us, these durzogs usually pick riders who let loose their own wrath with great frequency.\"—Medresi Guvron of Markarth",
                            ["icon"] = "/esoui/art/icons/mount_ragebounddurzog.dds",
                            ["furnitureId"] = 8392,
                            ["id"] = 10332,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Ragebound Durzog",
                        },
                        [10331] = 
                        {
                            ["description"] = "\"You're not hearing me. These were nothing like normal kagouti. Fury, froth, and carnage. And their riders, eyes wide with harnessed rage. That's what drew me in. That's why I joined them.\"—Medresi Guvron of Markarth",
                            ["icon"] = "/esoui/art/icons/mount_rageboundkagouti.dds",
                            ["furnitureId"] = 8391,
                            ["id"] = 10331,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Ragebound Kagouti",
                        },
                        [10330] = 
                        {
                            ["description"] = "\"Each pelt and bone on this monster of a bear reminds its rider of past battles. Rage turned to an end. Victory ripped from the rider's enemies. You know the feeling, I think. It's in your eyes. Rage. Barely controlled.\"—Arparnagh of Markarth",
                            ["icon"] = "/esoui/art/icons/mount_rageboundbear.dds",
                            ["furnitureId"] = 8390,
                            ["id"] = 10330,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Ragebound Bear",
                        },
                        [9874] = 
                        {
                            ["description"] = "\"Legends claim the Erabenimsun tamed these luminous creatures after Ashu-Ammu rode the first nix-ox into battle. While it's strange to choose a steed whose glow gives away your position, some warriors delight in added danger before battle.\"—Murdyn Athren",
                            ["icon"] = "/esoui/art/icons/mount_rubyfiretorchnix.dds",
                            ["furnitureId"] = 8063,
                            ["id"] = 9874,
                            ["category"] = "Arthropods",
                            ["hint"] = "",
                            ["name"] = "Rubyflare Torchnix",
                        },
                        [9875] = 
                        {
                            ["description"] = "\"At first, Baezati was angry. They give him a camel? Baezati rides nothing less than a charger. But this one must confess he enjoyed the ride. It was smooth. Fast. Surefooted. Even the rocks around Hel Ra gave the beast no issues.\"—Baezati's Travelogues",
                            ["icon"] = "/esoui/art/icons/mount_darkflamecamel.dds",
                            ["furnitureId"] = 8064,
                            ["id"] = 9875,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Hel Ra Camel of Kingship",
                        },
                        [9876] = 
                        {
                            ["description"] = "\"Graniteclaw Durzogs gorge themselves on the array of sea life swimming around the Systres Archipelago. Their markings help them blend in with the reefs and their feathers keep water from dripping into their eyes.\"—Excerpt from Physiology of Amphibians",
                            ["icon"] = "/esoui/art/icons/mount_graniteclawdurzog.dds",
                            ["furnitureId"] = 8065,
                            ["id"] = 9876,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Graniteclaw Durzog",
                        },
                        [11925] = 
                        {
                            ["description"] = "Hunter, Dark Brotherhood assassin, big brother—Kor is all this and more. Invite him into your abode, and he'll share observations about his life. After adding Kor to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/houseguest_kor.dds",
                            ["furnitureId"] = 9601,
                            ["id"] = 11925,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Kor",
                        },
                        [11926] = 
                        {
                            ["description"] = "When this fledgling Dark Brotherhood assassin isn't using her werewolf abilities to complete contracts, she reflects on her dual nature. After adding Hildegard to your home, you can set her on a path, plus you and your visitors can speak with her.",
                            ["icon"] = "/esoui/art/icons/houseguest_hildegard.dds",
                            ["furnitureId"] = 9602,
                            ["id"] = 11926,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Hildegard",
                        },
                        [10326] = 
                        {
                            ["description"] = "Wisps are sent from Y'ffre to herald the storms of Rain's Hand. To see one is to see the promise of new growth, new life, and a new chapter in nature's cycle.",
                            ["icon"] = "/esoui/art/icons/pet_stonelorewisp.dds",
                            ["furnitureId"] = 8386,
                            ["id"] = 10326,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Galen Wisp",
                        },
                        [10318] = 
                        {
                            ["description"] = "Tales tell of a mercenary abandoned by her lord during a storm. Her frozen lips begged for help. Sanguine heard her pleas, forming the ice into a steed. Come Saturalia morn, the crimson blood of that lord drenched the snow and evergreen boughs.",
                            ["icon"] = "/esoui/art/icons/mount_eveningstarice.dds",
                            ["furnitureId"] = 8369,
                            ["id"] = 10318,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Saturalia Ice Steed",
                        },
                        [10317] = 
                        {
                            ["description"] = "\"We found daedrats eating our ceremonial supplies in the cellar last Midyear. Now the damned things have gone green, and the Archdruid says they're a bridge from Galen to Oblivion? Draigh!\"—Callice Marence, formerly of Daggerfall",
                            ["icon"] = "/esoui/art/icons/pet_verdurousdaedrat.dds",
                            ["furnitureId"] = 8368,
                            ["id"] = 10317,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Moss Spine Daedrat",
                        },
                        [10303] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Shipwright's Regret.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranspriggan001.dds",
                            ["furnitureId"] = 8348,
                            ["id"] = 10303,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Shipwright's Regret.",
                            ["name"] = "Bust: Nazaray",
                        },
                        [10302] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Coral Aerie.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterancoralgryphon001.dds",
                            ["furnitureId"] = 8347,
                            ["id"] = 10302,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Coral Aerie.",
                            ["name"] = "Bust: Kargaeda",
                        },
                        [10301] = 
                        {
                            ["description"] = "Trophy taken from the Maormer Pirate in honor of an Undaunted victory in Shipwright's Regret",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyspriggan001.dds",
                            ["furnitureId"] = 8346,
                            ["id"] = 10301,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Shipwright's Regret.",
                            ["name"] = "Trophy: Nazaray",
                        },
                        [10300] = 
                        {
                            ["description"] = "Trophy taken from Varallion in honor of an Undaunted victory in Coral Aerie.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophycoralgryphon001.dds",
                            ["furnitureId"] = 8345,
                            ["id"] = 10300,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Coral Aerie.",
                            ["name"] = "Trophy: Kargaeda",
                        },
                        [10290] = 
                        {
                            ["description"] = "\"Do not underestimate the foxes trained by the Cult of the New Moon. Their glowing crimson eyes should be enough to warn you away. If you are foolish enough to attempt to steal an adult, say farewell to Nirn.\"—Jonnet of the Sunwalkers",
                            ["icon"] = "/esoui/art/icons/mount_newmoonfox.dds",
                            ["furnitureId"] = 8304,
                            ["id"] = 10290,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "New Moon Fox",
                        },
                        [10277] = 
                        {
                            ["description"] = "\"Do colors seem louder? Does music taste different? Does Tirdas have a personality? You're probably experiencing the synesthesic venom of the rare lemondot netch. Relax. It's harmless. A little new perspective never killed anybody.\"—Alinon the Alchemist",
                            ["icon"] = "/esoui/art/icons/pet_lemondotnetch.dds",
                            ["furnitureId"] = 8300,
                            ["id"] = 10277,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Lemondot Netch",
                        },
                        [10244] = 
                        {
                            ["description"] = "This savage welwa so interested members of the College of Sapiarchs that they brought several to Sil-Var-Woad for study. To help endear them to the public, an enterprising conservator trained them to saddle and \"lent\" them out into the wild.",
                            ["icon"] = "/esoui/art/icons/mount_speckledwelwa.dds",
                            ["furnitureId"] = 8286,
                            ["id"] = 10244,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Speckled Welwa",
                        },
                        [10243] = 
                        {
                            ["description"] = "\"Now, I says to my friend, look at all this dark anchor debris. No one's using it. No one owns it. And I look at his pony, this sickly little thing, and I say, why not make ourselves something nice?\"—\"Innovator\" Delan",
                            ["icon"] = "/esoui/art/icons/pet_planemeldpony.dds",
                            ["furnitureId"] = 8285,
                            ["id"] = 10243,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Anchorborn Pony",
                        },
                        [10242] = 
                        {
                            ["description"] = "Covered in coral and barnacles, this unusual sea creature moves like rushing water, creating a smooth traveling experience for its riders. Some speculate that Kyne crafted them from a sea storm and sent them to land to find those who revere her.",
                            ["icon"] = "/esoui/art/icons/mount_stormsurgehowler.dds",
                            ["furnitureId"] = 8280,
                            ["id"] = 10242,
                            ["category"] = "Canines",
                            ["hint"] = "Awarded by earning the \"Swashbuckler Supreme\" achievement.",
                            ["name"] = "Stormsurge Howler",
                        },
                        [10240] = 
                        {
                            ["description"] = "\"Where'd I get the cat? Cards. Poor thing was used in place of coin by some pet-smuggling lowlife. I'm teaching her how to count cards and fetch me a pint.\"—Privateer Mahk",
                            ["icon"] = "/esoui/art/icons/pet_rustpeltsabrecat.dds",
                            ["furnitureId"] = 8277,
                            ["id"] = 10240,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Rustpelt Sabre Cat",
                        },
                        [10239] = 
                        {
                            ["description"] = "Before the druids, before the coin-barons, before even the noble houses, the hermit crab held dominion over the Systres. Hauling its belongings wherever it travels, its beady eyes give you a look that seems to say, \"We're not so different, you and I.\"",
                            ["icon"] = "/esoui/art/icons/pet_damsonhermitcrab.dds",
                            ["furnitureId"] = 8276,
                            ["id"] = 10239,
                            ["category"] = "Exotic",
                            ["hint"] = "Awarded by earning the \"Lost Depths Explorer\" achievement.",
                            ["name"] = "Mulberry Hermit Crab",
                        },
                        [10238] = 
                        {
                            ["description"] = "It's the prestige of the mastiffs of Morthal that give the city's resident breed of bear-dog license to be a bit more … silly. Whether watching over children or facing intruders, someone's bound to get a licking.",
                            ["icon"] = "/esoui/art/icons/pet_spottedbeardog.dds",
                            ["furnitureId"] = 8275,
                            ["id"] = 10238,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Morthal Bear-Dog",
                        },
                        [10237] = 
                        {
                            ["description"] = "While Nords claim this lightning-limned wolf seeks out Kyne's champions to serve, the Stonelore Druids believe differently. Only an imbalance in nature would cause such a creature to coalesce. Its purpose? To find a rider who can restore the balance.",
                            ["icon"] = "/esoui/art/icons/mount_handmaidensstormwolf.dds",
                            ["furnitureId"] = 8274,
                            ["id"] = 10237,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Warmaiden's Wolf",
                        },
                        [7110] = 
                        {
                            ["description"] = "Bred for their wicked intelligence, the Emberthroat Durzog might just outwit the Netch Gouger Goblins that raised them. Only those with nimbler minds keep their loyalty—and that might just be you!",
                            ["icon"] = "/esoui/art/icons/pet_durzogemberthroat.dds",
                            ["furnitureId"] = 6541,
                            ["id"] = 7110,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Emberthroat Durzog",
                        },
                        [7272] = 
                        {
                            ["description"] = "\"Witches refused to share the grisly secrets of the Wickerfright summoning ritual … until now. Upon appearing, its wooden countenance twists into an eerie smile—a frightful expression, indeed!\"—Warlock Aldaale",
                            ["icon"] = "/esoui/art/icons/pet_wickerfrightbanekin.dds",
                            ["furnitureId"] = 6552,
                            ["id"] = 7272,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Wickerfright Banekin",
                        },
                        [7506] = 
                        {
                            ["description"] = "A miniature statue of Auri-El, chief deity of the Aldmeri pantheon, with an eagle.",
                            ["icon"] = "/esoui/art/icons/housing_ayl_run_dbhstatuegarlasmalatarsmall001.dds",
                            ["furnitureId"] = 6638,
                            ["id"] = 7506,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Auri-El, Aldmer King",
                        },
                        [6406] = 
                        {
                            ["description"] = "\"Senche steeds are already quiet. This one? It  moves as if it is the avatar of silence.\"—Jonnet of the Sunwalkers",
                            ["icon"] = "/esoui/art/icons/mount_newmoonsenche.dds",
                            ["furnitureId"] = 5978,
                            ["id"] = 6406,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "New Moon Senche",
                        },
                        [6404] = 
                        {
                            ["description"] = "\"Those seeking their way on dark sands should consider the New Moon Camel. Some say it feeds off the night itself. I say maybe so.\"—Jonnet of the Sunwalkers",
                            ["icon"] = "/esoui/art/icons/mount_newmooncamel.dds",
                            ["furnitureId"] = 5976,
                            ["id"] = 6404,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "New Moon Camel",
                        },
                        [102] = 
                        {
                            ["description"] = "When a Doom Wolf Pup looks at you with its big red eyes, you may just melt inside—but as soon as you turn your back, that little rascal will be shredding your embroidered Arenthian pillows and digging up your herbal garden.",
                            ["icon"] = "/esoui/art/icons/pet_082.dds",
                            ["furnitureId"] = 4187,
                            ["id"] = 102,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Doom Wolf Pup",
                        },
                        [618] = 
                        {
                            ["description"] = "Going to war may mean donning a helm, but beneath it an Argonian Pact warrior is entitled to wear this official Alliance Battle Crest, which keeps spines under control while still looking superb.",
                            ["icon"] = "/esoui/art/icons/hair_unisex_argonian_ebonheartflavor_01.dds",
                            ["furnitureId"] = 4303,
                            ["id"] = 618,
                            ["category"] = "Hair Styles",
                            ["hint"] = "",
                            ["name"] = "Pact Lizard Battle Crest",
                        },
                        [4671] = 
                        {
                            ["description"] = "The Bear was also one of the ancient Atmoran animal tokens, associated later with the Nord god Tsun, so the Frostbane Bear has historically been one of the most prestigious mounts a tradition-loving Nord could ride.",
                            ["icon"] = "/esoui/art/icons/mounticon_bear_scalecaller.dds",
                            ["furnitureId"] = 4768,
                            ["id"] = 4671,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Frostbane Bear",
                        },
                        [8457] = 
                        {
                            ["description"] = "\"While resting during their evacuation from Nenalata, guar mounts would voluntarily form a circle around the young and infirm, protecting them from danger. Their leader, Mafrelatta, set her calves amid them to share warmth.\"—Beredalmo the Signifier",
                            ["icon"] = "/esoui/art/icons/mount_ayleidguar.dds",
                            ["furnitureId"] = 7267,
                            ["id"] = 8457,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Nenalata Ayleid Guar",
                        },
                        [484] = 
                        {
                            ["description"] = "This loyal beast has been trained for warfare, and will stick with you through every kind of conflict. As a bonus, it comes outfitted in ancient Dwarven dog armor, canine barding as durable today as it was when it was first made many centuries in the past.",
                            ["icon"] = "/esoui/art/icons/pet_127.dds",
                            ["furnitureId"] = 4295,
                            ["id"] = 484,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Dwarven War Dog",
                        },
                        [483] = 
                        {
                            ["description"] = "The Khajiit of Corinthe believe the all-black Dark Moons Lynx is the worldly incarnation of Southpaw, the feline companion to Rajhin the Footpad, god of thieves. It's said Southpaw keeps watch while Rajhin is breaking and entering.",
                            ["icon"] = "/esoui/art/icons/pet_074.dds",
                            ["furnitureId"] = 4294,
                            ["id"] = 483,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Dark Moons Lynx",
                        },
                        [478] = 
                        {
                            ["description"] = "Though it may look like it just crawled from the depths of the Deadlands, the Infernal Sep Adder is actually native to the higher altitudes of Hammerfell. As pets, they are … not affectionate. Great conversation starters, though.",
                            ["icon"] = "/esoui/art/icons/pet_077.dds",
                            ["furnitureId"] = 4293,
                            ["id"] = 478,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Infernal Sep Adder",
                        },
                        [10209] = 
                        {
                            ["description"] = "\"Her calm presence keeps our patients at ease. Sometimes I ask them about the patterns and shapes they see in her coat, and their answers give me insight into their state of mind.\"—Mender Teliel",
                            ["icon"] = "/esoui/art/icons/pet_mottledsheep.dds",
                            ["furnitureId"] = 8259,
                            ["id"] = 10209,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Mottled Sheep",
                        },
                        [10208] = 
                        {
                            ["description"] = "\"We choose some of our guardians based on their overwhelming presence, like this ursauk. While riding it, I swear that the marrow in my bones resonates with her growls.\"—Rolmanoril of Glimmertarn",
                            ["icon"] = "/esoui/art/icons/mount_glistergloambear.dds",
                            ["furnitureId"] = 8258,
                            ["id"] = 10208,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Glimmertarn Ursauk",
                        },
                        [10207] = 
                        {
                            ["description"] = "\"When trees shrug off their colorful mantles, druids gather around a lynx summoned by Y'ffre. While they sing chants, the God of Song and Forest transforms the feline into a steed. Only a Hearthfire champion may claim such a mount.\"—Book of the Leaves",
                            ["icon"] = "/esoui/art/icons/mount_hearthfirelynx.dds",
                            ["furnitureId"] = 8257,
                            ["id"] = 10207,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Harvestleaf Lynx",
                        },
                        [10206] = 
                        {
                            ["description"] = "\"On the first night of Hearthfire, folks all over the Systres burn blessed oldefire logs. The smoke mingles with the soughing of leaves, giving form to spirits unseen the rest of the year. They take the form of loyal elk steeds.\"—Book of the Leaves",
                            ["icon"] = "/esoui/art/icons/mount_fireleafelk.dds",
                            ["furnitureId"] = 8256,
                            ["id"] = 10206,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Oldefire Elk",
                        },
                        [11959] = 
                        {
                            ["description"] = "The steeds of the Dark Brotherhood are conditioned to run blindly ahead in the darkness, fully trusting their riders. When the situation demands it, the horses will even run with multiple riders clinging to them on all sides, never flinching or faltering.",
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodtandemsteed.dds",
                            ["furnitureId"] = 9616,
                            ["id"] = 11959,
                            ["category"] = "Multi-Rider",
                            ["hint"] = "",
                            ["name"] = "Dark Brotherhood Crew Steed",
                        },
                        [11960] = 
                        {
                            ["description"] = "Few creatures are more apt mounts for the Dark Brotherhood than sabre cats. Light on their feet, agile, and with a hunting instinct to match their rider's, many Dark Brotherhood members believe a sabre cat mount is a gift from Sithis himself.",
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodsabrecat.dds",
                            ["furnitureId"] = 9617,
                            ["id"] = 11960,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Dark Brotherhood Sabre Cat",
                        },
                        [11961] = 
                        {
                            ["description"] = "\"Sithis teaches silence, yes, but stealth is not always the most important thing when you have enough speed and power on your side. That's why I choose to ride a kagouti. I find their ferocity more than makes up for the noise.\"—Dark Brother Bols Uveleth",
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhoodkagouti.dds",
                            ["furnitureId"] = 9618,
                            ["id"] = 11961,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Dark Brotherhood Kagouti",
                        },
                        [11962] = 
                        {
                            ["description"] = "Unlike other durzogs, which can become vocal when they sense their prey is near, those trained by the Dark Brotherhood have been bred for speed and silence.",
                            ["icon"] = "/esoui/art/icons/mount_darkbrotherhooddurzog.dds",
                            ["furnitureId"] = 9619,
                            ["id"] = 11962,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Dark Brotherhood Durzog",
                        },
                        [10201] = 
                        {
                            ["description"] = "Each of the druid circles keeps a different ursine companion. The Stonelore bear was originally bred to help with ambitious construction projects. While druids shaped heavy stone slabs, their bears supported the more fragile components of the structures.",
                            ["icon"] = "/esoui/art/icons/mount_stonelorebear.dds",
                            ["furnitureId"] = 8251,
                            ["id"] = 10201,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Stonelore Bear",
                        },
                        [10199] = 
                        {
                            ["description"] = "\"I prefer the company of animals over people. Communing with the Evergrowth provides a calming respite from the need to speak. This ursauk, for example, has proven most personable. And now, it needs a rider.\"—Druid Dolvasie",
                            ["icon"] = "/esoui/art/icons/mount_monsterousbear.dds",
                            ["furnitureId"] = 8249,
                            ["id"] = 10199,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Druid-Bound Ursauk",
                        },
                        [1392] = 
                        {
                            ["description"] = "When Peregrine Direnni passed her Master Conjurer test by summoning the first-ever Flame Atronach Camel, her mentor Corvus gave her high marks but was heard to comment, \"Now you're just showing off.\"",
                            ["icon"] = "/esoui/art/icons/mounticon_atronachcamel_a.dds",
                            ["furnitureId"] = 4474,
                            ["id"] = 1392,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Flame Atronach Camel",
                        },
                        [1387] = 
                        {
                            ["description"] = "Unlike their lone cousins, the great Shadowghost Wolf Mounts, the smaller Shadowghost Pack Wolves hunt on the darkest nights in howling groups. Separated from their packs, they make loyal companions.",
                            ["icon"] = "/esoui/art/icons/pet_151.dds",
                            ["furnitureId"] = 4473,
                            ["id"] = 1387,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Shadowghost Pack Wolf",
                        },
                        [1380] = 
                        {
                            ["description"] = "Originally designed for probing tiny, inaccessible areas of the Clockwork City, the mechanical Skeevaton can be set to recognize and follow an individual mortal, replicating pet behavior on the surface of Nirn.",
                            ["icon"] = "/esoui/art/icons/pat_153.dds",
                            ["furnitureId"] = 4471,
                            ["id"] = 1380,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Clockwork Skeevaton",
                        },
                        [10182] = 
                        {
                            ["description"] = "A miniature statue of Mehrunes Dagon, Daedric Prince of Destruction and Ambition.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettedagon001.dds",
                            ["furnitureId"] = 8197,
                            ["id"] = 10182,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Mehrunes Dagon",
                        },
                        [10181] = 
                        {
                            ["description"] = "A miniature statue of Saint Kaladas, builder of the Great Chapel of Zenithar in Leyawiin.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuettestkaladas001.dds",
                            ["furnitureId"] = 8196,
                            ["id"] = 10181,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Kaladas of Leyawiin",
                        },
                        [10065] = 
                        {
                            ["description"] = "Spring blossoms nod their heads as if recognizing kin in this Elf-pampered companion. Some caretakers claim these gryphons provide a sense of ease to those who care for them—and pain for those who seek their demise.",
                            ["icon"] = "/esoui/art/icons/pet_aurulungryphon.dds",
                            ["furnitureId"] = 8195,
                            ["id"] = 10065,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Aurulun Fledgling Gryphon",
                        },
                        [1147] = 
                        {
                            ["description"] = "White cats are sacred to Dibella, the Lady of Love, and all white cats are said to be her representatives in the animal kingdom. A House of Dibella will typically have three or four milk-white cats within its walls.",
                            ["icon"] = "/esoui/art/icons/pet_110.dds",
                            ["furnitureId"] = 4370,
                            ["id"] = 1147,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Milady's Cloud Cat",
                        },
                        [10061] = 
                        {
                            ["description"] = "\"The sight of this welwa's claws sparks something in my imagination, showing me different scenarios where those icy talons end my life. It's beautiful. In a horrible, gruesome way. I wonder if it can be tamed?\"—Pyn Bossard, Welwa Researcher (Deceased)",
                            ["icon"] = "/esoui/art/icons/mount_icefirewrathsteed.dds",
                            ["furnitureId"] = 8192,
                            ["id"] = 10061,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Azuredoom Wrathsteed",
                        },
                        [1145] = 
                        {
                            ["description"] = "This loyal horse has been trained for warfare, and will stick with you through every kind of conflict. As a bonus, it comes outfitted in ancient Dwarven horse armor.\n|cFFFFFF\nRiding Skill does not affect this mount's appearance.|r",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_p.dds",
                            ["furnitureId"] = 4368,
                            ["id"] = 1145,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Dwarven War Horse",
                        },
                        [1144] = 
                        {
                            ["description"] = "The Molag Amur Cliff Strider is prized by reptilian connoisseurs because its coloration, though somber, is lightened by its subtle golden tones. And if startled, its squawk will cause passersby to jump and horses to bolt.",
                            ["icon"] = "/esoui/art/icons/pet_131.dds",
                            ["furnitureId"] = 4367,
                            ["id"] = 1144,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Molag Amur Cliff Strider",
                        },
                        [1143] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Selene's Web.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranselenwebspider001.dds",
                            ["furnitureId"] = 4366,
                            ["id"] = 1143,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Selene's Web.",
                            ["name"] = "Bust: Selene",
                        },
                        [1142] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Vaults of Madness.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranfleshatronach001.dds",
                            ["furnitureId"] = 4365,
                            ["id"] = 1142,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Vaults of Madness.",
                            ["name"] = "Bust: Grothdarr",
                        },
                        [5236] = 
                        {
                            ["description"] = "Werewolf hunting is a dirty and largely thankless business, but when a Silver Dawn member mounts their resplendent Argent Charger, they feel like the hero they really are. Sure, it's showy, but as a defender of society against the vicious, you deserve it.",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_silverdawn.dds",
                            ["furnitureId"] = 5439,
                            ["id"] = 5236,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Silver Dawn Argent Charger",
                        },
                        [1139] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Sanctum Ophidia.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialmantikora001.dds",
                            ["furnitureId"] = 4362,
                            ["id"] = 1139,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Sanctum Ophidia.",
                            ["name"] = "Bust: Possessed Mantikora",
                        },
                        [9578] = 
                        {
                            ["description"] = "\"The mythic texts of discredited scholars are right, the Great Dark Ram lives! Hircine appears in this form only during Rain's Hand in the Great Forest. Soon, there will be the trials of virility. I hope my strength endures.\"—Lost Journal of Bekelva",
                            ["icon"] = "/esoui/art/icons/mount_greatdarkram.dds",
                            ["furnitureId"] = 7911,
                            ["id"] = 9578,
                            ["category"] = "Cervines",
                            ["hint"] = "",
                            ["name"] = "Great Dark Ram",
                        },
                        [9632] = 
                        {
                            ["description"] = "Trophy taken from the Magma Incarnate in honor of an Undaunted victory in the Dread Cellar.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyearthincarnate001.dds",
                            ["furnitureId"] = 8026,
                            ["id"] = 9632,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing The Dread Cellar.",
                            ["name"] = "Trophy: Magma Incarnate",
                        },
                        [9633] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Red Petal Bastion.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranartifactmaster001.dds",
                            ["furnitureId"] = 8023,
                            ["id"] = 9633,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Red Petal Bastion.",
                            ["name"] = "Bust: Prior Thierric Sarazen",
                        },
                        [9684] = 
                        {
                            ["description"] = "\"In my defense, those heroes just left pieces of that Dark Anchor lying there. All of that auxiliary magic? What if some evil cult got it? Oh, and I wanted to make a Senche … but one of the runes got smudged.\"—Interview with Frugal Jedd, Mage",
                            ["icon"] = "/esoui/art/icons/mount_wailingshacklerwolf.dds",
                            ["furnitureId"] = 7928,
                            ["id"] = 9684,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Wailing Shackler Wolf",
                        },
                        [9685] = 
                        {
                            ["description"] = "\"Meridia's charger manifests wherever vile darkness gathers. In 298 1E, it blazed out of the sunrise and into Cath Bedraud where the righteous flames of the Sunfire reduced a nest of bloodfiends to ashes.\"—Terendra Vocula, Priest of Inner Luminance",
                            ["icon"] = "/esoui/art/icons/mount_luminousmeridiancharger.dds",
                            ["furnitureId"] = 7929,
                            ["id"] = 9685,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Luminous Meridian Charger",
                        },
                        [9786] = 
                        {
                            ["description"] = "\"Why. Can't. They. Keep. Quiet? Arkay blesses them with their own cycle, but every few years they claw their way back into Greenshade. And what do they do once they get here? Scream. Constantly.\"—Hasinel, Lament of the Midyear Screech",
                            ["icon"] = "/esoui/art/icons/pet_screamingnixad.dds",
                            ["furnitureId"] = 7954,
                            ["id"] = 9786,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Screaming Midyear Nixad",
                        },
                        [9794] = 
                        {
                            ["description"] = "Legend tells of a Breton hunter who freed a Flint-Pelt Fox from a hagraven's snare. Now these creatures seek out any warrior who calls hagravens \"foe,\" often lingering around areas terrorized by their hated enemies.",
                            ["icon"] = "/esoui/art/icons/mount_grayfox.dds",
                            ["furnitureId"] = 8027,
                            ["id"] = 9794,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Flint-Pelt Fox",
                        },
                        [9795] = 
                        {
                            ["description"] = "Hay-Crown Chub Loons were revered as omens of good harvests until one winter in Rivenspire, when desperate farmers discovered that these creatures were delectable. Druids took the dim-witted, delicious birds with them when they fled to High Isle.",
                            ["icon"] = "/esoui/art/icons/pet_haycrownchubloon.dds",
                            ["furnitureId"] = 8028,
                            ["id"] = 9795,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Hay-Crown Chub Loon",
                        },
                        [9805] = 
                        {
                            ["description"] = "The people of Falkreath call these lynxes \"blizzard bringers.\" The cats are as powerful as the buffeting winds that scour the slopes of the Shriekwind Bastion. There are even rumors that the lynx's growl causes avalanches high up in the mountains.",
                            ["icon"] = "/esoui/art/icons/mount_snowfalllynx.dds",
                            ["furnitureId"] = 8055,
                            ["id"] = 9805,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Falkreath Riding-Lynx",
                        },
                        [9819] = 
                        {
                            ["description"] = "Kneel before the mighty Arox and he might just offer to crush your enemies for you! But, as a daedrat. Not his former much bigger self. After adding Arox to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/houseguest_arox.dds",
                            ["furnitureId"] = 8058,
                            ["id"] = 9819,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Arox the Mutilator",
                        },
                        [9979] = 
                        {
                            ["description"] = "After spending years expelling dro-m'Athra from Nirn, M'aar decided to follow a new path. Now they hope to explore as much of the Mundus as possible before venturing to the Gates of the Crossing.",
                            ["icon"] = "/esoui/art/icons/mount_stygiansencheraht.dds",
                            ["furnitureId"] = 8069,
                            ["id"] = 9979,
                            ["category"] = "Heavyweights",
                            ["hint"] = "",
                            ["name"] = "Midnight Cantor Senche-Raht",
                        },
                        [5846] = 
                        {
                            ["description"] = "The Hot Pepper Bantam Guar breed is native to the \"spice island\" of Esroniet, the source of much of Tamriel's nutmeg, cloves, mace, and hot peppers. And the Pepper Guar has a spicy little personality to go with its name!",
                            ["icon"] = "/esoui/art/icons/pet_236_hotpepperbantam.dds",
                            ["furnitureId"] = 5590,
                            ["id"] = 5846,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Hot Pepper Bantam Guar",
                        },
                        [5847] = 
                        {
                            ["description"] = "\"The recesses of our nightmares contain horrors that we often cannot look at. Yet we must, lest these pockets of terror fester and grow. To light your path, I present this bantam guar. Please do not squeal.\" — Overheard in a dark alley",
                            ["icon"] = "/esoui/art/icons/pet_255_twitchbantam.dds",
                            ["furnitureId"] = 5591,
                            ["id"] = 5847,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Eerie Violet Bantam Guar",
                        },
                        [5848] = 
                        {
                            ["description"] = "When asked about the rumor that the Hot-Blooded Bantam Guar had been bred as a vampiric sub-species by the disgraced mage Darvasen before he was exiled from Shad Astula, Arch-Mage Valeyn replied, \"What nonsense! They just like to eat tomatoes. Trust me.\"",
                            ["icon"] = "/esoui/art/icons/pet_250_bloodbuddybantam.dds",
                            ["furnitureId"] = 5592,
                            ["id"] = 5848,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Hot-Blooded Bantam Guar",
                        },
                        [5849] = 
                        {
                            ["description"] = "Start with a dollop of wiggly cuteness, add a dash of the Coldharbour glow, and you get a bantam guar that causes \"oohs!\" and \"ahhhs!\" wherever you go, plus helps you avoid stubbing your toe at night when you leave your bed. Genius!",
                            ["icon"] = "/esoui/art/icons/pet_251_coldharbourbantam.dds",
                            ["furnitureId"] = 5593,
                            ["id"] = 5849,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Coldharbour Bantam Guar",
                        },
                        [5850] = 
                        {
                            ["description"] = "\"A fur-less, cold-blooded reptile with icy blue eyes that comes from the frozen, far-north, and in-all-likelihood legendary continent of Atmora? Bah. I refuse to believe it.\" —Phrastus of Elinhir",
                            ["icon"] = "/esoui/art/icons/pet_237_atmoranbantam.dds",
                            ["furnitureId"] = 5594,
                            ["id"] = 5850,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Atmoran Bantam Guar",
                        },
                        [5851] = 
                        {
                            ["description"] = "It may look cute, but this volcanic little pest comes from Mehrunes Dagon's Oblivion plane of the Deadlands: it's got lava in its blood and fire in its eyes, so keep it away from the curtains.",
                            ["icon"] = "/esoui/art/icons/pet_247_deadlandbantam.dds",
                            ["furnitureId"] = 5595,
                            ["id"] = 5851,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Deadlands Bantam Guar",
                        },
                        [5852] = 
                        {
                            ["description"] = "A donkey might not be the most glamorous pack animal, but it's certainly the hardiest and most sure-footed, toting heavy loads through desert, mountains, and tundra without complaint … though it will give you a dirty look, and might nip if you turn away!",
                            ["icon"] = "/esoui/art/icons/pet_253_donkey.dds",
                            ["furnitureId"] = 5596,
                            ["id"] = 5852,
                            ["category"] = "Inventory",
                            ["hint"] = "|cffffffPurchasing this pet increases your inventory capacity by 5 slots on all characters account wide.|r",
                            ["name"] = "Explorer's Pack Donkey",
                        },
                        [5853] = 
                        {
                            ["description"] = "According to Nord legend, in its native land of Atmora this Chub Loon is much larger, as tall as two warriors and with a squawk that starts avalanches. It took mighty Ysgramor a day and a night to wrestle one down from Shivering Glacier. What, you doubt?",
                            ["icon"] = "/esoui/art/icons/pet_240_atmoranchubloon.dds",
                            ["furnitureId"] = 5597,
                            ["id"] = 5853,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Atmoran Chub Loon",
                        },
                        [5854] = 
                        {
                            ["description"] = "Stolid, careful, sturdy, and long-suffering, the Treasure Hunter's Horse is resigned to a life of being ridden into crumbling ruins by a reckless master who's searching for wealth but often finds only danger.",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_treasurehunter.dds",
                            ["furnitureId"] = 5598,
                            ["id"] = 5854,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Treasure Hunter's Horse",
                        },
                        [5855] = 
                        {
                            ["description"] = "North of Windhelm in Skyrim, where the snow on the heights never melts, the Nords' great Wolfhounds have lighter and fluffier fur coats. In addition to barking, they even howl a bit like the wolves they pursue.",
                            ["icon"] = "/esoui/art/icons/pet_254_winterholdwolfhound.dds",
                            ["furnitureId"] = 5599,
                            ["id"] = 5855,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Winterhold Wolfhound",
                        },
                        [5856] = 
                        {
                            ["description"] = "One might think that being frozen in a glacier for several thousand years would damage a delicate mechanism like a Dwarven Spider, but in the case of the Icebound units it seems instead to have preserved them in perfect working order.",
                            ["icon"] = "/esoui/art/icons/pet_257_dwarvenice.dds",
                            ["furnitureId"] = 5600,
                            ["id"] = 5856,
                            ["category"] = "Exotic",
                            ["hint"] = "Awarded for completing the \"Frostvault Conqueror\" Achievement.",
                            ["name"] = "Icebound Dwarven Spider",
                        },
                        [5857] = 
                        {
                            ["description"] = "\"The forces of Nocturnal's attempted invasion of the Colored Rooms were inadvertently accompanied by some Evergloam Daedrats, which afterward were rounded up, Lustrated for purification, and then banished to Nirn.\" —Sapiarch Galaadil",
                            ["icon"] = "/esoui/art/icons/pet_239_purifieddaedrat.dds",
                            ["furnitureId"] = 5601,
                            ["id"] = 5857,
                            ["category"] = "Daedric",
                            ["hint"] = "",
                            ["name"] = "Lustrated Daedrat",
                        },
                        [5858] = 
                        {
                            ["description"] = "According to the notebooks of Corvus Direnni, the frost senche-panther may actually be a form of atronach summoned from a plane known as the Fourth Sinus of Takubar. Why it remains in Tamriel where it willingly submits to the orders of mortals is unknown.",
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_apexsenche.dds",
                            ["furnitureId"] = 5602,
                            ["id"] = 5858,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Dragonscale Frost Senche",
                        },
                        [5859] = 
                        {
                            ["description"] = "\"I have been fortunate enough to have personally glimpsed a Solar Horse on an Anequine morning, and I say with conviction that it must be a creature of Magrus, the Cat's Eye, and no other.\" —Moon-Bishop Hunal",
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_apexhorse.dds",
                            ["furnitureId"] = 5603,
                            ["id"] = 5859,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Dragonscale Solar Horse",
                        },
                        [9837] = 
                        {
                            ["description"] = "\"Boredom. Boredom and that accursed holiday in Stonefalls. That's why I used my considerable skills to merge a salamander and a guar. Hmm. The colors are striking. It was just a whim, but I'm pleased with the results.\"—Irastimil Direnni, Creature Creator",
                            ["icon"] = "/esoui/art/icons/mount_salamandrineguar.dds",
                            ["furnitureId"] = 8062,
                            ["id"] = 9837,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Salamandrine Guar",
                        },
                        [5861] = 
                        {
                            ["description"] = "\"Our Lady of the Infinite Energies, Strict but Fair Arbiter of Inner Luminance, grant unto thy most devoted worshiper a sign of thy radiant favor, mayhap a loveable, glowing Sabre Cat cub.\" —Sayings of Valasha",
                            ["icon"] = "/esoui/art/icons/pet_244_purifiedsenchecub.dds",
                            ["furnitureId"] = 5605,
                            ["id"] = 5861,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Meridian Sabre Cub",
                        },
                        [5862] = 
                        {
                            ["description"] = "Tired of pets that follow you everywhere? Fed up with feeding them? Step up to Pebble Pal, the pet that's a … rock.",
                            ["icon"] = "/esoui/art/icons/pet_258_pebblepal.dds",
                            ["furnitureId"] = 5606,
                            ["id"] = 5862,
                            ["category"] = "Exotic",
                            ["hint"] = "|cff0000This pet cannot path when placed as a furnishing.|r",
                            ["name"] = "Pebble Pal",
                        },
                        [5863] = 
                        {
                            ["description"] = "Pining for a perfect pet? Perhaps you're a person who'd prefer a pleasantly playful piglet, pearly-white, pretty, and partial to paladins and protectors!",
                            ["icon"] = "/esoui/art/icons/pet_238_pinkpig.dds",
                            ["furnitureId"] = 5607,
                            ["id"] = 5863,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Pink Pearl Pig",
                        },
                        [5864] = 
                        {
                            ["description"] = "The Dwarven Theodolite was a sort of automated measuring device designed to explore and survey subterranean areas; this version is notable for its distinctive red \"eye.\"",
                            ["icon"] = "/esoui/art/icons/pet_248_redtheodolite.dds",
                            ["furnitureId"] = 5608,
                            ["id"] = 5864,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Carnelian Theodolite",
                        },
                        [5865] = 
                        {
                            ["description"] = "\"I would speculate that the Storm Wolf is the result of an experiment by a powerful Destruction mage in which a wild canine was subjected to prolonged exposure to a Meip Glyph of Shock.\" —Gabrielle Benele, Wizard",
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_apexwolf.dds",
                            ["furnitureId"] = 5609,
                            ["id"] = 5865,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Dragonscale Storm Wolf",
                        },
                        [5866] = 
                        {
                            ["description"] = "The rare Sweetroll Grizzly Bears prowl the golden forests of the Rift on the northern slopes of the Jerall Mountains. They're big strong cuddly hug machines—except when they're angry.",
                            ["icon"] = "/esoui/art/icons/mounticon_bear_sweetroll.dds",
                            ["furnitureId"] = 5610,
                            ["id"] = 5866,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Sweetroll Grizzly",
                        },
                        [5867] = 
                        {
                            ["description"] = "Deep in the shadows of the Tenmar Forest, hidden by its camouflaged coat and stealthy stalking, the Senche-Tiger is a nearly invisible jungle predator. Even as a mount, it retains something of the air of mystery it wears in the wild.",
                            ["icon"] = "/esoui/art/icons/mounticon_senche_tenmartiger.dds",
                            ["furnitureId"] = 5611,
                            ["id"] = 5867,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Tenmar Senche-Tiger",
                        },
                        [5868] = 
                        {
                            ["description"] = "Though in coloration the Glenumbra Border Wolf resembles certain Breton dog breeds, this sturdy and stoic mount is no dog, and will carry a High Rock courier for leagues through dark night and heavy weather.",
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_glennumbra.dds",
                            ["furnitureId"] = 5612,
                            ["id"] = 5868,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Glenumbra Border Wolf",
                        },
                        [5869] = 
                        {
                            ["description"] = "\"Some accounts of Meridia's plane of the Colored Rooms describe a menagerie of light-imbued spectral beasts elevated from Nirn and 'purified' by the Lady's holy light.\" —Sayings of Valasha",
                            ["icon"] = "/esoui/art/icons/mounticon_senche_purified.dds",
                            ["furnitureId"] = 5613,
                            ["id"] = 5869,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Meridian Sabre Cat",
                        },
                        [5870] = 
                        {
                            ["description"] = "During the Jester's Festival even the lowliest of commoners can pretend to be a mounted knight with a whimsical Novelty Stick steed. Horses are popular in the Daggerfall Covenant.",
                            ["icon"] = "/esoui/art/icons/mounticon_stick_horse.dds",
                            ["furnitureId"] = 5614,
                            ["id"] = 5870,
                            ["category"] = "Toys",
                            ["hint"] = "|cff0000This mount doesn't increase your movement speed. Riding Lessons don't affect its appearance. This mount cannot path when placed as a furnishing.|r",
                            ["name"] = "Novelty Stick Horse",
                        },
                        [5871] = 
                        {
                            ["description"] = "Shorn Camels are desert mounts with elaborate Tattoos on their hide where once there were wiry bristles. The \"Verdant,\" with its repeating floral designs, may be the most beautiful of them all.",
                            ["icon"] = "/esoui/art/icons/mounticon_camel_verdantshorn.dds",
                            ["furnitureId"] = 5615,
                            ["id"] = 5871,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Verdant Tattoo Shorn Camel",
                        },
                        [5872] = 
                        {
                            ["description"] = "Frankly, compared to war horses, bear mounts, and even saddle guars, it's hard for Camels to look magnificent—until you dress them in Dragonscale Bard. Then look out!",
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_camel.dds",
                            ["furnitureId"] = 5616,
                            ["id"] = 5872,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Dragonscale Barded Camel",
                        },
                        [5873] = 
                        {
                            ["description"] = "\"This one doesn't sell many Guars here at the Riverhold Stables because Khajiit are folk who value their natural dignity and prefer not to ride so silly a beast. But a Guar in Dragonscale Bard is a thing of beauty!\" — Master Groom Zarbi'dahuz",
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_guar.dds",
                            ["furnitureId"] = 5617,
                            ["id"] = 5873,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Dragonscale Barded Guar",
                        },
                        [5874] = 
                        {
                            ["description"] = "\"Our distant cousins, the senche-mounts, look so majestic in Dragonscale Bard, like creatures who've just stepped out of an ancient wall-frieze in Dune. Perhaps these pesky Dragons have a use after all, yes?\" — Master Groom Zarbi'dahuz",
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_senche.dds",
                            ["furnitureId"] = 5618,
                            ["id"] = 5874,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Dragonscale Barded Senche",
                        },
                        [5875] = 
                        {
                            ["description"] = "\"I had always thought the Helkarn Wolf to be Elsweyr's finest Wolf mount, but that was before I saw a cavalry Wolf in Dragonscale Bard. Could a mount look any more martial?\" — Master Groom Zarbi'dahuz",
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_wolf.dds",
                            ["furnitureId"] = 5619,
                            ["id"] = 5875,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Dragonscale Barded Wolf",
                        },
                        [5876] = 
                        {
                            ["description"] = "Dragonscale bard is just about the heaviest armor one can put on a mount, but bears bred as mounts are so strong they scarcely seem to notice it.",
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_bear.dds",
                            ["furnitureId"] = 5620,
                            ["id"] = 5876,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Dragonscale Barded Bear",
                        },
                        [5877] = 
                        {
                            ["description"] = "\"Dragons are a pain in the tailbones, yes? But their scales make such superb steed armor! The Dragonscale Barded War-Horse may be the sharpest mount this one has ever seen!\" — Master Groom Zarbi'dahuz",
                            ["icon"] = "/esoui/art/icons/mounticon_dragonscale_horse.dds",
                            ["furnitureId"] = 5621,
                            ["id"] = 5877,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Dragonscale Barded War-Horse",
                        },
                        [5878] = 
                        {
                            ["description"] = "The Daggerfall Dapple is a hardy horse breed that comes from the Farwatch region of Glenumbra between Daggerfall and Camlorn. Known for its endurance, it's a favorite of long-distance riders.",
                            ["icon"] = "/esoui/art/icons/mounticon_horse_speckled.dds",
                            ["furnitureId"] = 5622,
                            ["id"] = 5878,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Daggerfall Dapple Horse",
                        },
                        [5879] = 
                        {
                            ["description"] = "During the Jester's Festival even the lowliest of commoners can pretend to be a mounted knight with a whimsical Novelty Stick steed. Guars are popular in the Aldmeri Dominion.",
                            ["icon"] = "/esoui/art/icons/mounticon_stick_guar.dds",
                            ["furnitureId"] = 5623,
                            ["id"] = 5879,
                            ["category"] = "Toys",
                            ["hint"] = "|cff0000This mount doesn't increase your movement speed. Riding Lessons don't affect its appearance. This mount cannot path when placed as a furnishing.|r",
                            ["name"] = "Novelty Stick Guar",
                        },
                        [5880] = 
                        {
                            ["description"] = "During the Jester's Festival even the lowliest of commoners can pretend to be a mounted knight with a whimsical Novelty Stick steed. Dragons are popular in the Ebonheart Pact.",
                            ["icon"] = "/esoui/art/icons/mounticon_stick_dragon.dds",
                            ["furnitureId"] = 5624,
                            ["id"] = 5880,
                            ["category"] = "Toys",
                            ["hint"] = "|cff0000This mount doesn't increase your movement speed. Riding Lessons don't affect its appearance. This mount cannot path when placed as a furnishing.|r",
                            ["name"] = "Novelty Stick Dragon",
                        },
                        [9977] = 
                        {
                            ["description"] = "Feeling festive? Let this little firepot spider follow you around! With its adorable alchemical light show, you're bound to brighten up anyone's day—including your own!",
                            ["icon"] = "/esoui/art/icons/pet_aurorafirepotspider.dds",
                            ["furnitureId"] = 8067,
                            ["id"] = 9977,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Aurora Firepot Spider",
                        },
                        [9978] = 
                        {
                            ["description"] = "\"To my chagrin, thieves stole my current batch of pony guars! I'd hoped to gift some to my cousin, who adored my salamandrine guar and whose love of pony guars knows no bounds. Those thieves had better watch out.\"—Irastimil Direnni, Creature Creator",
                            ["icon"] = "/esoui/art/icons/pet_salamanderponyguar.dds",
                            ["furnitureId"] = 8068,
                            ["id"] = 9978,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Salamandrine Pony Guar",
                        },
                        [7931] = 
                        {
                            ["description"] = "Don't let Biro-dar's appearance deceive you! He's not your average scholar. In fact, he makes for an entertaining and trouble-prone guest. After adding Biro-dar to your home, you can set him on a path, plus you and your visitors can speak with him.",
                            ["icon"] = "/esoui/art/icons/assistant_birodar.dds",
                            ["furnitureId"] = 6742,
                            ["id"] = 7931,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Biro-dar",
                        },
                        [9980] = 
                        {
                            ["description"] = "While they often disagree on theology, the Orsinium Orcs are unified by their love of this echatere's coat. Some call it a blessing from Trinimac. Others call it an outcast's brand from Malacath. Either way, this beast is a bundle of skittering joy.",
                            ["icon"] = "/esoui/art/icons/pet_spottedechalette.dds",
                            ["furnitureId"] = 8070,
                            ["id"] = 9980,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Tortoiseshell Echatere",
                        },
                        [9981] = 
                        {
                            ["description"] = "Driven to madness by the erratic magic around the Spellscar, these kagouti make surprisingly excellent pets. In comparison to their lucid and more aggressive kin, an insane kagouti is docile and picks up commands with ease.",
                            ["icon"] = "/esoui/art/icons/mount_spellscarkagouti.dds",
                            ["furnitureId"] = 8071,
                            ["id"] = 9981,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Spellscar Kagouti",
                        },
                        [9982] = 
                        {
                            ["description"] = "\"Some believe these skeletal senche respond to the call of a lost soul seeking safe passage. I firmly believe Y'ffre's hand is involved, and I pray I can prove it one day.\"—Druid Phillic",
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntsenche.dds",
                            ["furnitureId"] = 8072,
                            ["id"] = 9982,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Wraithtide Senche",
                        },
                        [9983] = 
                        {
                            ["description"] = "\"The day a Stonelore druid thundered in on this frightful sea-birthed horse, well … let's just say I'm glad I recognized Druid Dolvasie on top. Her ferocious expression will haunt my nightmares—as will this steed.\"—Squire Hareld, Oaken Order",
                            ["icon"] = "/esoui/art/icons/mount_wraithhaunthorse.dds",
                            ["furnitureId"] = 8073,
                            ["id"] = 9983,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Wraithtide Horse",
                        },
                        [9984] = 
                        {
                            ["description"] = "\"The ghost of Ol' Brineburr herds glowing guar down trade roads, seeking buyers. Don't be put off by their appearance. Or, hmmm, maybe seeing your steed's skeleton is a bonus to you? Regardless, get one.\"—Initiate Rogeric",
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntguar.dds",
                            ["furnitureId"] = 8074,
                            ["id"] = 9984,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Wraithtide Guar",
                        },
                        [9985] = 
                        {
                            ["description"] = "\"Where mages born from water gather, they enact ancient rites. Together they bind the essence of bear and sea and death, forming it into a mount one of their number may ride. Or so the tales go.\"—Druid Sandire",
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntbear.dds",
                            ["furnitureId"] = 8075,
                            ["id"] = 9985,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Wraithtide Bear",
                        },
                        [9986] = 
                        {
                            ["description"] = "\"Communing with the Evergrowth is sometimes confusing. I saw the waters birth an unusual wolf pack, flowing like the angry waves that gave them life. Experience proves they possess the same loyalty other wolves have toward their riders.\"—Druid Anotille",
                            ["icon"] = "/esoui/art/icons/mount_wraithhauntwolf.dds",
                            ["furnitureId"] = 8076,
                            ["id"] = 9986,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Wraithtide Wolf",
                        },
                        [9683] = 
                        {
                            ["description"] = "\"A whole bear? You grew a whole bear? Well? What are you doing with it still? Get out there! Burn a fort to the ground! Make it hit some rocks with its paws! Bask in bear-y devastation!\"—Glooredel, Vinedusk Ranger",
                            ["icon"] = "/esoui/art/icons/mount_vineduskbear.dds",
                            ["furnitureId"] = 7927,
                            ["id"] = 9683,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Wealdspirit Bear",
                        },
                        [9678] = 
                        {
                            ["description"] = "The crypts of High Isle are littered with walking suits of armor. Those who survive say that the armor protects treasures of old. But I suspect they haunt the black hallways, waiting for the dead to wake.\"—Grod, Castle Navire Crypt Keeper",
                            ["icon"] = "/esoui/art/icons/mount_soulrazerguar.dds",
                            ["furnitureId"] = 7924,
                            ["id"] = 9678,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Soulrazer Guar",
                        },
                        [9677] = 
                        {
                            ["description"] = "\"We know that a crazed necromancer forged these creatures with his dying breath. They are unrelenting, and never stop even when the Ritemaster commands them. Inexplicably, some of the bears sit calmly at the feet of the apprentices.\"—Yrssin, Psijic Order",
                            ["icon"] = "/esoui/art/icons/mount_soulrazerbear.dds",
                            ["furnitureId"] = 7923,
                            ["id"] = 9677,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Soulrazer Bear",
                        },
                        [9676] = 
                        {
                            ["description"] = "Plates of armor hover around the nonexistent fur of a blue senche. It makes no noise—does not growl or roar with the thrill of the chase. It creeps across the ground slowly, knowing that no prey can escape once the hunt has begun.",
                            ["icon"] = "/esoui/art/icons/mount_soulrazersenche.dds",
                            ["furnitureId"] = 7922,
                            ["id"] = 9676,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Soulrazer Senche",
                        },
                        [9645] = 
                        {
                            ["description"] = "Cey-Tarn Keep dog-handlers made armor training wolf pups a priority after older members of the pack gnawed their plate-harnesses to pieces. The practice lives on in this pup who proudly displays his Elven panoply as he trots beside his owner.",
                            ["icon"] = "/esoui/art/icons/pet_glassworkwolfcub.dds",
                            ["furnitureId"] = 7918,
                            ["id"] = 9645,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Meadowglass Wolf Pup",
                        },
                        [9643] = 
                        {
                            ["description"] = "Bred for their lithe frame and large eyes, these senches excel at tracking prey through the dark underbrush of Balfiera. The Direnni Hegemony fell, but their senches prowl on, hunting during the night and sharpening their claws during the day.",
                            ["icon"] = "/esoui/art/icons/pet_balfierasenchecub.dds",
                            ["furnitureId"] = 7917,
                            ["id"] = 9643,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Balfiera Senche Cub",
                        },
                        [9640] = 
                        {
                            ["description"] = "Template Description",
                            ["icon"] = "/esoui/art/icons/icon_missing.dds",
                            ["furnitureId"] = 7916,
                            ["id"] = 9640,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Infernium",
                        },
                        [9639] = 
                        {
                            ["description"] = "No one knows how these beasts found their way into Blackreach, but it didn't take long for them to heed the Dark Heart's call. Drenched in the void's corruption, this mount will chill your enemies to the bone.",
                            ["icon"] = "/esoui/art/icons/mount_voideaterdurzog.dds",
                            ["furnitureId"] = 7915,
                            ["id"] = 9639,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Voideater Durzog",
                        },
                        [9636] = 
                        {
                            ["description"] = "Tainted by proximity to active harrowstorms, these bears have become hexed abominations—perfect for warriors with cold blood and dark intentions.",
                            ["icon"] = "/esoui/art/icons/mount_stormspawnseeker.dds",
                            ["furnitureId"] = 7913,
                            ["id"] = 9636,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Harrowstorm Bear",
                        },
                        [9635] = 
                        {
                            ["description"] = "Alchemists in Cey-Tarn Keep fashion mount armor out of specially treated Culanda stones. No alchemist will say exactly what properties the resulting meadowglass has, but scouts riding meadowglass armored wolves have yet to be captured.",
                            ["icon"] = "/esoui/art/icons/mount_glassworkwolf.dds",
                            ["furnitureId"] = 7912,
                            ["id"] = 9635,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Meadowglass Wolf",
                        },
                        [9997] = 
                        {
                            ["description"] = "\"Respect the dovah-fly. They are the spirits of the ancestors given new life. They brighten the quiet tranquility of ponds and streams. What better afterlife is there?\"—Druid Henneque Blakeley",
                            ["icon"] = "/esoui/art/icons/pet_glimmergreendovafly.dds",
                            ["furnitureId"] = 8077,
                            ["id"] = 9997,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Glimmergreen Dovah-Fly",
                        },
                        [9998] = 
                        {
                            ["description"] = "Shimmering like fire, these dovah-flies dart around port cities, eating many of the nuisance insects that pester transported livestock. Recently, merchants started training and selling them to help others with insect issues.",
                            ["icon"] = "/esoui/art/icons/pet_yoltoordovafly.dds",
                            ["furnitureId"] = 8078,
                            ["id"] = 9998,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Yoltoor Dovah-Fly",
                        },
                        [9999] = 
                        {
                            ["description"] = "You can place this station in multiple homes, where it allows you and your guests to save and equip Armory builds.",
                            ["icon"] = "/esoui/art/icons/housing_gen_crf_armorycraftingbase001.dds",
                            ["furnitureId"] = 8079,
                            ["id"] = 9999,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Armory Station",
                        },
                        [9577] = 
                        {
                            ["description"] = "The cat's eyes seem to speak, saying, \"Jolly good to see you! We appear to have a small blight of rodents. Dreadful crawling things. Scuttling everywhere. Hmm, skittering blights. I knew a good joke about that. What? Oh, yes. Lovely day for a hunt!\"",
                            ["icon"] = "/esoui/art/icons/pet_catwell.dds",
                            ["furnitureId"] = 7910,
                            ["id"] = 9577,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Catwell",
                        },
                        [9576] = 
                        {
                            ["description"] = "Ride in style with a close friend or partner on this sturdy Skyrim-bred draft horse! With its pillion saddle crafted from genuine horker leather, this horse possesses strength to take two riders without breaking a sweat.",
                            ["icon"] = "/esoui/art/icons/mount_pillionhorse.dds",
                            ["furnitureId"] = 7909,
                            ["id"] = 9576,
                            ["category"] = "Multi-Rider",
                            ["hint"] = "|cFFFFFF|t32:32:EsoUI/Art/Tutorial/radialIcon_joinMount_over.dds|t Multi-Rider Mount (1 Driver, 1 Passenger)|r|",
                            ["name"] = "Grand Pillion Draft Horse",
                        },
                        [9575] = 
                        {
                            ["description"] = "\"Do these coral spiders simply mimic Dwarven spiders or did coral grow over a discarded animunculus? I haven't pried one open to find out—they really don't like that, so don't even try.\"—Wheezing Wilren",
                            ["icon"] = "/esoui/art/icons/mount_coralcrawler.dds",
                            ["furnitureId"] = 7908,
                            ["id"] = 9575,
                            ["category"] = "Constructs",
                            ["hint"] = "",
                            ["name"] = "Coral Crawler Dwarven Spider",
                        },
                        [9574] = 
                        {
                            ["description"] = "\"Like Spriggans roam the glades on land, so does this creature prowl around the tidepools. Its gnarled wooden bones sprout with aquatic life. If it sees me, I'm sure it'll tear my throat out.\"—Scrap from the lost journal of Teldh",
                            ["icon"] = "/esoui/art/icons/mount_seaorchardsenche.dds",
                            ["furnitureId"] = 7907,
                            ["id"] = 9574,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Cat O' War Senche Lion",
                        },
                        [9573] = 
                        {
                            ["description"] = "As swift as the waves at high tide, this steed's gallop is unmatched. With its glowing mane and shining tail, night riding on this Surfglow Courser is the most sublime experiences known to equestrians.",
                            ["icon"] = "/esoui/art/icons/mount_surfglowcourser.dds",
                            ["furnitureId"] = 7906,
                            ["id"] = 9573,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Surfglow Courser",
                        },
                        [9572] = 
                        {
                            ["description"] = "Though still feared by those traveling to and from Amenos, the ornaug packs native to local waters can serve as loyal steeds if tamed and trained. Or so say the prisoners dreaming of freedom on that prison isle.",
                            ["icon"] = "/esoui/art/icons/mount_amenosseabeast.dds",
                            ["furnitureId"] = 7905,
                            ["id"] = 9572,
                            ["category"] = "Serpentes",
                            ["hint"] = "",
                            ["name"] = "Amenos Ornaug",
                        },
                        [12054] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Oathsworn Pit.",
