                        [12056] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Bedlam Veil.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantheblind001.dds",
                            ["furnitureId"] = 9623,
                            ["id"] = 12056,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Bedlam Veil.",
                            ["name"] = "Bust: The Blind",
                        },
                        [12057] = 
                        {
                            ["description"] = "Trophy taken from the Blind in honor of an Undaunted victory in Bedlam Veil.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophytheblind001.dds",
                            ["furnitureId"] = 9624,
                            ["id"] = 12057,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Bedlam Veil.",
                            ["name"] = "Trophy: The Blind",
                        },
                        [12058] = 
                        {
                            ["description"] = "\"Hold your grudges well. Keep them close to your heart. Let them punctuate every blow you make as you fulfill upon your promise of vengeance. And display this statue in your dwelling so that all may know the cost of crossing you.\"—Lucky Lashgikh",
                            ["icon"] = "/esoui/art/icons/housing_vrd_inc_housingstatuemalacath003.dds",
                            ["furnitureId"] = 9675,
                            ["id"] = 12058,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Malacath, Furious One",
                        },
                        [12059] = 
                        {
                            ["description"] = "Discipline and resolution. Protection and honor. These traits and more embody the spirit of the Imperial warrior. Display these noble qualities in this artful statuette!",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_statuetteimperialmedium001.dds",
                            ["furnitureId"] = 9676,
                            ["id"] = 12059,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Statuette: Imperial Warrior",
                        },
                        [12060] = 
                        {
                            ["description"] = "\"Those whom Hermaeus Mora calls to the Infinite Archive may serve him—or may choose to leave. But who, upon understanding the limitless knowledge they may access, dares refuse the Lord of Secrets without feeling bereft forever after?\"—Mage Allierwen",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_housingpaintingu41endlessarchive001.dds",
                            ["furnitureId"] = 9677,
                            ["id"] = 12060,
                            ["category"] = "General",
                            ["hint"] = "",
                            ["name"] = "Painting: Infinite Archive",
                        },
                        [12061] = 
                        {
                            ["description"] = "Like the Warrior-Poet himself, this striking butterfly is bisected by two distinct color palettes. The Tribunal's faithful consider it a good omen to see one of these creatures, and a blessing from Lord Vivec himself if one chooses to follow you.",
                            ["icon"] = "/esoui/art/icons/pet_vivecspromisebutterfly.dds",
                            ["furnitureId"] = 9678,
                            ["id"] = 12061,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Vivec's Promise Butterfly",
                        },
                        [12062] = 
                        {
                            ["description"] = "These cats of Skyrim are used to harsh conditions with little respite. As a result, they're quite hardy, known for their large size and thick, gorgeous fur. They're prized by local villages for their mousing abilities and teeth-rattling purrs.",
                            ["icon"] = "/esoui/art/icons/pet_keizaalalpinecat.dds",
                            ["furnitureId"] = 9679,
                            ["id"] = 12062,
                            ["category"] = "Domestic",
                            ["hint"] = "",
                            ["name"] = "Majestic Alpine Cat",
                        },
                        [9515] = 
                        {
                            ["description"] = "Senches are opinionated creatures, but ones imbued with the confidence of the stars are infinitely more judgmental than their Nirn-born counterparts. Riding one of these across Tamriel is a clear sign that even the stars heed your power.",
                            ["icon"] = "/esoui/art/icons/mount_celestialsenche.dds",
                            ["furnitureId"] = 7863,
                            ["id"] = 9515,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Star-Born Guardian Senche",
                        },
                        [9512] = 
                        {
                            ["description"] = "All Star-Born horses are children of the Steed. Impatient and in a rush, these creatures are difficult to tame. Any time spent earning their trust is always recovered the second they're allowed to canter down an open road.",
                            ["icon"] = "/esoui/art/icons/mount_celestialhorse.dds",
                            ["furnitureId"] = 7860,
                            ["id"] = 9512,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Star-Born Guardian Horse",
                        },
                        [9466] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Rockgrove.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialrockgrove001.dds",
                            ["furnitureId"] = 7855,
                            ["id"] = 9466,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Rockgrove.",
                            ["name"] = "Bust: Xalvakka",
                        },
                        [9465] = 
                        {
                            ["description"] = "Trophy taken from Xalvakka in honor of an Undaunted victory in Rockgrove.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_mountedtrophyrockgrove001.dds",
                            ["furnitureId"] = 7854,
                            ["id"] = 9465,
                            ["category"] = "Undaunted Trophies",
                            ["hint"] = "Awarded for completing Rockgrove.",
                            ["name"] = "Trophy: Xalvakka",
                        },
                        [9464] = 
                        {
                            ["description"] = "\"You'll find few wild guars wandering Abecean shores, but these coral beasts dance in the shallows nonetheless. Wherever they came from, they still exhibit the tamed guars' playful disposition.\"—Saissula, Stablemaster",
                            ["icon"] = "/esoui/art/icons/mount_coraldriftguar.dds",
                            ["furnitureId"] = 7853,
                            ["id"] = 9464,
                            ["category"] = "Bipedals",
                            ["hint"] = "",
                            ["name"] = "Reefborn Guar",
                        },
                        [9463] = 
                        {
                            ["description"] = "\"If you visit Abecean islands, you need to be ready to handle reefborn creatures. The bears, for example, do bear things. Mostly. But watch them near saltwater—they'll roll in it whether you're on them or not.\"—Saissula, Stablemaster",
                            ["icon"] = "/esoui/art/icons/mount_coraldriftbear.dds",
                            ["furnitureId"] = 7852,
                            ["id"] = 9463,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Reefborn Bear",
                        },
                        [9462] = 
                        {
                            ["description"] = "Foolhardy warriors travel into the charred Deadlands forests to face off against the ursine horrors that reside there. Lucky adventurers return to their homelands alive, but forever haunted by the sound of red-hot claws digging into ashen dirt.",
                            ["icon"] = "/esoui/art/icons/mount_nightmarebear.dds",
                            ["furnitureId"] = 7851,
                            ["id"] = 9462,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Nightmare Bear",
                        },
                        [9461] = 
                        {
                            ["description"] = "\"Mages Guild scholars think someone creates these types of senches. With what magic, I don't know. Maybe some sea-loving druid? Regardless, they're as fierce as you'd expect for a senche mount.\"—Saissula, Stablemaster",
                            ["icon"] = "/esoui/art/icons/mount_coraldriftsenche.dds",
                            ["furnitureId"] = 7850,
                            ["id"] = 9461,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Reefborn Senche-Lion",
                        },
                        [9460] = 
                        {
                            ["description"] = "\"Those who love wolves may find this breed boosts their prestige in some Abecean coastal areas, especially among the druid folk. While you need stern discipline to train this one to saddle, you gain a lifelong adventuring partner.\"—Saissula, Stablemaster",
                            ["icon"] = "/esoui/art/icons/mount_coraldriftwolf.dds",
                            ["furnitureId"] = 7849,
                            ["id"] = 9460,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Reefborn Wolf",
                        },
                        [9459] = 
                        {
                            ["description"] = "\"The hues on these reefborn steeds—wondrous, yes? Instead of flowing manes on these so-called equines, colorful coral grew. Just don't try to feed them apples. They prefer to feed on algal blooms.\"—Saissula, Stablemaster",
                            ["icon"] = "/esoui/art/icons/mount_coraldrifthorse.dds",
                            ["furnitureId"] = 7848,
                            ["id"] = 9459,
                            ["category"] = "Equines",
                            ["hint"] = "",
                            ["name"] = "Reefborn Charger",
                        },
                        [1140] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Aetherian Archive.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialstoneatronach001.dds",
                            ["furnitureId"] = 4363,
                            ["id"] = 1140,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Aetherian Archive.",
                            ["name"] = "Bust: Foundation Stone Atronach",
                        },
                        [5930] = 
                        {
                            ["description"] = "This meticulous reproduction of the ancient Argonian calendar may not have the storied history of the original, but is a masterpiece of stonework in its own right.",
                            ["icon"] = "/esoui/art/icons/housing_arg_run_floorcalendar001.dds",
                            ["furnitureId"] = 5801,
                            ["id"] = 5930,
                            ["category"] = "General",
                            ["hint"] = "Awarded for bringing all twelve tablets of the Xinchei-Konu to Jekka-Wass Vozei at the Xinchei-Konu Monument northeast of Lilmoth.",
                            ["name"] = "Replica of the Xinchei-Konu",
                        },
                        [9451] = 
                        {
                            ["description"] = "Known for its brilliant yellow hues, this moth flits through the deciduous fall forests of Cyrodiil almost unseen. Each year, some fly beyond the Heartland's borders in all directions, as if trying to escape the war-torn province.",
                            ["icon"] = "/esoui/art/icons/pet_sungoldmoth.dds",
                            ["furnitureId"] = 7846,
                            ["id"] = 9451,
                            ["category"] = "Flying Pets",
                            ["hint"] = "",
                            ["name"] = "Mustardseed Moth",
                        },
                        [9450] = 
                        {
                            ["description"] = "\"Now, surely the presence of this creature is enough to dissuade those pompous academics from believing magic created the first Vvardvark. Who would create a creature so listless that moss grows on it?\"—Atmore, Vvardenfell Zoological Field Commission",
                            ["icon"] = "/esoui/art/icons/pet_mossyvvardvark.dds",
                            ["furnitureId"] = 7845,
                            ["id"] = 9450,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Mossy Vvardvark",
                        },
                        [5172] = 
                        {
                            ["description"] = "When a cub, the young Atmoran Snow Bear is a lap-clambering cuddle bug, a friendly fuzzball whose demeanor is completely at odds with the fierce reputation of adult Snow Bears. Enjoy them while they're still small!",
                            ["icon"] = "/esoui/art/icons/pet_189_atmoranbearcub.dds",
                            ["furnitureId"] = 5447,
                            ["id"] = 5172,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Atmoran Snow Bear Cub",
                        },
                        [5173] = 
                        {
                            ["description"] = "These fiercely noble Snow Bears are said to have been brought from the legendary frozen continent of Atmora by mighty Ysgramor himself, who deemed them the only worthy avatars of the ancient Nord Bear totem.",
                            ["icon"] = "/esoui/art/icons/mounticon_bear_atmoransnow.dds",
                            ["furnitureId"] = 5556,
                            ["id"] = 5173,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Atmoran Snow Bear",
                        },
                        [5179] = 
                        {
                            ["description"] = "Though Dwarven Metal was usually employed in building Spider constructs, for reasons unknown some rare variants were built with a darker Ebon Steel alloy. When found in working order, these automata are prized by collectors.",
                            ["icon"] = "/esoui/art/icons/mounticon_dwarven_spider_ebonyyellow.dds",
                            ["furnitureId"] = 5519,
                            ["id"] = 5179,
                            ["category"] = "Constructs",
                            ["hint"] = "",
                            ["name"] = "Ebon Steel Dwarven Spider",
                        },
                        [5180] = 
                        {
                            ["description"] = "This extremely rare Dwarven Spider model is surmounted with a double golden crescent, interpreted by scholars of the Dwemer as a \"Solar Arc,\" or tribute to the sun—an iconography otherwise completely unknown among the handiworks of the Deep Elves.",
                            ["icon"] = "/esoui/art/icons/pet_200_dwarven-ebonyyellow.dds",
                            ["furnitureId"] = 5509,
                            ["id"] = 5180,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Solar Arc Dwarven Spider",
                        },
                        [9446] = 
                        {
                            ["description"] = "Several theories circulate on the nature of the torchnix's light. Some scholars suggest the luminescence is a mating display, while others argue that it's a form of communication. Children in Ahemmusa tell each other the glow is bad food in the nix's gut.",
                            ["icon"] = "/esoui/art/icons/mount_greentorchnix.dds",
                            ["furnitureId"] = 7842,
                            ["id"] = 9446,
                            ["category"] = "Arthropods",
                            ["hint"] = "",
                            ["name"] = "Summer's Herald Torchnix",
                        },
                        [9445] = 
                        {
                            ["description"] = "\"Long ago, during the annual Ket Keptu hunt, Tula the Skullcleaver and their bear Falk rose above the others in the amount of prey they killed for the shared larder. In celebration, Falk received these markings of Hircine's favor.\"—Fori, Keptu Scholar",
                            ["icon"] = "/esoui/art/icons/mount_keptubear.dds",
                            ["furnitureId"] = 7841,
                            ["id"] = 9445,
                            ["category"] = "Ursines",
                            ["hint"] = "",
                            ["name"] = "Keptu Bear",
                        },
                        [9442] = 
                        {
                            ["description"] = "Granted to the winner of the 2020 Tamriel Together Sweepstakes. After adding Larry, Duke of the Dance to your home, you can set him on a path.",
                            ["icon"] = "/esoui/art/icons/assistent_larry.dds",
                            ["furnitureId"] = 7840,
                            ["id"] = 9442,
                            ["category"] = "Houseguests",
                            ["hint"] = "",
                            ["name"] = "Larry, Duke of the Dance",
                        },
                        [1138] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Maw of Lorkhaj.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialgrevioustwilight001.dds",
                            ["furnitureId"] = 4361,
                            ["id"] = 1138,
                            ["category"] = "Undaunted Busts",
