                        [1135] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Blessed Crucible.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantroll001.dds",
                            ["furnitureId"] = 4358,
                            ["id"] = 1135,
