                        },
                        [9406] = 
                        {
                            ["description"] = "Template Description",
                            ["icon"] = "/esoui/art/icons/icon_missing.dds",
                            ["furnitureId"] = 7669,
                            ["id"] = 9406,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Shock Theodolite",
                        },
                        [5213] = 
                        {
                            ["description"] = "Lord of the Nightmare Pack, this night-black Wolf mount has burning paws and flames hissing from its face and tail; can anyone doubt that its origin must be Mehrunes Dagon's plane of the Deadlands?",
                            ["icon"] = "/esoui/art/icons/mounticon_wolf_nightmare.dds",
                            ["furnitureId"] = 5520,
                            ["id"] = 5213,
                            ["category"] = "Canines",
                            ["hint"] = "",
                            ["name"] = "Packlord Nightmare Wolf",
                        },
                        [5214] = 
                        {
                            ["description"] = "\"Be scared—be very scared!\" say this pup's big fiery eyes. \"Please?\" But no matter how much it tries to frighten like a grown-up Nightmare Wolf, this flaming fuzzball is still completely adorable.",
                            ["icon"] = "/esoui/art/icons/pet_199_nightmarepup.dds",
                            ["furnitureId"] = 5533,
                            ["id"] = 5214,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Nightmare Wolf Pup",
                        },
                        [5219] = 
                        {
                            ["description"] = "Summerset's Salamanders are amphibians that, when threatened, defend themselves with an impressive array of elemental powers. The bright orange Lava Line on this breed is an indicator of its reliance on natural Flame magic.",
                            ["icon"] = "/esoui/art/icons/pet_202_lavaline.dds",
                            ["furnitureId"] = 5448,
                            ["id"] = 5219,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Lava Line Salamander",
                        },
                        [1125] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Cradle of Shadows.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranhoarvoardaedra001.dds",
                            ["furnitureId"] = 4348,
                            ["id"] = 1125,
                            ["category"] = "Undaunted Busts",
                            ["hint"] = "Awarded for completing Veteran Cradle of Shadows.",
                            ["name"] = "Bust: Velidreth, Lady of Lace",
                        },
                        [5222] = 
                        {
                            ["description"] = "If you're looking for a warm and fuzzy companion animal to cuddle with, don't start with the Crested Reef Viper. But if what you want is an intimidating reptilian monster that says \"Don't mess with me, city boy,\" this is the ophidian follower for you.",
                            ["icon"] = "/esoui/art/icons/pet_195_seaadder-yellow.dds",
                            ["furnitureId"] = 5446,
                            ["id"] = 5222,
                            ["category"] = "Exotic",
                            ["hint"] = "",
                            ["name"] = "Crested Reef Viper",
                        },
                        [5225] = 
                        {
                            ["description"] = "Most inhabitants of Skyrim hate and loathe necromancy, but those Nords who do stoop to raising the dead tend to go all in, wallowing in death and its symbols. It was no doubt such Nord necromancers who bred the skull-faced Death Mask Sabre Cats as mounts.",
                            ["icon"] = "/esoui/art/icons/mounticon_deathmasksabrecat.dds",
                            ["furnitureId"] = 5445,
                            ["id"] = 5225,
                            ["category"] = "Felines",
                            ["hint"] = "",
                            ["name"] = "Death Mask Sabre Cat",
                        },
                        [5226] = 
                        {
                            ["description"] = "It's no surprise that in the Alik'r Desert, where blooming flowers are rare and prized, that Shorn Camels tattooed with Floral designs are well loved and popular. Covering them with flower designs is even said to make them less ornery!",
                            ["icon"] = "/esoui/art/icons/mounticon_camel_floraltattoo.dds",
                            ["furnitureId"] = 5440,
                            ["id"] = 5226,
                            ["category"] = "Camelids",
                            ["hint"] = "",
                            ["name"] = "Floral Tattoo Shorn Camel",
                        },
                        [1131] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Fungal Grotto II.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veteranspiderdaedra001.dds",
