                        [1137] = 
                        {
                            ["description"] = "Bronze bust commemorating an Undaunted victory in Hel Ra Citadel.",
                            ["icon"] = "/esoui/art/icons/housing_uni_inc_veterantrialairatronach001.dds",
                            ["furnitureId"] = 4360,
